(window.GIM_TS=window.GIM_TS||{})["Menachot.7"]={"from":168,"a":[["\u0003ואם הביא\u0004 למקדש משמן אנפקטן — הריהו \u0003פסול\u0004 למנחות, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 \u0003ואם הביא\u0004 — \u0003כשר, מפני ש\u0004אין \u0003הוא\u0004 שמנו של הפרי, אלא ה\u0003שרף\u0004 היוצא ממנו. הרי שאין הוא נחשב לשמן!","\u0003אמר רב יוסף\u0004 בתירוץ הסתירה שבין משנתנו לברייתא: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן שתי שיטות תנאים הן בהגדרת שמן אנפקטן, \u0003הא\u0004 \u0005[זו],\u0006 משנתנו הסבורה ששמן הוא — הריהי כשיטת \u0003ר' חייא,\u0004 ואילו \u0003הא\u0004 \u0005[זו]\u0006 הברייתא הסבורה שהוא שרף בלבד — הריהי כשיטת \u0003ר' שמעון בר\u0004 \u0005[בן]\u0006 \u0003רבי\u0004 יהודה הנשיא. שכך היו שני אלה נוהגים בשמן האנפקטן: \u0003ר' חייא זריק ליה\u0004 \u0005[היה זורק אותו],\u0006 ולא היה משתמש בו כלל, שלדעתו אינו שמן. \u0003ו\u0004אילו \u0003ר' שמעון בר רבי\u0004 לא היה משליך אותו, אלא היה \u0003מטבל ביה\u0004 \u0005[בו]\u0006 את מאכלו, כדרך שנוהגים בשמן מאכל. \u0003וסימניך\u0004 לזכור איך נהג כל אחד מן החכמים הללו הוא: דווקא ה\u0003עשירים,\u0004 כר' שמעון בנו של ר' יהודה הנשיא, \u0003העשיר, הם ה\u0004\u0003מקמצין\u0004 (החוסכים), שהוא זה שלא השליך את שמן האנפקטן, והיה משתמש בו.","ומתוך שעוסקים בענייני השמן השונים, מביאים עוד: \u0003נאמר בתמרוקי הנשים \"...כי כן ימלאו ימי מרוקיהן\u0004 \u0003ששה חדשים בשמן המור\u0004 וששה חדשים בבשמים ובתמרוקי הנשים\" (אסתר ב, יב). ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"שמן המור\"? רב הונא בר חייא אמר:\u0004 הוא הנקרא עתה \u0003סטכתא. ר' ירמיה בר אבא אמר:\u0004 \"שמן המור\" הריהו \u0003שמן\u0004 הבא מן ה\u0003זית שלא הביא\u0004 (הבשיל) \u0003שליש\u0004 גידולו.","ובעקבות דברי ר' ירמיה בר אבא ש\"שמן המור\" הוא שמן הבא מזית שלא הביא שליש, מביאים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא האומרת \u0005גם כן כך]\u0006 ששמן הבא מזית שלא הביא שליש הריהו שמן \u0005תמרוקים,\u0006 \u0003ר' יהודה אומר:\u0004 מהו שמן \u0003אנפקנון?\u0004 — \u0003שמן זית שלא הביא שליש. למה סכין אותו\u0004 על הגוף? מפני \u0003ש\u0004הוא \u0003משיר את השיער ומעדן את הבשר.\u0004","שנינו במשנתנו ש\u0003אין מביאין\u0004 שמן למנחות \u0003מן הגרגרין שנשרו במים\u0004 ולא מן הגרגרים הכבושים ולא מן השלוקים, ואם הביא מהם — פסול. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמן\u0004 הבא \u0003מן ה\u0004\u0003זית\u0004 שהיה \u0003כבוש\u0004 במלח ובחומץ, או שהיה \u0003שלוק\u0004 (מבושל), או שהיה \u0003שרוי\u0004 במים, \u0003ו\u0004כן שמן זה \u0003של שמרים, ו\u0004כן שמן \u0003של ריח רע\u0004 — \u0003לא יביא\u0004 מהם למנחות, \u0003ואם\u0004 עבר ו\u0003הביא\u0004 אחד מאלה — \u0003פסול.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004 עבר ו\u0003הקדישו\u0004 לאחד מהשמנים הללו למנחות, \u0003מהו\u0004 דינו \u0003שילקה עליו\u0004 כעובר על איסור תורה, ו\u0003משום\u0004 שהקדיש דבר שהוא \u0003בעל מום\u0004 (הפסול בגופו) להקרבה? וצדדי השאלה: האם \u0003כיון\u0004 ש\u0003פסול\u0004 שמן זה להקרבה \u0003כבעל מום דמי\u0004 \u0005[נחשב],\u0006 וילקה כשאר מקדיש בעל מום. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003אין בעל מום אלא בבהמה\u0004 הפסולה להקרבה, ולא בשאר דברים הפסולים להקרבה, לכן אינו לוקה על כך. ומעירים: שאלה זו לא נפתרה, ולכך \u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","\u0003שלשה\u0004 זמנים בשנה בהם מוסקים את ה\u0003זיתים הן, ובהן,\u0004 בכל אחד מן הזמנים הללו מפיקים \u0003שלשה\u0004 \u0003שלשה\u0004 סוגי \u0003שמנים,\u0004 ונמצא כי בסך הכל מופקים תשעה סוגי שמן בשנה אחת.","ומפרטים: מסיק \u0003הזית הראשון\u0004 כיצד הוא נעשה? בעל הזית \u0003מגרגרו\u0004 (קוטף זיתים בודדים) \u0003בראש הזית,\u0004 שזיתים אלה ממהרים להבשיל, משום שהם חשופים לקרני השמש. \u0003וכותש\u0004 אותם במכתשת \u0003ו\u0004לאחר מכן \u0003נותן\u0004 אותם \u0003לתוך הסל\u0004 העשוי נצרים דקים וביניהם חללים, וכך השמן ניגר מבעד לחללים לכלי שהסל נתון בתוכו. \u0003ר' יהודה אומר:\u0004 כי אין שמים את הזיתים שנכתשו בתוך הסל עצמו, אלא על \u0003סביבות\u0004 (דפנותיו, הסובבות) \u0003הסל,\u0004 שכן באופן זה השמן מזוקק ונקי יותר. \u0003זה\u0004 הוא השמן \u0003ה\u0004\u0003ראשון\u0004 המופק מהמסיק הראשון, והוא המובחר מכל השמנים.","לאחר שתם השמן לצאת מהזיתים הכתושים שבסל, בעל הזיתים \u0003חזר וטוען\u0004 על הזיתים \u0003בקורה\u0004 הניתנת עליהם, ומתוך הלחץ שהיא לוחצת אותם ניגר שמן נוסף אל הכלי שמתחת לסל. ואף בזאת חולק \u0003ר' יהודה\u0004 ה\u0003אומר\u0004 כי אין מעמיסים על הזיתים הכבושים קורה (שלחצה רב, וגורם להוצאת שמן שאינו נקי), אלא היו מעמיסים על הזיתים \u0003באבנים\u0004 — ו\u0003זה\u0004 השמן היוצא מהם הוא השמן ה\u0003שני\u0004 מזיתי המסיק הראשון.","ולאחר מכן \u0003חזר\u0004 ולקח את הזיתים שנכבשו במכתשת ונלחצו, \u0003וטחן\u0004 אותם בריחיים, לפורר את הזיתים ולאפשר לשארית השמן שבתוכם לצאת החוצה, \u0003וטען\u0004 על הזיתים הללו קורה — ו\u0003זה\u0004 השמן היוצא מאלה הריהו השמן ה\u0003שלישי\u0004 מזיתי המסיק הראשון.","מבין שלושת השמנים הללו, השמן \u0003הראשון\u0004 — כשר \u0003ל\u0004הדלקת ה\u0003מנורה\u0004 שבמקדש, שנאמר בו \"שמן זית זך\" (ויקרא כד, ב), \u0003והשאר\u0004 (שני השמנים האחרים) — כשרים \u0003למנחות.\u0004","כיצד נעשה המסיק \u0003השני? מגרגרו\u0004 מהזיתים הנמצאים \u0003ב\u0004זית שבקירבת \u0003ראש הגג\u0004 של ביתו. שזיתים אלה מתבשלים מאוחר יותר מזיתי המסיק הראשון, \u0003וכותש\u0004 אותם במכתשת, \u0003ונותן\u0004 אותם \u0003לתוך הסל.\u0004 ואילו \u0003ר' יהודה אומר:\u0004 אין נותנים את הזיתים בתוך הסל, אלא ב\u0003סביבות\u0004 (דפנות) \u0003הסל\u0004 — \u0003ו\u0004\u0003זה\u0004 השמן היוצא מהזיתים הריהו השמן ה\u0003ראשון\u0004 של זיתי המסיק השני.","ולאחר מכן \u0003טוען\u0004 את הזיתים הכתושים \u0003בקורה, ו\u0004אילו \u0003ר' יהודה אומר\u0004 שאין מעמיסים על הזיתים אלא \u0003באבנים\u0004 — ושמן \u0003זה\u0004 הוא השמן ה\u0003שני\u0004 מזיתי המסיק השני.","ולאחר מכן \u0003חזר וטחן\u0004 בריחיים את הזיתים שכבר יצא מהם שמן בקורה, ושב \u0003וטען\u0004 אותם בקורה — ושמן \u0003זה\u0004 הוא השמן ה\u0003שלישי\u0004 של זיתי המסיק השני.","ואף דינם של שלושת שמנים אלה, כדין שמני המסיק הראשון: השמן \u0003הראשון\u0004 — כשר \u0003למנורה, והשאר\u0004 — כשרים \u0003למנחות.\u0004","והשמן מהמסיק ה\u0003שלישי:\u0004 לאחר שנאספו הזיתים מן העץ, בעל הזית \u0003עוטנו\u0004 (מניח את יבול הזיתים במעטן — הכלי בו מתרככים הזיתים לקראת כתישתם) \u0003בבית הבד,\u0004 ושוהה שם יבול הזיתים הזה \u0003עד שילקה\u0004 (יתרכך), \u0003ו\u0004לאחר מכן הריהו \u0003מעלהו\u0004 מתוך המעטן \u0003ומנגבו\u0004 (מייבשו) מן המוהל שעליו. ומשום שיש ריח רע בזיתים הללו ששהו במעטן, נעשית פעולה זו לא בתוך הבית אלא \u0003בראש הגג.\u0004 ולאחר מכן הריהו \u0003כותש\u0004 את הזיתים הללו במכתשת, \u0003ונותן\u0004 אותם \u0003לתוך הסל,\u0004 שיצא השמן מנקבי הסל, אל הכלי הנמצא תחתיו. ואילו \u0003ר' יהודה אומר\u0004 שאין נותנים את הזיתים בתוך הסל, אלא ב\u0003סביבות\u0004 (דפנות) \u0003הסל\u0004 — \u0003ו\u0004\u0003זה\u0004 השמן היוצא מזיתים אלה הריהו השמן ה\u0003ראשון\u0004 במסיק השלישי.","ולאחר מכן הריהו נוטל את הזיתים הללו, \u0003ו\u0004\u0003טוען\u0004 אותם \u0003בקורה,\u0004 זו דעת חכמים, ואילו \u0003ר' יהודה אומר\u0004 שלא היה טוען אותם בקורה אלא \u0003באבנים\u0004 — ו\u0003זה\u0004 השמן היוצא מהם הוא השמן ה\u0003שני\u0004 של זיתי המסיק השלישי.","ולאחר מכן \u0003חזר\u0004 ונטל את הזיתים הללו \u0003וטחן\u0004 אותם בריחיים, ושב \u0003וטען\u0004 אותם בקורה — ושמן \u0003זה\u0004 היוצא מזיתים אלה הוא השמן ה\u0003שלישי\u0004 מזיתי המסיק השלישי.","ואף בדינם של שמנים אלה נקבע כי השמן \u0003הראשון\u0004 — כשר \u0003למנורה, והשאר\u0004 — כשרים \u0003למנחות.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 מהי הגירסה המדוייקת במשנה, האם \u0003\"מגרגרו\" תנן\u0004 \u0005[שנינו]\u0006 ומשמע הדברים: שקוטף זיתים בודדים, אותם שכבר הבשילו ביותר. \u0003או \"מגלגלו\" תנן\u0004 \u0005[שנינו],\u0006 ומשמע הדברים: שמניח \u0005את הפירות שבראש האילן כדי שיתבשלו יפה? ומציעים:\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו \u0003ממה\u0004 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]?\u0006 מה שנאמר בשמן המובא למנורה במקדש \u0003\"שמן זית\u0004 זך\" (שמות כז, כ) בא להורות, שיהא שמן זה \u0003מזיתו\u0004 (מזיתים בשלים כל כך, שהשמן יוצא מהם מעצמו בלא לחץ. \u0003מכאן\u0004 (מן הנאמר בכתוב זה) \u0003אמרו\u0004 חכמים בתיאור דרך העשיה הנכונה של השמן: יבול ה\u0003זית\u0004 ה\u0003ראשון\u0004 — \u0003מגלגלו בראש הזית, ו\u0004לאחר מכן הריהו \u0003כונסו\u0004 (מכניסו) \u0003לבית הבד, וטוחנו\u0004 לזיתים \u0003בריחים\u0004 (כדי לאפשר לשמן שבתוכם לזוב החוצה) \u0003ונותנו בסלין\u0004 והשמן זב מהם לכלי שהם נתונים בתוכו — ה\u0003שמן היוצא ממנו,\u0004 \u0003זה היה\u0004 השמן ה\u0003ראשון\u0004 הבא מהיבול הראשון.","ולאחר מכן \u0003טען\u0004 אותם \u0003בקורה\u0004 — ה\u0003שמן היוצא ממנו, זה היה\u0004 השמן ה\u0003שני\u0004 של היבול הראשון. \u0003ו\u0004לאחר מכן \u0003חזר ופרק\u0004 את הזיתים הללו מתוך הסלים, ו\u0003טחן\u0004 אותם שוב בריחיים, וחזר \u0003וטען\u0004 אותם בקורה או באבנים — \u0003זה היה\u0004 השמן ה\u0003שלישי\u0004 של היבול הראשון. השמן \u0003הראשון\u0004 — \u0003כשר\u0004 \u0003למנורה, והשאר\u0004 — \u0003למנחות\u0004 בלבד. \u0003וכן\u0004 הוא עושה ביבול ה\u0003זית\u0004 ה\u0003שני. ו\u0004אילו ביבול ה","\u0003זית\u0004 ה\u0003שלישי\u0004 כיצד הוא עושה? \u0003עוטנו\u0004 (מכניסו אל המעטן) הנמצא \u0003בבית הבד,\u0004 ומניחו שם \u0003עד שילקה\u0004 (שיתעפש ויתרכך), \u0003ו\u0004לאחר מכן הריהו \u0003מעלה\u0004 אותו \u0003לראש הגג, ועושה אותו\u0004 שם \u0003כמין תמרה\u0004 (ערימה), והוא מונח שם \u0003עד שיזובו מימיו\u0004 (הנוזלים שבו). \u0003ו\u0004אחר כך הריהו שב ו\u0003כונסו\u0004 (מכניסו) \u0003לבית הבד, ו\u0004בבית הבד הריהו \u0003טוחנו בריחים, ונותנו בסלין\u0004 — \u0003ו\u0004ה\u0003שמן היוצא ממנו, זה היה\u0004 השמן ה\u0003ראשון\u0004 של היבול השלישי.","אחר כך הוא \u0003טען\u0004 את הזיתים הללו \u0003בקורה\u0004 — ה\u0003שמן היוצא ממנו, זה היה\u0004 השמן ה\u0003שני\u0004 של היבול השלישי. ולאחר מכן \u0003פרק\u0004 את הזיתים מתוך הסל והקורה, ו\u0003חזר וטחן\u0004 אותם בריחיים, ושב \u0003וטען\u0004 אותם בקורה, כדי להוציא מהם את שארית השמן שבתוכם — ו\u0003זה היה\u0004 השמן ה\u0003שלישי\u0004 מן היבול השלישי. השמן \u0003הראשון\u0004 מהם — כשר \u0003למנורה, ו\u0004אילו \u0003השאר\u0004 — \u0003למנחות\u0004 בלבד.","שלא כדברי חכמים שאמרו כי בכל שלושת היבולים, היו טוחנים בתחילה את הזיתים כדי להוציא מהזיתים את השמן הראשון, \u0003ר' יהודה אומר\u0004 כי לצורך הוצאת השמן הראשון שבכל שלושת היבולים \u0003לא היה טוחנו בריחים, אלא\u0004 היה \u0003כותשו במכתשת. ו\u0004עוד חולק ר' יהודה על חכמים ואומר כי \u0003לא היה טוען\u0004 את הזיתים \u0003בקורה אלא באבנים. ו\u0004עוד חולק ר' יהודה על חכמים ואומר כי \u0003לא היה נותנו ב\u0004תוך ה\u0003סלין\u0004 עצמם, \u0003אלא לתוך סביבות הסל.\u0004 ומכאן פתרון לשאלה בנוסח המדויק של משנתנו, שהוא \"מגלגלו\".","ולאחר שהובאו דברי ברייתא זו, נפנים להקשות על דברי משנתנו: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 שכן זה ששנינו בדברי התנא הראשון שבמשנתנו שלצורך הוצאת השמן הראשון בשלושת היבולים היה \u0003כותש\u0004 ונותן לתוך הסל — כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 כשיטת \u0003ר' יהודה היא,\u0004 ולא כשיטת חכמים שבברייתא (האומרים שהיה טוחנם בריחיים). ואולם אחר כך שונים אנו בדברי התנא הראשון שבמשנתנו שמניחים את הזיתים ב\u0003תוך הסל,\u0004 ולא בדפנותיו, ואם כן \u0003אתאן\u0004 \u0005[באנו]\u0006 איפוא \u0003ל\u0004שיטתם של \u0003רבנן\u0004 \u0005[חכמים]\u0006 שבברייתא, ולא כר' יהודה!","ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 של משנתנו \u0003סבר לה כותיה בחדא ופליג עליה בחדא\u0004 \u0005[סבור הוא כמותו,\u0006 כר' יהודה, \u0005ב\u0006דבר \u0005אחד, וחולק עליו ב\u0006דבר \u0005אחד].\u0006","ולאחר שתוארו במשנה הקודמת תשעת השמנים, מגדירים את סדר חשיבותם: השמן \u0003הראשון שב\u0004מסיק ה\u0003ראשון\u0004 — \u0003אין למעלה\u0004 באיכותו \u0003הימנו\u0004 (ממנו). השמן \u0003השני שב\u0004מסיק ה\u0003ראשון, ו\u0004השמן \u0003הראשון שב\u0004מסיק ה\u0003שני\u0004 — \u0003שוין\u0004 בחשיבותם, והריהם איפוא מדרגה שניה של שמנים. השמן \u0003השלישי שב\u0004מסיק ה\u0003ראשון ו\u0004השמן \u0003השני שב\u0004מסיק ה\u0003שני ו\u0004כן השמן \u0003הראשון שב\u0004מסיק ה\u0003שלישי\u0004 — \u0003שוין\u0004 זה לזה בחשיבותם, והריהם איפוא מדרגה שלישית של השמנים. השמן \u0003השלישי שב\u0004מסיק ה\u0003שני ו\u0004השמן \u0003השני שב\u0004מסיק \u0003ה\u0004\u0003שלישי\u0004 — \u0003שוין\u0004 זה לזה, והריהם איפוא מדרגה רביעית של השמנים. ואילו השמן \u0003השלישי שב\u0004מסיק ה\u0003שלישי\u0004 — הוא בדרגה חמישית מכל השמנים הללו ו\u0003אין\u0004 שמן שהוא \u0003למטה\u0004 באיכותו \u0003הימנו.\u0004","ומעירים: למדנו כי למנחות מביאים מכל השמנים הללו, ואילו למנורה אין מביאים אלא מהשמן הראשון שבכל מסיק, ואולם \u0003אף כל המנחות היו בדין\u0004 (ראויות להילמד בקל וחומר) \u0003שיטענו\u0004 (שיחוייבו) ב\u0003שמן זית זך,\u0004 וכשמן המנורה, ומקל וחומר: ו\u0003מה\u0004 ה\u0003מנורה\u0004 הקלה \u0003ש\u0004השמן בה \u0003אינה\u0004 מיועדת \u0003לאכילה\u0004 של המזבח — \u0003טעונה\u0004 (חייבת) ב\u0003שמן זית זך, מנחות\u0004 החמורות \u0003שהן\u0004 מיועדות \u0003לאכילה\u0004 של המזבח — \u0003אינו דין שיטענו שמן זית זך!\u0004 אולם \u0003לכך\u0004 \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \"...שמן זית \u0003זך כתית למאור\u0004 להעלות נר תמיד\" (שמות כז, ב) — לומר: כתית נדרש רק למאור, לנרות המנורה, \u0003ואין זך כתית\u0004 נדרש \u0003למנחות.\u0004"],["שנינו במשנתנו בסדר החשיבות של תשעת השמנים המנויים בה, כי השמן השני שבמסיק הראשון והשמן הראשון שבמסיק השני \u0003שוין\u0004 בחשיבותם. ומקשים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 אין הם שוים, שכן כבר \u0003אמרת\u0004 לפני כן, במשנה הקודמת, כי רק השמן ה\u0003ראשון\u0004 שבכל אחת משלושת המסיקים הוא הכשר \u0003למנורה, ו\u0004אילו \u0003השאר\u0004 אינם כשרים למנורה אלא \u0003למנחות\u0004 בלבד, ונמצא איפוא שהשמן השני מהמסיק הראשון — אינו כשר למנורה, בעוד שהשמן הראשון מהמסיק השני כשר למנורה! \u0003אמר רב נחמן בר יצחק\u0004 בתשובה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שוין\"?\u0004 שהם \u0003שוין ל\u0004ענין \u0003מנחות,\u0004 שאף מן הראשון שבשני יכול להביא למנחות.","עוד שנינו במשנתנו ש\u0003אף כל המנחות היו\u0004 ראויות להילמד \u0003בדין\u0004 (במידת קל וחומר) שאין מביאים להן אלא מן השמן הראשון, אלא שלמדנו מן הכתוב \"שמן זית זך כתית למאור\" (שמות כז, כ) שאין דין זה נוהג אלא בשמן למנורה. ועוד בדרשות על כתוב זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר בכתוב: \"שמן זית \u0003זך\"\u0004 — \u0003אין\u0004 משמעות המלה \u0003\"זך\" אלא נקי,\u0004 שעל שמן זה להיות נקי, כגון זה שיצא מן הזיתים מעצמו. \u0003ר' יהודה אומר:\u0004 מה שנאמר בכתוב בענין השמן \u0003\"כתית\"\u0004 — \u0003אין\u0004 משמעות המלה \u0003\"כתית\" אלא\u0004 זה שהוא \u0003כתוש\u0004 במכתשת. ואין בכלל זה השמן היוצא מזיתים שנטחנו בריחיים.","ומעתה יש לדון: \u0003יכול יהא\u0004 הדין ש\u0003שמן\u0004 \u0003זך כתית\u0004 \u0003פסול למנחות?\u0004 לכך \u0003תלמוד לומר\u0004 במנחה הבאה עם קרבן התמיד \u0003\"ועשרון סלת בלול בשמן כתית\"\u0004 (שם כט, מ), שאף השמן הבא בשאר מנחות יכול להיות שמן כתית. וממשיכים לדון, \u0003אם כן\u0004 הוא הדין, שאף השמן של שאר המנחות הריהו שמן כתית, \u0003מה תלמוד לומר\u0004 בשמן המנורה \u0003\"למאור\"\u0004 (\"שמן זית זך כתית למאור\"), שהרי אין זה דין המיוחד דווקא למנורה? \u0003אלא\u0004 ללמדנו שהשמן הבא למאור בא רק משמן כתית, ואולם השמן הבא למנחות, אף שאפשר להביאו גם כן משמן כתית, הריהו כשר גם משאר השמנים. וטעם הדבר — \u0003מפני החיסכון\u0004 בממון.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 ענין\u0005]\u0006 \u0003\"חיסכון\"\u0004 יש כאן, בכך שהותרו שאר המנחות להיות מובאות אף משמן שאינו כתית? \u0003אמר ר' אלעזר: התורה חסה על ממונן של ישראל,\u0004 וכיון שמנחות מובאות לרוב, לא הצריכה אותם להביאן משמן \u0003מובחר ויקר שכזה.\u0004","ועוד בענין שמן המנורה. על הנאמר בענין מצות הדלקת המנורה במקדש \u0003\"צו את בני ישראל ויקחו אליך שמן זית זך\u0004 כתית למאור להעלות נר תמיד\" (ויקרא כד, ב), \u0003אמר ר' שמואל בר נחמני:\u0004 לשון המיעוט \u0003\"אליך\"\u0004 בא להורות, שכך אמר הקדוש ברוך הוא לעם ישראל: לך ובעבורך נועדה מצוה זו, להראות חיבתך לפני, \u0003ולא לי,\u0004 כי \u0003לא לאורה\u0004 של המנורה \u0003אני צריך.\u0004","וכן גם בענין מצוות העמדת \u0003שלחן\u0004 לחם הפנים \u0003בצפון\u0004 ההיכל, \u0003ומנורה\u0004 \u0003בדרום\u0004 ההיכל, בריחוק זה מזה — \u0003אמר ר' זריקא, אמר ר' אלעזר,\u0004 שכך אמר הקדוש ברוך הוא לעם ישראל: \u0003לא לאכילה\u0004 של הלחם המונח על שולחן הפנים \u0003אני צריך, ולא לאורה\u0004 של המנורה \u0003אני צריך,\u0004 ולכך אין השולחן עומד בצד המנורה, וכמנהג בני אדם הנותנים את שולחן אכילתם במקום שיש בו אור.","וכיוצא בדבר בענין הנאמר בבנין בית המקדש של שלמה \u0003\"ויעש לבית חלוני שקפים אטמים\"\u0004 (מלכים א ו, ד) — \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בפירוש הדברים, שכך אמר הקדוש ברוך הוא: עשו את פתחי הבית \u0003שקופין\u0004 (צרים) \u0003מבפנים\u0004 (כלפי פנים), \u0003ואטמים\u0004 (רחבים) \u0003מבחוץ\u0004 (כלפי חוץ), ושלא כמנהג הרווח בבנין בתים בהם הפתח כלפי חוץ צר והולך ומתרחב כלפי פנים, שכן \u0003לא לאורה אני צריך.\u0004","ועוד בדרשות חכמים על הכתוב בענין המנורה במקדש. מה שהזכיר הכתוב (בציווי ההדלקה) \u0003\"מחוץ לפרכת העדות באהל מועד\u0004 יערוך אותו אהרן מערב עד בקר לפני ה' תמיד...\" (ויקרא כד, ב) לשון \"עדות\", הרי זה בא להורות כי הדלקה זו \u0003עדות הוא לכל באי עולם שהשכינה שורה בישראל.\u0004","\u0003ואם תאמר:\u0004 שציוה הקדוש ברוך הוא על ההדלקה כי \u0003לאורה\u0004 של מנורה \u0003אני צריך\u0004 — אין לומר כן, \u0003והלא כל ארבעים שנה שהלכו\u0004 בני \u0003ישראל במדבר\u0004 סיני עד כניסתם לארץ ישראל \u0003לא הלכו אלא לאורו\u0004 של הקדוש ברוך הוא בעמוד האש אשר האיר לפניהם את הלילה, ומה צורך לו באור המנורה! \u0003אלא עדות הוא לכל באי עולם שהשכינה שורה בישראל.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 הדבר בו מתבטאת \u0003עדותה\u0004 של המנורה על כך? \u0003אמר רבא: זה נר מערבי\u0004 שבמנורה, \u0003ש\u0004היו \u0003נותנין בה,\u0004 בנר המערבי, כמות \u0003שמן\u0004 שהיא \u0003כנגד\u0004 (בדומה) לכל שאר \u0003חברותיה\u0004 (הנרות האחרים) ולא יותר, \u0003ו\u0004עם זאת, בערבו של כל יום נר זה היה הנר הראשון שהודלק, \u0003ו\u0004\u0003ממנה היה\u0004 הכהן \u0003מדליק\u0004 את המנורה, \u0003ו\u0004בבוקר כשהיה הכהן מיטיב את הנרות, \u0003בה היה\u0004 הכהן \u0003מסיים,\u0004 שכן אף שהודלקה ראשונה היתה כבה אחרונה. וזהו נס קבוע שהיה במקדש.","\u0003מאין היו מביאין את היין\u0004 לנסכים? יינם של המקומות הנקראים \u0003בשם\u0004 \u0003קדוחים ועטולין\u0004 הוא \u0003אלפא\u0004 (הראשון והמובחר) \u0003ל\u0004כל \u0003יין\u0004 אחר, וממנו ראוי להביא לכתחילה לנסכים. \u0003שניה להן\u0004 בטיב היין הם המקומות הנקראים \u0003בית רימה ובית לבן בהר וכפר סיגנא\u0004 הנמצאת \u0003בבקעה.\u0004 ומבהירים: אמנם \u0003כל\u0004 ה\u0003ארצות היו כשרות\u0004 להביא מהן את היין, \u0003אלא מיכן\u0004 (מהמקומות המנויים למעלה) \u0003היו מביאין\u0004 לכתחילה.","\u0003אין מביאין\u0004 יין לנסכים \u0003לא מבית הזבלים\u0004 (כרם המדושן בזבל) \u0003ולא מבית השלחים\u0004 (כרם המושקה בידי אדם) \u0003ולא ממה\u0004 (מגפנים) \u0003שנזרע ביניהן\u0004 זרעים שונים. ואין זה אלא לכתחילה, \u0003ו\u0004אולם \u0003אם הביא\u0004 — יין זה \u0003כשר\u0004 לנסכים. וכן \u0003אין מביאין\u0004 לכתחילה לנסכים יין \u0003הליסטיון\u0004 (העשוי מענבים שהתמתקו ביותר על ידי השמש), \u0003ו\u0004אולם \u0003אם הביא\u0004 — הריהו \u0003כשר. אין מביאין\u0004 לנסכים מן היין ה\u0003ישן\u0004 שעברה עליו שנה, אלו \u0003דברי רבי, ו\u0004אילו \u0003חכמים מכשירין\u0004 להבאה לנסכים מן היין הישן. \u0003אין מביאין\u0004 לנסכים \u0003לא\u0004 מהיין \u0003ה\u0004\u0003מתוק ולא מעושן\u0004 (שנעשה מענבים שהעלו עשן מתחתיהם על מנת להיטיב את טעמם), \u0003ולא\u0004 מן היין ה\u0003מבושל\u0004 באש. \u0003ו\u0004בשלושת יינות אלה, אף בדיעבד, \u0003אם הביא\u0004 — הריהו \u0003פסול\u0004 לנסכים. \u0003ואין מביאין מן הדליות\u0004 (גפנים המודלות על גבי עמודים או עצים), \u0003אלא מן\u0004 הגפנים \u0003הרגליות\u0004 (השטוחות על פני הקרקע), שפירותיהן משובחים יותר. \u0003ו\u0004מביאים \u0003מן הכרמים העבודין\u0004 (המעובדים, שעודרים תחת הגפנים פעמיים בשנה).","\u0003ו\u0004את היין הבא לנסכים \u0003לא כונסין\u0004 (מכניסים) \u0003אותו בחצבין\u0004 (כדים) \u0003גדולים\u0004 שכן בכך נפגם טיבו של היין, \u0003אלא בחביות קטנות. ו\u0004אף בחביות אלה \u0003אינו ממלא את החבית עד פיה,\u0004 אלא משאיר מקום פנוי. וטעם הדבר — \u0003כדי שיהא ריחו\u0004 של היין \u0003נודף\u0004 (מתפשט בחלל החבית, ונאסף אל מתחת למגופת החבית).","ואף ביין הנמצא בחבית קטנה, \u0003אינו מביא\u0004 לנסכים \u0003מ\u0004היין הנמצא ב\u0003פיה\u0004 של החבית — \u0003מפני\u0004"],["\u0003הקמחין\u0004 (אבק לבן של עובש יין, הדומה לקמח, הצף על פני היין) \u0003ו\u0004כן \u0003לא\u0004 מביאים \u0003מ\u0004היין הנמצא ב\u0003שוליה\u0004 (תחתיתה) של החבית. וטעם הדבר — \u0003מפני השמרים\u0004 השוקעים אל תחתית החבית. \u0003אלא מביא\u0004 \u0003מ\u0004היין הנמצא ב\u0003שלישה\u0004 האמצעי של החבית, כלומר, \u0003מאמצעה\u0004 של החבית.","\u0003כיצד הוא בודק\u0004 את היין? \u0003הגזבר יושב\u0004 בצד חבית היין הנבדקת, \u0003ו\u0004עוקב אחר הוצאת היין מהחבית, כאשר \u0003הקנה\u0004 (אמת מידה) נתון \u0003בידו,\u0004 ואם \u0003ראה הגזבר שהיין היוצא מהחבית\u0004 \u0003זרק\u0004 (מושך עמו בכח) גם \u0003הגיר\u0004 החלק הלבן הצף על פני השמרים — מייד \u0003הקיש\u0004 הגזבר \u0003בקנה\u0004 שבידו, כסימן שיש לסגור את ברז החבית, ולא למשוך ממנה עוד יין לנסכים. \u0003ר' יוסי בר' יהודה אומר:\u0004 יין \u0003שיש בו קמחין\u0004 — הריהו \u0003פסול\u0004 כולו להבאה לנסכים, וטעם הדבר — \u0003ש\u0004כן \u0003נאמר\u0004 בדין הקרבנות \u0003\"...תמימים יהיו לכם\"\u0004 (במדבר כח, יט), וממשיך הכתוב ואומר בפסוק שלאחריו \u0003\"ומנחתם\u0004 סלת בלולה...\" (שם כ), ועוד נאמר לאחר מכן \"מלבד עולת התמיד ומנחתו תעשו \u0003תמימים יהיו לכם ונסכיהם\"\u0004 (שם לא). שמפסוקים אלה למדים כי כקרבנות עצמם אף הסולת והשמן הבאים למנחות, והיין הבא לנסכים, שהם צריכים להיות בתכלית השלמות (\"תמימים\"). ואילו יין זה שעלו בו קמחים — אינו \"תמים\", ולכך הריהו פסול.","","שנינו במשנתנו כי \u0003אין מביאין\u0004 יין לנסכים \u0003לא\u0004 מהיין ה\u0003מתוק ולא\u0004 מהיין ה\u0003מבושל ולא\u0004 מהיין ה\u0003מעושן, ואם\u0004 עבר ו\u0003הביא\u0004 — הרי זה \u0003פסול\u0004 להקרבה. ושואלים על כך: \u0003והא קתני רישא\u0004 \u0005[והרי הוא\u0006 התנא עצמו \u0005שנה בראש,\u0006 לפני כן במשנה\u0005]\u0006 כי \u0003אין מביאין\u0004 לנסכים \u0003את הליסטיון\u0004 שהוא יין מתוק, \u0003ו\u0004אולם בדיעבד \u0003אם הביא\u0004 — \u0003הרי זה\u0004 \u0003כשר! אמר רבינא:\u0004 אכן אף הליסטיון פסול לנסכים גם בדיעבד, ויש לתקן גירסת משנתנו ו\u0003כרוך\u0004 (צרף) את דין הליסטיון \u0003ותני\u0004 \u0005[ושנה]\u0006 אותו עם דינם של היין המתוק והמעושן והמבושל, שכל אלה אף בדיעבד פסולים. \u0003רב אשי אמר\u0004 תירוץ אחר: \u0003חוליא דשימשא\u0004 \u0005[מתיקות של שמש],\u0006 כזו שיש בהליסטיון — \u0003לא מאיס\u0004 \u0005[אינה מאוסה],\u0006 ולכן בדיעבד הוא כשר, ואולם טעם \u0003חוליא דפירא\u0004 \u0005[מתיקות של פרי]\u0006 שמוסיפים בו דברים — הריהו \u0003מאיס\u0004 \u0005[מאוס]\u0006 משום שיש בו טעם אחר, ולכך יין זה פסול אף בדיעבד. עוד שנינו במשנתנו כי \u0003אין מביאין\u0004 לנסכים מן היין ה\u0003ישן,\u0004 אלו הם \u0003דברי רבי, ו\u0004אילו \u0003חכמים מכשירין.\u0004 ובענין זה \u0003אמר חזקיה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי?\u0004 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין \u0005הנסכים \"ונסכיהם חצי ההין יהיה לפר ושלישית ההין לאיל ורביעית ההין\u0006 \u0003לכבש יין...\"\u0004(שם, יד), והדגיש הכתוב \"לכבש יין\" לדמות את היין לכבש: \u0003מה כבש\u0004 הבא לקרבן אינו אלא זה שהוא \u0003בן\u0004 (בתוך) \u0003שנתו\u0004 הראשונה, \u0003אף יין\u0004 הבא לנסכים אינו אלא זה שהוא \u0003בן שנתו,\u0004 ולא הישן.","","","ומקשים על הסבר זה: \u0003אי\u0004 \u0005[אם]\u0006 כך הוא, תאמר אף: \u0003מה כבש בן שתי שנים\u0004 (בשנתו השנית, משעה שאין הוא בכלל \"בן שנתו\") — הריהו \u0003פסול\u0004 להקרבה, אף בדיעבד, \u0003אף יין בן שתי שנים\u0004 (בשנתו השנית), שהוא בכלל \"ישן\" — הריהו \u0003פסול\u0004 אף בדיעבד! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי אכן \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן\u0006\u0003]\u0004 שאף בדיעבד הריהו פסול, \u0003ו\u0004אולם אין לומר כך, שכן \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]\u0006 מפורשת האומרת ש\u0003יין בן שתי שנים\u0004 — לכתחילה \u0003לא יביא\u0004 לנסכים, \u0003ו\u0004אולם \u0003אם\u0004 עבר ו\u0003הביא\u0004 — הריהו \u0003כשר.\u0004 ומחזקים את השאלה: והרי \u0003ברייתא זו היא כשיטת רבי, שכן\u0004 \u0003מאן\u0004 \u0005[מי]\u0006 התנא ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר\u0004 שיין ישן \u0003לא יביא?\u0004 הלוא זה \u0003רבי\u0004 בשיטתו במשנתנו, \u0003וקאמר\u0004 \u0005[והוא אמר]\u0006 עוד בברייתא ש\u0003אם הביא\u0004 — \u0003כשר! אלא אמר רבא: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 לשיטת \u0003רבי\u0004 שאין מביאים לכתחילה מן היין הישן — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בתיאור היין המשובח (שמפני סכנותיו \u0005מזהירנו הכתוב)\u0006 \u0003\"אל תרא יין כי יתאדם\"\u0004 (משלי כג, כט—ל). הרי איפוא שהיין האדום הוא המשובח, ואין אדמימות זו מצויה ביין אלא בשנתו הראשונה.","","שנינו במשנה בדין היין לנסכים, ש\u0003אין מביאין לא מן הדליות\u0004 אלא מן הרוגליות, ומן הכרמים העבודים. ובענין זה של כרמים העבודים, מביאים עוד מה ש\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: אין מביאים יין לנסכים אלא מ\u0003כרמים העבודים פעמים בשנה\u0004 ולא פעם אחת.","ומביאים כי \u0003רב יוסף הוה ליה קרנא דפרדיסא דרפיק ביה טפי ריפקא\u0004 \u0005[היתה לו חלקת פרדס,\u0006 כרם, \u0005שעדר בה עידור יתר],\u0006 ששב ועדר בה, \u0003ועבד\u0004 \u0005[ועשה,\u0006 הניב\u0005]\u0006 אותו פרדס ענבים משובחים ביותר, שעשו מהן \u0003חמרא\u0004 \u0005[יין]\u0006 כה חזק, שניתן היה לשתיה רק באופן \u0003דדרי מיא\u0004 \u0005[שמזגו\u0006 בו \u0005מים]\u0006 בכמות שהיא \u0003על חד תרין\u0004 \u0005[על אחת שתיים,\u0006 פי שנים\u0005]\u0006 מכמות המים הנמזגת ליין רגיל.","עוד שנינו במשנתנו, ש\u0003לא היו כונסין אותן,\u0004 את היין לנסכים \u0003בחצבין גדולים\u0004 אלא בחביות קטנות, שיישמר טעמן. ובעניינן של חביות קטנות אלה מביאים מה ש\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: המדובר ב\u0003חביות כדיות\u0004 (כעין הכדים) הללו ה\u0003לודיות\u0004 (הבאות מהעיר לוד), \u0003ובינוניות\u0004 הן בגודלן.","ועוד נמסר בהנהגה הנכונה ביין המובא לנסכים, ש\u0003אין מניחין אותן,\u0004 את חביות היין הללו, במקום אחד ובאופן שהן נמצאות \u0003שתים שתים\u0004 (אחת על גבי חברתה), \u0003אלא\u0004 מניח כל \u0003אחת\u0004 ו\u0003אחת\u0004 מהחביות בנפרד.","ובדרך בדיקת היין שנינו במשנתנו \u0003כיצד\u0004 היה הגזבר שבמקדש \u0003בודק\u0004 את היין, שאין בו קמחים ושמרים? ה\u0003גזבר\u0004 היה \u0003יושב\u0004 בצד חבית היין הנבדקת, \u0003ו\u0004עוקב אחר הוצאת היין מהחבית, כאשר ה\u0003קנה\u0004 (אמת מידה) נתון \u0003בידו,\u0004 ואם ראה הגזבר שהיין היוצא מהחבית \u0003זרק\u0004 (מושך עמו בכח) גם \u0003הגיר\u0004 (החלק הלבן הצף על פני השמרים) — מייד הגזבר \u0003הקיש בקנה\u0004 שבידו, והרי זה כסימן שיש לסגור את ברז החבית, ולא למשוך ממנה עוד יין, שכן אין יין זה כשר לנסכים. ובענין זה \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא כתוספת ביאור לדברי משנתנו: הכוונה היא שראה הגזבר שהיין \u0003זרק\u0004 את \u0003הגיר של שמרים,\u0004 אז ה\u0003גזבר הקיש בקנה.\u0004","ושואלים: מדוע הגזבר מקיש בקנה, \u0003ולימא ליה מימר\u0004 \u0005[ושיאמר לו,\u0006 לשואב היין מהחבית ב\u0005אמירה]\u0006 לסתום את החבית! \u0005ומשיבים: עדיף שהדבר ייעשה לא בדיבור. והרי זה\u0006 \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן,\u0004 שכן \u0003אמר ר' יוחנן: כשם שהדיבור\u0004 (בקול נעימה) הריהו \u0003יפה\u0004 (מועיל) \u0003ל\u0004ריח ה\u0003בשמים,\u0004 \u0003כך\u0004 ה\u0003דיבור\u0004 הריהו \u0003רע\u0004 (מזיק) \u0003ליין,\u0004 ולכן נמנע הגזבר מלדבר סמוך לו. שנינו במשנתנו ש\u0003ר' יוסי בר ר' יהודה אומר\u0004 כי יין שיש בו קמחים פסול לנסכים. ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן:\u0004 אדם שעבר ו\u0003הקדישו\u0004 ליין שכזה לנסכים, \u0003מהו\u0004 דינו לענין זה \u0003שילקה עליו\u0004 כעובר על איסור תורה, ו\u0003משום\u0004 שהקדיש דבר שהוא \u0003בעל מום\u0004 (הפסול בגופו) להקרבה? וצדדי השאלה: האם \u0003כיון\u0004 ש\u0003פסול\u0004 הוא יין זה להקרבה \u0003כבעל מום\u0004 הוא \u0003דמי\u0004 \u0005[נחשב],\u0006 וילקה על הקדשתו זו, כשאר מקדיש בעל מום. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003אין\u0004 דין \u0003בעל מום אלא בבהמה\u0004 הפסולה להקרבה, ולא בשאר דברים הפסולים להקרבה, ולכן אינו לוקה על כך. ומעירים: שאלה זו לא נפתרה, ולכך \u0003תיקו\u0004 \u0005[תעמוד,\u0006 תישאר\u0005]\u0006 במקומה.","","ובסיכומו של הפרק בו נידונו דיני הסולת והשמן והיין המובחרים, מביאים עוד בעניינם של בעלי החיים המובחרים לקרבנות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003ה\u0004\u0003אלים\u0004 המובחרים ביותר — אלה הבאים \u0003ממואב;\u0004 ה\u0003כבשים\u0004 המובחרים ביותר — אלה הבאים \u0003מחברון;\u0004 ה\u0003עגלים\u0004 המובחרים ביותר — אלה הבאים \u0003משרון;\u0004 ה\u0003גוזלות\u0004 של יונים המובחרים ביותר — אלה הבאים \u0003מהר המלך.\u0004","\u0003ר' יהודה אומר:\u0004 היו \u0003מביאין\u0004 למקדש \u0003כבשים\u0004 כה משובחים, כאלה \u0003שגבהן\u0004 היה \u0003כרחבן,\u0004 שכל כך היו שמנים שהיו רחבים כמידת גובהם. \u0003אמר רבא בר רב שילא: מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לדברי \u0003ר' יהודה\u0004 שהיו מביאים למקדש כבשים כאלה? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדברי הנביא ישעיהו: \"ונתן מטר זרעך אשר תזרע את האדמה ולחם תבואת האדמה והיה דשן ושמן \u0003ירעה מקנך ביום ההוא כר נרחב\"\u0004 (ישעיהו ל, כג), ומשמעות \"כר נרחב\" — כבש רחב.","ומתוך דברים אלה נחתם פרק זה עוד בדרשות הנאמר בנבואות ישעיהו שעניינן בנין הארץ. \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"על חומתיך ירושלים הפקדתי שמרים כל היום וכל הלילה תמיד לא יחשו המזכירים את ה' אל דמי לכם\"\u0004 (שם סב, ו). ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 השומרים על חומות ירושלים \u0003אמרי\u0004 \u0005[אומרים]\u0006 כהזכרה לה'? ומשיבים: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבא בר רב שילא:\u0004 כך הם אומרים, \u0003\"אתה תקום תרחם ציון\u0004 כי עת לחננה כי בא מועד\" (תהלים קב, יד).","\u0003רב נחמן בר יצחק אמר:\u0004 כך הם אומרים \u0003\"בונה ירושלים ה'\u0004 נדחי ישראל יכנס\" (שם קמז, ב). ושואלים: \u0003ומעיקרא\u0004 \u0005[ומתחילה],\u0006 בזמן שבית המקדש היה קיים, וירושלים בנויה וכל עם ישראל כנוס בארצו, \u0003מאי הוו אמרי\u0004 \u0005[מה היו אומרים]\u0006 אותם המלאכים? \u0003אמר רבא בר רב שילא:\u0004 היו אומרים \u0003\"כי בחר ה' בציון אוה למושב לו,\u0004 זאת מנוחתי עדי עד פה אשב כי אויתיה...\" (שם קלב, יג— יד).","","\u0003שתי מדות\u0004 (כלי מדידה) \u0003של\u0004 הדבר ה\u0003יבש היו\u0004 נהוגות \u0003במקדש,\u0004 ובהם היו מודדים את הסולת למנחות, והם: כלי מידה של \u0003עשרון\u0004 (עשירית האיפה), \u0003ו\u0004כלי מידה של \u0003חצי עשרון. ר' מאיר\u0004 חולק על כך ו\u0003אומר\u0004 כי שלושה סוגי כלי היו: כלי מידה של \u0003עשרון\u0004 ועוד סוג נוסף של כלי מידה \u0003של\u0004 \u0003עשרון, ו\u0004כלי מידה של \u0003חצי עשרון.\u0004 ומסבירים את שימושיהם של הכלים הללו: כלי המידה של \u0003עשרון,\u0004 ל\u0003מה\u0004 (לאיזו תכלית) \u0003היה משמש? שבו היה מודד לכל המנחות,\u0004 שהרי כל המנחות באות משיעור עשרון סולת ומעלה. ומדידת הסולת לכל המנחות היתה נעשית בכלי של עשרון, ש\u0003לא היה מודד לא ב\u0004כלי של \u0003שלשה\u0004 עשרונים \u0003ל\u0004מנחת נסכים של \u0003פר,\u0004 \u0003ולא\u0004 היה מודד \u0003ב\u0004כלי \u0003של שנים\u0004 \u0003ל\u0004מנחת נסכים של \u0003איל,\u0004 \u0003אלא\u0004 היה \u0003מודדן\u0004 בכלי של \u0003עשרונות,\u0004 אחד אחרי השני.","","וכלי מדידה זה של \u0003חצי עשרון\u0004 ל\u0003מה היה משמש?\u0004 — \u0003שבו היה מודד\u0004 את חצי עשרון הסולת המובא ל\u0003חביתי\u0004 (מנחת חביתין של) \u0003כהן גדול,\u0004 המביא בכל יום עשרון שלם, שאותו היו מחלקים לשנים, \u0003מחצה\u0004 ממנו קרבה \u0003בבקר ו\u0004ה\u0003מחצה\u0004 השנית קרבה \u0003בין הערבים,\u0004 וחלוקת עשרון זה לשני חצאי עשרונים היתה נעשית בכלי זה.","שנינו במשנתנו שר' מאיר חולק על דברי תנא קמא, והריהו סבור ששלושה סוגי כלי מדידה היו במקדש: שנים של עשרון, וכלי מדידה נוסף של חצי עשרון. ובענין זה עוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה ר' מאיר אומר, מה תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"עשרון עשרון לכבש האחד\"\u0004 (במדבר כח, כט)? — \u0003מלמד ששתי עשרונות\u0004 (שני מיני כלי מדידה של עשרון) \u0003היו במקדש, אחד\u0004 מהם היה מכיל כדי עשרון רק כשהדבר הנמדד בו היה \u0003גדוש\u0004 מעל שפת הכלי, \u0003ואחד\u0004 מהם היה גדול ממנו, והיה מכיל כדי עשרון גם כשהדבר הנמדד בו הריהו \u0003מחוק\u0004 (שטוח, משתווה לפני שפת הכלי). ולמה היה משמש כלי המדידה שהכיל עשרון ב\u0003גדוש\u0004 — \u0003שבו היה מודד\u0004 את \u0003עשרון הסולת המובא\u0004 \u0003לכל המנחות.\u0004",""],["ואילו בכלי העשרון ה\u0003מחוק\u0004 — \u0003שבו היה מודד\u0004 עשרון סולת \u0003ל\u0004צורך \u0003חביתי כהן גדול.\u0004","\u0003וחכמים\u0004 החלוקים על ר' מאיר, \u0003אומרים\u0004 כי \u0003לא היה שם\u0004 במקדש שני כלי מדידה לעשרון, \u0003אלא\u0004 כלי \u0003עשרון אחד\u0004 בלבד. ומקור שיטתם של חכמים — \u0003ש\u0004כן \u0003נ\u0004 \u0003אמר: \"ועשרון אחד לכבש האחד\"\u0004 (במדבר כט, ד), לומר שלא היה במקדש אלא כלי עשרון אחד בלבד. ואולם \u0003אם כן\u0004 הוא, \u0003מה תלמוד לומר\u0004 \u0003\"עשרון עשרון\u0004 לכבש האחד\" (שם כח, כט) ממנו למד ר' מאיר שהיו במקדש שני כלי עשרונים? — הרי זה בא \u0003לרבות\u0004 כלי מדידת יבש נוסף שהיה במקדש, הכלי למדידת \u0003חצי עשרון. ו\u0004שואלים עתה לשיטת","\u0003ר' מאיר,\u0004 שדרש מהפסוק \"עשרון עשרון\" שהיו במקדש שני כלי מדידת עשרון, אם כן שהיה במקדש גם כלי למדידת \u0003חצי עשרון מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד, \u0005לו]\u0006 דבר זה \u0003מ\u0004מה שנאמר \u0003\"ועשרון\"\u0004 (\"ועשרון אחד לכבש האחד\"), ובאה בו וי\"ו יתירה לרבות שהיה במקדש גם כלי למדידת חצי עשרון. \u0003ו\u0004שואלים לשיטת \u0003רבנן\u0004 \u0005[חכמים]:\u0006 מדוע דרשו \u0005שהיתה מידת חצי עשרון במקדש מהפסוק \"עשרון עשרון לכבש האחד\", ולא דרשו כן מייתור וי\"ו, כדרך שדרש ר' מאיר?! ומשיבים: חכמים את האות\u0006 \u0003וי\"ו לא דרשי\u0004 \u0005[אינם דורשים],\u0006 שלדעתם אין לדרוש מכאן.","ושואלים עתה לצד האחר: \u0003ו\u0004לדעת \u0003ר' מאיר\u0004 הסבור ששני כלי מדידת עשרון היו במקדש, \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"ועשרון אחד לכבש האחד\"\u0004 שחכמים דרשו ממנו שלא היה אלא כלי עשרון אחד במקדש, \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה,\u0006 דורש \u0005בו]?\u0006 ומשיבים: הפסוק \u0003ההוא\u0004 בא להורות שאף למנחות ששיעור הסולת בהם גדול מעשרון אין מודדים אלא עשרון אחר \u0003עשרון,\u0004 \u0003שלא ימדוד לא ב\u0004כלי מדידה \u0003של שלשה\u0004 עשרונים \u0003ל\u0004צורך מנחת נסכים של \u0003פר ולא\u0004 ימדוד \u0003ב\u0004כלי מדידה \u0003של שנים\u0004 עשרונים \u0003ל\u0004צורך מנחת נסכים של \u0003איל.\u0004","ושואלים לצד האחר: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שדרשו מפסוק זה לענין שלא היה אלא כלי מדידת עשרון אחד, מהיכן הם לומדים הלכה זו? ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא,\u0006 נלמד, \u0005להם]\u0006 הלכה זו \u0003מנקודו\u0004 (מהנקודה) הכתובה בתורה מעל המלה \"ועשרון\". \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: למה נקוד\u0004 (רשומה נקודה מעל) האות \u0003וי\"ו שבאמצע\u0004 המלה \u0003\"עשרון\",\u0004 \u0003של\u0004 המלה \u0003\"עשרון\"\u0004 בפרשיות המועדות שבפרשת פינחס ה\u0003ראשון\u0004 מבין שניים (\"עשרון עשרון\") הנזכרים בפרשיה \u0003של יום טוב הראשון של חג\u0004 הסוכות (הוא הכתוב \"ועשרון עשרון לכבש האחד לארבעה עשר כבשים\", במדבר כט, טו)? ללמד \u0003שלא ימדוד לא בשל שלשה לפר, ולא בשל שנים לאיל.\u0004 ושואלים עתה לצד השני: \u0003ו\u0004לדעת \u0003ר' מאיר\u0004 שדרש הלכה זו מן הכתוב \u0003\"ועשרון אחד לכבש האחד\", מדוע לא דרש כן, מהניקוד שעל המלה \"עשרון\", כדרך שדרשו חכמים? ומשיבים: ר' מאיר את\u0004 \u0003נקודו\u0004 (נקודה זו שמעל המלה \"עשרון\") \u0003לא דריש\u0004 \u0005[אינו דורש],\u0006 שלדעתו, אין לדרוש מכך דבר\u0005.\u0006","שנינו במשנתנו כי הכלי המשמש למדידת \u0003חצי עשרון\u0004 ל\u0003מה היה משמש?\u0004 — \u0003שבו היה מודד לחביתי כהן גדול.\u0004","ותוהים: האמנם היה מביא הכהן הגדול מביתו חצי עשרון סולת, ואת אותו חצי עשרון היה \u0003מודד\u0004 במקדש באמצעות כלי מדידה זה? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו במסכתנו (לעיל מנחות נ,ב) כי \u0003חביתי כהן גדול\u0004 אותם מביא הכהן הגדול משל עצמו בכל יום, \u0003לא היו באין\u0004 בשני \u0003חצאין\u0004 חצי עשרון בבוקר וחצי עשרון בערב, \u0003אלא\u0004 הריהו \u0003מביא\u0004 מביתו \u0003עשרון שלם ו\u0004לאחר מכן \u0003הריהו\u0004 \u0003חוצהו\u0004 ולש מכל חצי עשרון שש חלות מצות, שהן שתים עשרה חלות מכל העשרון שהביא, ומקריב מחצית מהן בבוקר ומחצית מהן בערב.","\u0003אמר רב ששת: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מודד\" נמי דקתני\u0004 \u0005[גם כן ששנינו\u0006 במשנתנו\u0005]?\u0006 \u0003מחלק,\u0004 שהיה הכהן הגדול מביא מביתו עשרון שלם למקדש, ואחר כך היה חוצהו על ידי מדידתו בכלי זה.","ובעקבות דברי ר' מאיר המבחין בין שני סוגי מידות עשרון שהיו במקדש, המחוק והגדוש, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רמי בר חמא מרב חסדא\u0004 שאלה זו: כלי מדידת \u0003חצי עשרון\u0004 שהיה במקדש, \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 האם \u0003גדוש היה, או מחוק היה?\u0004","ולפני שמביאים את מענה רב חסדא לבעייתו זו של רמי בר חמא שבעקבותיה תבואנה בהמשך הסוגיה עוד שתי בעיות ששאל רמי בר חמא את רב חסדא, מביאים \u0003סימן\u0004 לזכור על ידו את נושאיהן של שלוש הבעיות הללו: \u0003חצי\u0004 (=חצי עשרון), \u0003חביתי\u0004 (=חביתי כהן גדול), \u0003שלחן\u0004 (=שולחן הפנים).","אמר לו רב חסדא לרמי בר חמא, בטרם פתר לו את בעייתו: מדוע מעלה אתה את בעייתך דווקא לשיטת \u0003ר' מאיר,\u0004 \u0003ו\u0004הרי \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 בעיה זו אף \u0003ל\u0004שיטתם \u0003של\u0004 \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' מאיר, שהרי הכל מודים שהיה כלי למדידת חצי עשרון, ומעתה יש לדון בו האם היה גדוש או מחוק. הסביר רמי בר חמא: כוונתי היתה לומר כי \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 גם בכלי למדידת ה\u0003עשרון גופיה\u0004 \u0005[עצמו]\u0006 כבר בעיה זו \u0003קא מיבעיא להו\u0004 \u0005[היא נשאלת להם],\u0006 האם \u0003גדוש היה או מחוק היה.\u0004 ואולם לר' מאיר בכלי למדידת \u0003עשרון עצמו אין מקום לבעיה זו, שהרי לשיטתו שני כלים היו, אחד מחוק ואחד גדוש. אלא אף לשיטת ר' מאיר יש מקום לשאול האם הכלי ששימש למדידת חצי עשרון היה גדוש או מחוק.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר חמא בפתרון בעייתו: \u0003מ\u0004תוך דברי \u0003ר' מאיר\u0004 ביחס לכלי למדידת עשרון \u0003נשמע\u0004 (נבין) מה היה הכלי למדידת חצי עשרון \u0003ל\u0004דעת \u0003ר' מאיר, ומ\u0004תוך דברי \u0003ר' מאיר נשמע\u0004 מה היה כלי זה \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים].\u0006","ומפרט רב חסדא את דבריו: \u0003מ\u0004תוך מה ש\u0003אמר ר' מאיר\u0004 כי הכלי למדידת ה\u0003עשרון\u0004 ה\u0003מחוק\u0004 הוא שנועד לצורך מנחת חביתי כהן גדול, מכאן יש ללמוד שאף כלי המדידה של \u0003חצי עשרון\u0004 שנועד לחביתי כהן גדול \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מחוק\u0004 היה. ו\u0003מ\u0004תוך שלמדנו כי לדעת \u0003ר' מאיר\u0004 הכלי המשמש למדידה (הן זה של עשרון והן זה של חצי העשרון) לצורך חביתי כהן גדול היה \u0003מחוק,\u0004 נסיק מכאן ש\u0003ל\u0004דעת \u0003רבנן נמי\u0004 \u0005[חכמים גם כן]\u0006 היה הכלי המשמש למדידה לחביתי כהן גדול \u0003מחוק,\u0004 הן זה של חצי עשרון והן זה של עשרון (שלדעת חכמים, שימש את כל המנחות כולן). שהרי לא נחלקו ר' מאיר וחכמים אלא בשאלה האם היו שני כלי עשרון או כלי עשרון אחד, משמע שמוסכם אף על חכמים שכלי עשרון שהיה במקדש היה מחוק.","ועוד בעיה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רמי בר חמא מרב חסדא:\u0004 את העיסה המשמשת לעשיית \u0003חביתי כהן גדול במה\u0004 היה \u0003מחלקן\u0004 לשתי מחציות, \u0003ל\u0004הכנת שש ה\u0003חלות\u0004 הקרבות בבוקר, ולהכנת שש החלות הקרבות בערב, האם \u0003ביד\u0004 ובלא להיעזר בכלי מדידה, \u0003או\u0004 \u0003בכלי\u0004 מדידה? אמר לו רב חסדא: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שהעיסה היתה נחלקת \u0003ביד.\u0004 וטעם הדבר: משום \u0003דאי\u0004 \u0005[שאם]\u0006 היתה החלוקה נעשית \u0003בכלי\u0004 כיצד היא תיעשה? האם \u0003טורטני\u0004 (פלס, מאזניים) \u0003יכניס\u0004 לעזרה לשם כך?!","שאל רמי בר חמא: \u0003ו\u0004מדוע לא \u0003יכניס\u0004 מאזניים לעזרה?! השיב רב חסדא: אין להכניס מאזניים לצורך מדידת הלחם המובא בו, \u0003כיון\u0004 ש\u0003ב\u0004פרשת התוכחה שבספר ויקרא, בכלל ה\u0003קללה כתיב\u0004 \u0005[נאמר]\u0006 \"בשברי לכם מטה לחם ואפו עשר נשים לחמכם בתנור אחד והשיבו לחמכם במשקל ואכלתם ולא תשבעו\" (ויקרא כו, כו), הרי ששקילת לחם היא מנהג של רעב, לכך \u0003לאו\u0004 \u0005[אין]\u0006 זה \u0003אורח ארעא\u0004 \u0005[דרך ארץ]\u0006 לנהוג כן במקדש\u0005.\u0006","ובעיה נוספת \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רמי בר חמא מרב חסדא: שלחן\u0004 של לחם הפנים \u0003מהו\u0004 דינו לענין \u0003שיקדש\u0004 את ה\u0003קמצים\u0004 המורמים מן המנחה או מן הלבונה שלא ניתנו כדינם בכלי שרת, \u0003אלא\u0004 \u0003בגודש\u0004 (בחלקו העליון, בין לחם ללחם) \u0003שלו\u0004 של שולחן הפנים? וצדדי הבעיה: \u0003מ\u0004תוך שהשולחן \u0003מקדש\u0004 את ה\u0003לחם\u0004 שעליו, אף את ה\u0003קמצים\u0004 הריהו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מקדש. או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי רק את הדבר \u0003דחזי ליה\u0004 \u0005[שראוי לו]\u0006 מן הדין להינתן עליו \u0003מקדש\u0004 אותו. ואולם מה \u0003דלא חזי ליה\u0004 \u0005[שאינו ראוי לו]\u0006 מן הדין להינתן עליו \u0003לא מקדש\u0004 אותו השולחן?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר חמא בפתרון בעייתו זו: את הקמצים הללו השולחן \u0003אינו מקדש.\u0004 תמה על כך רמי בר חמא: \u0003איני\u0004 \u0005[האמנם]\u0006 כך הוא? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: לדברי האומר\u0004 שבלטו הלחמים בשיעור \u0003טפחיים ומחצה\u0004 אל מחוץ לשולחן משני צידיו \u0003קופל\u0004 את יתרת הלחם הזו כלפי מעלה. וכיון שששה לחמים הם הנתונים זה מעל זה \u0003נמצא\u0004 איפוא שהיה ה\u0003שלחן מקדש\u0004 את הלחמים הנמצאים בגובה כדי \u0003חמשה עשר טפח\u0004 (שהם כפולה של ששה לחמים, שכל אחד מהם מוגבה שני טפחים ומחצה מעל השולחן) \u0003למעלה.\u0004 ואילו \u0003לדברי האומר\u0004 כי \u0003טפחיים\u0004 מלחם הפנים היה \u0003קופל\u0004 כלפי מעלה, \u0003נמצא\u0004 שהיה ה\u0003שלחן מקדש\u0004 כדי \u0003שנים עשר טפח למעלה.\u0004 הרי שהשולחן מקדש אף בחלק הגדוש, שמחוצה לו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר חמא: מה שאמרתי לך שאינו מקדש את הקמצים \u0003אינו\u0004 \u0003מקדש\u0004 את הקמצים לענין \u0003ליקרב\u0004 על המזבח. \u0003אבל\u0004 אכן הוא \u0003מקדש\u0004 אותם לענין \u0003ליפסל\u0004 בלינה ובמי שהוא טבול יום, כדין הקמצים שהתקדשו כתיקנם.","ולאחר שנידונו בפרקנו כלי המידות של הדברים היבשים שהיו במקדש, מונים עתה את כלי המידות של הדברים הלחים (כשמן ויין) שהיו במקדש. \u0003שבע מדות של לח היו במקדש,\u0004 ואלו הן: \u0003הין\u0004 (שהוא בן שנים עשר לוג); \u0003וחצי\u0004 ה\u0003הין\u0004 (ששה לוגים) המשמש למדידת השמן והיין למנחת נסכים של פר; \u0003ושלישית ההין\u0004 (ארבעה לוגים), המשמש למדידת השמן והיין למנחת נסכים של איל; \u0003ורביעית ההין\u0004 (שלושה לוגים), המשמש למדידת השמן והיין למנחת נסכים של כבש.","ובמידות הלוג: כלי שמידתו \u0003לוג.\u0004 המשמש למדידת שמן לכל המנחות, שהרי כל מנחה טעונה לפחות לוג שמן; \u0003וחצי לוג\u0004 שהיה משמש למדידת מים לסוטה, ולמדידת השמן ללחמי התודה (כמבואר להלן מנחות פח,א); \u0003ורביעית לוג\u0004 שהיה משמש למדידת מים למצורע שנתרפא ולמדידת שמן לרקיקים וחלות שמביא הנזיר ביום השלמת נזירותו (כמבואר להלן, שם).","\u0003ר' אליעזר בר ר' צדוק אומר:\u0004 לא היו במקדש כלי מידות רבים אלא כלי אחד שמידתו הין, ו\u0003שנתות\u0004 (חריצים מסמנים) \u0003היו בהין\u0004 זה, במחציתו של הכלי היה סימון האומר: \u0003עד כאן\u0004 יש כשיעור \u0003הראוי\u0004 \u0003לפר\u0004 (כלומר, חצי ההין). \u0003ו\u0004בשליש גובהו של הכלי היה סימון האומר כי \u0003עד כאן\u0004 יש כשיעור הראוי \u0003לאיל\u0004 (כלומר, שליש ההין). וברבע גובהו של כלי ההין היה סימון האומר כי \u0003עד כאן\u0004 יש כשיעור הראוי \u0003לכבש\u0004 (כלומר, רבע ההין).","\u0003ר' שמעון אומר:\u0004 מידות חצי ההין ושליש ההין ורבע ההין היו במקדש, ואולם \u0003לא היה שם\u0004 במקדש כלי מידה בשיעור \u0003הין.\u0004 וטעמו: \u0003וכי מה היה הין משמש?\u0004 שהרי אין דבר הבא במקדש שמידתו היא בהין, ואין איפוא צורך בכלי שכזה. \u0003אלא\u0004 לדעת ר' שמעון כדי להשלים את מספר הכלים למדידת הלח שהיו במקדש לשבעה, \u0003מדה יתירה\u0004 (נוספת) \u0003של לוג ומחצה היתה שם, שבה היה מודד\u0004 שמן \u0003ל\u0004צורך \u0003מנחת\u0004 חביתין של \u0003כהן גדול\u0004 הצריכה שלושה לוגים שמן, והיו שלושה לוגים אלה נחלקים לשניים: \u0003לוג ומחצה\u0004 שמן למחצית המנחה הקרבה \u0003בבוקר,\u0004 ו\u0003לוג ומחצה\u0004 שמן למחצית המנחה הקרבה \u0003בין הערבים.\u0004","שנינו במשנתנו כי שבעה כלי מדידה של נוזלים היו במקדש, ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003שבע מדות של לח היו במקדש,\u0004 הנמנות בסדר עולה: \u0003רביעית לוג, וחצי לוג, ולוג, ורביעית ההין, ושלישית ההין, וחצי\u0004 ה\u0003הין,\u0004 \u0003והין,\u0004 אלו \u0003דברי ר' יהודה.\u0004 אף \u0003ר' מאיר אומר\u0004 כי שבע מדות של לח היו במקדש, אלא שהוא מונה אותן בסדר יורד: \u0003הין, וחצי הין, ושלישית ההין, ורביעית ההין, ולוג, וחצי לוג, ורביעית לוג. ר' שמעון אומר: לא היה שם\u0004 במקדש כלי מדידה בשיעור \u0003הין,\u0004 וטעמו: \u0003וכי מה היה הין משמש?\u0004"],["ואולם אם כן, שלא היה במקדש כלי מידה ששיעורו הין, \u0003את מי\u0004 (איזה כלי אחר) \u0003אביא תחתיו\u0004 (במקומו) על מנת להשלים את מנין הכלים המשמשים למדידת נוזלים במקדש לשבעה? \u0003אלא\u0004 כלי \u0003מדה יתירה\u0004 (נוספת) ששיעורה כ\u0003של לוג ומחצה היתה שם\u0004 במקדש. \u0003שבו היה מודד\u0004 את שלושת הלוגים המובאים \u0003ל\u0004צורך \u0003חביתי כהן גדול,\u0004 שהיה חוצה את שלושת הלוגים הללו, לשני חלקים שוים: \u0003לוג ומחצה\u0004 למחצית המנחה הקריבה \u0003בבקר,\u0004 ו\u0003לוג ומחצה\u0004 למחצית השניה הקריבה \u0003בין הערבים.\u0004","\u0003אמרו לו\u0004 חכמים לר' שמעון, בתשובה לדבריו אלה: לצורך מדידת לוג ומחצה לחביתי כהן גדול, אין נדרשת מידה מיוחדת זו של לוג ומחצה. שהרי מידת \u0003חצי לוג היתה שם\u0004 במקדש, \u0003ואפשר\u0004 איפוא \u0003לשער\u0004 כמות זו של לוג ומחצה שמן במידת הלוג שהיתה במקדש ו\u0003ב\u0004מידת \u0003חצי לוג\u0004 שהיתה בו.","\u0003אמר להם\u0004 ר' שמעון בדחיית דבריהם: והרי \u0003אף לדבריכם\u0004 (לשיטתכם) שלא היתה מידת לוג ומחצה, יש מקום לשאול שמידת \u0003חצי לוג ו\u0004מידת \u0003לוג לא יעשה,\u0004 שהרי מידת \u0003רביעית היתה שם, ואפשר\u0004 איפוא \u0003לשער ב\u0004מידה זו של \u0003רביעית\u0004 את הדברים הנצרכים לשיעור חצי לוג (על ידי מדידת שתי פעמים מכלי המידה של רביעית), ובדרך דומה אפשר למדוד שמן ויין בשיעור לוג (על ידי מזיגת ארבע פעמים מכלי המידה של רביעית)! \u0003אלא זה הכלל היה במקדש: כלי\u0004 מדידה \u0003ש\u0004היה \u0003משמש מדה\u0004 (מסויימת) \u0003זו\u0004 \u0003אינו משמש\u0004 ככלי מדידה ל\u0003מדה אחרת.\u0004","ומביאים מה ששנינו במשנתנו ש\u0003ר' אלעזר בר' צדוק\u0004 היה \u0003אומר\u0004 כי \u0003שנתות היו בהין\u0004 שעליהן היו סימונים המלמדים מהו שיעור חצי ההין ורבע ההין.","ודנים עוד בברייתא שהובאה בעמוד הקודם. שנינו כי בין לדברי ר' יהודה ובין לדברי ר' מאיר שבע מידות של לח היו במקדש, ושניהם מנו אותן מידות, אלא שר' יהודה מנה אותן בסדר עולה, מן המידה הקטנה למידה הגדולה. בעוד שר' מאיר מנה אותן בסדר יורד, מן המידה הגדולה למידה הקטנה. ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 איזה\u0005]\u0006 הבדל הלכתי \u0003איכא\u0004 \u0005[יש]\u0006 \u0003בין ר' מאיר לר' יהודה? אמר ר' יוחנן:\u0004 ההבדל הוא בדינם של \u0003בירוצי\u0004 ה\u0003מדות,\u0004 הדברים העולים על גדות כלי המידה וניגרים על דפנותיהם מבחוץ, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006","שכן \u0003ל\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 את סדר המידות \u0003ממטה למעלה\u0004 (ר' יהודה), \u0003קסבר\u0004 \u0005[הריהו סבור]\u0006 כי אף \u0003בירוצי המדות נתקדשו. ו\u0004טעמו של דבר: שכן כאשר הצטווה משה רבינו לקבוע לבני ישראל את המידות הללו הנהוגות במקדש, בתחילה מידה בשיעור \u0003רביעית,\u0004 שהיא המידה הקטנה ביותר במידות הנוזלים \u0003יהיב ליה רחמנא\u0004 \u0005[נתן לו ה']\u0006 \u0003למשה, ואמר ליה\u0004 \u0005[לו]:\u0006 מכאן והלאה, \u0003שער\u0004 (מדוד) בה את שאר המידות. שישפוך שתי מידות של רביעית שכזו לכלי והרי זו מידת חצי לוג. ולאחר מכן יוסיף ויעלה למידה הגדולה יותר: שישפוך שני חצאי לוג לכלי — והרי זו מידת לוג. וכן ימשיך מן המידה הקטנה יותר למידה הגדולה יותר. ולדרך זו נמצא \u0003דקא עיילי להו\u0004 \u0005[שנכנסו להם]\u0006 מן הנוזלים שבמידה הקטנה לתוך המידה הגדולה יותר אף מן ה\u0003בירוצין\u0004 שאיתם. שהרי כאשר יוצקים מכלי קטן לכלי אחר הגדול הימנו, אף בירוציו של הנוזל הניצוק נכנסים אל הכלי הגדול יותר.","ואילו \u0003ל\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 את סדר המידות \u0003ממעלה למטה\u0004 (ר' מאיר), \u0003קסבר\u0004 \u0005[הריהו סבור]\u0006 כי \u0003בירוצי\u0004 ה\u0003מדות לא נתקדשו, ו\u0004סבר שכאשר הצטווה משה רבינו לקבוע לבני ישראל את המידות הללו, בתחילה מידה בשיעור \u0003הין\u0004 שהיא המידה הגדולה ביותר במידות הנוזלים \u0003יהיב ליה רחמנא\u0004 \u0005[נתן לו ה']\u0006 \u0003למשה, ואמר ליה\u0004 \u0005[לו]:\u0006 מכאן והלאה, \u0003שער\u0004 (מדוד) \u0003בהא\u0004 \u0005[בזה].\u0006 שנטל משה בתחילה ממידת ההין שניתנה לו מה', ושפך את הנמצא בה לשני כלים, בכל כלי מחצית \u0003דקא נפקי\u0004 \u0005[שהיו יוצאים]\u0006 ה\u0003בירוצין\u0004 תוך כדי שפיכה מהכלי הגדול, ונופלים ארצה, ולא היו נשפכים אל הכלי הקטן. שהרי כאשר יוצקים מכלי גדול לכלי קטן בירוציו של הנוזל הניצוק אינם נכנסים לכלי הקטן.","\u0003אביי אמר:\u0004 אין להסביר את ההבדל ההלכתי שבין ר' יהודה לר' מאיר באופן זה, \u0003דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל,\u0006 הן ר' יהודה והן ר' מאיר\u0005]\u0006 בדינם של \u0003בירוצי המדות איכא למימר\u0004 \u0005[יש\u0006 מקום \u0005לומר]\u0006 לדעת שניהם ש\u0003נתקדשו, ואיכא למימר\u0004 \u0005[ויש\u0006 מקום \u0005לומר]\u0006 בדעת שניהם כי \u0003לא נתקדשו.\u0004 שאין זה קשור למחלוקתם של ר' יהודה ור' מאיר. \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004משמעות המלה \u0003\"מלאים\"\u0004 שנאמרה בקרבנות הנשיאים בזמן חנוכת המשכן (\"קערת כסף אחת שלשים ומאה משקלה מזרק אחד כסף שבעים שקל בשקל הקודש שניהם מלאים סולת בלולה בשמן למנחה\". במדבר ז, יג) \u0003קא מיפלגי\u0004 \u0005[הם חלוקים].\u0006","ומפרט אביי את דבריו: \u0003מאן דאמר\u0004 \u0005[מי שאמר,\u0006 שמנה\u0005]\u0006 את שבעת כלי המדידה שבמקדש בסדר יורד \u0003מלמעלה למטה\u0004 (ר' מאיר) \u0003קא סבר\u0004 \u0005[הריהו סבור]\u0006 כי ההדגשה \u0003\"מלאים\"\u0004 באה להורות שתהא המידה מדוייקת, \u0003שלא יחסר\u0004 ממנה \u0003ושלא יותיר\u0004 עליה. ולכך בסיס הקביעה לשבע המידות היא מידת ההין, וממנה נקבעות שאר המידות הקטנות יותר, באופן זה שאין בו חסר או יתר.","\u0003ו\u0004אילו \u0003מאן דאמר\u0004 \u0005[מי שאמר,\u0006 שמנה\u0005]\u0006 את סדר כלי המדידה שבמקדש \u0003ממטה למעלה\u0004 (ר' יהודה) סבור שבאה המלה \u0003\"מלאים\"\u0004 \u0003שלא יחסר\u0004 מהמידה, \u0003אבל\u0004 אם \u0003יותיר\u0004 על המידה אין בכך כלום, שכן עדיין \u0003\"מלאים\" קרינא ביה\u0004 \u0005[קורא אני בו].\u0006","שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא ובמשנתנו כי \u0003ר' שמעון אומר\u0004 ש\u0003לא היה שם\u0004 במקדש מידת \u0003הין,\u0004 ושלא כדברי חכמים. וטעמו: שלמידת הין לא היה כל שימוש במקדש. ושואלים: \u0003שפיר קאמר להו\u0004 \u0005[יפה,\u0006 היטב, \u0005הוא אמר להם]\u0006 \u0003ר' שמעון לרבנן\u0004 \u0005[לחכמים]!\u0006 ומשיבים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: \u0003הוה\u0004 \u0005[היה]\u0006 במקדש כלי למדידת \u0003הין דעבד\u0004 \u0005[שעשה]\u0006 \u0003משה\u0004 במדבר סיני, \u0003ל\u0004צורך \u0003שמן המשחה\u0004 בו נמשחו המשכן וכליו והכהנים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בעשיית שמן המשחה \"ואתה קח לך... \u0003ושמן זית הין.\u0004 ועשית אותו שמן משחת קודש...\" (שמות ל, כד— כה). ונחלקו ר' שמעון וחכמים.","ש\u0003מר סבר\u0004 \u0005[שחכם זה,\u0006 ר' שמעון, \u0005סבור]:\u0006 \u0003כיון\u0004 ש\u0003לדורות לא הוה\u0004 \u0005[לא היה]\u0006 \u0003צריך\u0004 עוד בכלי למדידת ההין — רק \u0003לפי שעה\u0004 (לאותו הזמן בלבד) \u0003הוא דעבדיה\u0004 \u0005[שעשהו]\u0006 משה \u0003ו\u0004לאחר מכן \u0003איגנז\u0004 \u0005[נגנז]\u0006 אותו כלי. \u0003ו\u0004אילו \u0003אידך\u0004 \u0005[האחר,\u0006 חכמים\u0005]\u0006 סבורים כי \u0003כיון דהוה\u0004 \u0005[ש\u0006כבר \u0005היה]\u0006 כלי למדידת הין לא נגנז, אף שאין בו עוד צורך, אלא \u0003הוה\u0004 \u0005[היה]\u0006 גם לאחר מכן, שנשאר במקדש.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא ובמשנתנו: \u0003ואת מי אביא תחתיו\u0004 כדי להשלים את מנין הכלים לשבעה. ותוהים: ומה בכך שיהיו רק שש מידות, וכי \u0003לא סגיא דלא מעייל\u0004 \u0005[לא די לו שלא יכניס תחתיו]\u0006 מידה אחרת?! ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רבינא\u0004 לענין אחר: \u0003גמירי\u0004 \u0005[למודים היו,\u0006 קבלה היתה בידם\u0005]\u0006 שיש \u0003שתי סמיכות בציבור, הכא נמי גמירי\u0004 \u0005[כאן גם כן למודים היו]\u0006 ש\u0003שבע מדות של לח היו במקדש,\u0004 ומשום כך היה צריך ר' שמעון להשלים.","\u0003ר' אלעזר בר' צדוק אומר:\u0004 כלי מידה אחד היה ללח, הין ו\u0003שנתות היו ב\u0004אותו \u0003הין.\u0004 ושואלים: \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו\u0006 אינו מקבל\u0005]\u0006 את המסורת ש\u0003שבע מדות\u0004 היו במקדש? ואומרים: אפשר לומר ש\u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 מסורת זו. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שבע מדות?\u0004 הוא סבור שהכוונה היא ל\u0003שבע מדידות.\u0004","ומעתה מפרטים (בסדר עולה, מן המידה הקטנה למידה הגדולה ממנה) למה היתה משמשת כל אחת משבע המידות של לח שהיו במקדש. מידת ה\u0003רביעית מה היתה משמשת?\u0004 למדידת שיעור \u0003רביעית מים ל\u0004צורך טהרת ה\u0003מצורע\u0004 שנרפא מצרעתו. \u0003ו\u0004כן לצורך מדידת \u0003רביעית שמן ל\u0004חלות ורקיקים שמביא ה\u0003נזיר\u0004 ביום בו הוא משלים את ימי נזירותו.","כלי מידת \u0003חצי\u0004 ה\u0003לוג מה היה משמש?\u0004 למדידת שיעור \u0003חצי לוג\u0004 ה\u0003מים\u0004 מן הכיור שבמקדש \u0003ל\u0004צורך השקיית האשה ה\u0003סוטה.\u0004 \u0003ו\u0004כן למדידת שיעור \u0003חצי לוג שמן ל\u0004לחמי ה\u0003תודה\u0004 (לשלושת מיני המצה שבהם).","\u0003וב\u0004כלי מידת ה\u0003לוג היה מודד\u0004 שמן \u0003לכל\u0004 שאר \u0003המנחות,\u0004 שכן עשרון סולת המובא למנחה טעון לוג שמן.","ומציינים כי \u0003אפילו\u0004 הובאה סולת ל\u0003מנחה\u0004 בשיעור \u0003של ששים עשרון\u0004 \u0003נותן לה ששים לוג\u0004 שמן, לוג שמן כנגד כל עשרון סולת. ואילו \u0003ר' אליעזר בן יעקב אומר\u0004 כי כל מנחה, בין גדולה ובין קטנה, טעונה לוג שמן אחד, ולכך \u0003אפילו\u0004 היתה זו \u0003מנחה של ששים עשרון\u0004 \u0003אין לה אלא לוגה,\u0004 לוג אחד בלבד. וטעמו של ר' אליעזר בן יעקב: \u0003ש\u0004כן \u0003נאמר\u0004 בדין טהרת המצורע הדל שהריהו מביא ביום טהרתו \"...ועשרון סולת אחד בלול בשמן \u0003למנחה ולג שמן\"\u0004 (ויקרא יד, כא) ללמד: שכל מנחה, אף הגדולה ביותר, טעונה לוג שמן אחד בלבד.","וממשיכים בתיאור שימושם של כלי המדידה: כלי חצי ההין, שהם \u0003ששה\u0004 לוגים \u0003ל\u0004מנחת נסכי ה\u0003פר. ו\u0004כלי מידת שליש ההין, שהם \u0003ארבעה\u0004 לוגים משמש \u0003ל\u0004מדידת ארבעה לוגי השמן הבאים למנחת נסכי ה\u0003איל. ו\u0004כלי רביעית ההין, שהם \u0003שלשה\u0004 לוגים הריהו משמש \u0003ל\u0004מדידת לוגי השמן הבאים למנחת נסכי ה\u0003כבש.\u0004","ומציינים כי \u0003שלשה ומחצה\u0004 לוגים של שמן נדרשו \u0003ל\u0004הדלקת ה\u0003מנורה,\u0004 שכן היו במנורה שבעה נרות, ו\u0003חצי לוג\u0004 שמן היה ניתן \u0003לכל נר\u0004 שבה.","שנינו במשנתנו כי היה במקדש כלי שמידתו רביעית הלוג, והיה משמש למדידת מים למצורע ולמדידת שמן לצורך לחמי נזיר. ובענין זה מוסיפים: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבי\u0004 בלימודו \u0003וקא קשיא ליה\u0004 \u0005[והיה קשה לו]\u0006 על דברים אלה ששנינו: כלי \u0003רביעית\u0004 זה \u0003למה\u0004 בכלל \u0003נמשחה\u0004 (התקדשה במשיחת שמן המשחה עליה), ולשם מה נקבעה ככלי שרת במקדש? שהרי \u0003אי\u0004 \u0005[אם]\u0006 תאמר כי היא נועדה לשמש לצורך מדידת המים לטהרת ה\u0003מצורע,\u0004"],["— הלא דבר שנעשה ב\u0003חוץ הוא\u0004 ואינו צריך קידוש! \u0003ואי\u0004 \u0005[ואם]\u0006 נמשח כלי הרביעית לצורך מדידת השמן לטהרת ה\u0003נזיר\u0004 — הלא \u0003לחם נזיר בשחיטת איל הוא דקדיש\u0004 \u0005[שנקדש]\u0006 ואינו צריך הקדשה על ידי כלי!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא\u0004 לרבי כתשובה לשאלתו: נצרכה מידת רביעית להימשח, \u0003ש\u0004כן \u0003בה היה מודד\u0004 שמן \u0003ל\u0004מנחת \u0003חביתי כהן גדול\u0004 הבאים בכל יום, ש\u0003רביעית שמן\u0004 ניתנת \u0003לכל חלה וחלה\u0004 שבה. כהוקרה על שיישב לו את שאלתו, \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 רבי על ר' חייא, את האמור בכתוב \u0003\"מארץ מרחק איש עצתי...\"\u0004(ישעיהו מו, יא), שר' חייא שהחכים בדבר זה את רבי (\"איש עצתי\") בא לארץ ישראל, מקום מגורי רבי, מארץ בבל המרוחקת (\"מארץ מרחק\").","שנינו במשנתנו כי אחד מכלי המידה ללח שבמקדש היה מידת \u0003חצי\u0004 ה\u0003לוג,\u0004 ו\u0003מה היה משמש\u0004 — למדידת המים הניתנים במי הסוטה ולשמן הניתן ללחמי התודה. ואף בענין זה נמסר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבי\u0004 תוך לימודו \u0003וקא קשיא ליה\u0004 \u0005[והיה קשה לו]:\u0006 כלי מידה זה של \u0003חצי לוג למה,\u0004 לשם מה \u0003נמשח\u0004 והתקדש לכלי שרת? ופרט רבי את תמיהתו זו: שכן \u0003אי\u0004 \u0005[אם]\u0006 לצורך מדידתם וקידושם של מי \u0003סוטה\u0004 — \u0003וכי\u0004 המים הניתנים להשקייתה של הסוטה מי \u0003חולין הוא, דצריכי לקדושי\u0004 \u0005[שצריכים לקדש\u0006 אותם\u0005]?!\u0006 והלא \u0003\"מים קדושים\" כתיב\u0004 \u0005[נאמר]\u0006 בהם (\"ולקח הכהן מים קדושים בכלי חרש...\". במדבר ה, יז), שנלקחו המים מן הכיור שבמקדש, ובו נתקדשו כבר! ו\u0003אי\u0004 \u0005[אם]\u0006 תאמר שנצרכה לצורך מדידתו וקידושו של השמן הניתן ללחמי \u0003תודה\u0004 — והרי \u0003לחמי\u0004 ה\u0003תודה, בשחיטת\u0004 קרבן ה\u0003תודה הוא דקדשי\u0004 \u0005[שמתקדשים],\u0006 ואין צורך לקדש את השמן!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון ברבי\u0004 (בן רבי) לאביו: נצרך לקדש כלי מחצית הלוג, משום \u0003שבו\u0004 בכלי זה \u0003היה מחלק חצי לוג שמן לכל נר ונר\u0004 במנורת המקדש, שכך היתה מידת השמן בכל נר. \u0003אמר לו\u0004 רבי לבנו ר' שמעון: בלשון הוקרה: \u0003נר ישראל,\u0004 באמת \u0003כך היה\u0004 עושה במידת מחצית הלוג.","ומתוך שנזכרו דברי רבי בענין השמן בנרות המנורה, מביאים עוד בענין זה מה ש\u0003אמר ר' יוחנן, אמר רבי: נר\u0004 מנרות המנורה \u0003שכבתה\u0004 לפני שהאיר היום, הדין הוא ש\u0003נידשן\u0004 (נעשה כדשן) \u0003השמן\u0004 שבנר, כשם ש\u0003נידשנה\u0004 (נעשית כדשן) \u0003הפתילה\u0004 שבנר. ואין להם תקנה. \u0003כיצד\u0004 הכהן \u0003עושה\u0004 (נוהג)? \u0003מטיבה\u0004 (משליך אל מחוץ לנר את השמן והפתילה שבתוך הנר), \u0003ונותן בה שמן\u0004 ופתילה חדשים \u0003ומדליקה.\u0004","ונמסר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' זריקא\u0004 תוך לימודו בהלכה זו, \u0003וקא מיבעיא ליה\u0004 \u0005[ונשאלה לו]\u0006 שאלה זו: \u0003כשהוא\u0004 שב ו\u0003נותן בה\u0004 בנר שכבתה \u0003שמן\u0004 מחדש, האם הוא נותן בה שמן \u0003כמדה\u0004 שנתן \u0003בנר זה ב\u0004\u0003ראשונה\u0004 (בתחילה), חצי הלוג, \u0003או\u0004 שמא הוא נותן בנר שמן בשיעור \u0003כמו שחסרה\u0004 עתה הנר בהשלכת השמן שנותר לאחר שכבה הנר?","\u0003אמר ר' ירמיה:\u0004 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא ש\u0003כמדה ראשונה\u0004 של שמן הוא נותן. ונימוקו: \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שהוא נותן שמן בשיעור \u0003כמה שחסרה, מנא ידעינן מאי\u0004 \u0005[מנין יודעים אנו מה,\u0006 כמה\u0005]\u0006 שמן הוא \u0003חיסר? וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שיהא הכהן \u0003משער ליה\u0004 \u0005[אותו]\u0006 על ידי מדידתו בכלי מידה שהיה במקדש — אין לומר כך, משום ש\u0003אם כן,\u0004 רק \u0003שבע\u0004 כלי \u0003מדות\u0004 (מדידות) היו במקדש? \u0003נפיש להו\u0004 \u0005[מרובות הן]\u0006 כלי \u0003מדות טובא\u0004 \u0005[הרבה],\u0006 לצורך מדידתם של כמויות שמן קטנות וקטנות ביותר, שנותרו בנרות שכבו בלילה.","קיבל ר' זריקא את פתרונו של ר' ירמיה, ו\u0003קרי עליה\u0004 \u0005[קרא,\u0006 המליץ, \u0005עליו]\u0006 בלשון שבח וכבוד: \u0003\"והדרך צלח רכב על דבר אמת וענוה צדק\u0004 ותורך נוראות ימינך\" (תהלים מה, ד).","ומביאים בענין זה, \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 שכך \u0003אמר ר' אבהו, אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר ר' אבא, אמר ר' חנינא, אמר רבי: נר שכבתה, נידשן השמן נידשנה הפתילה. כיצד עושה? מטיבה, ונותן בה שמן כמדה ראשונה ומדליקה.\u0004 וכפתרונו של ר' ירמיה.","מתוך שהובאו דברים בענין הטבת נרות המנורה, מביאים עוד בענין זה ממה ש\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה, אמר רב ששת:\u0004 כל \u0003נר\u0004 ונר \u0003שב\u0004מנורת ה\u0003מקדש\u0004 — \u0003של פרקים\u0004 (בעל מפרקים, המאפשרים כיפוף והטיה) \u0003הוה\u0004 \u0005[היה],\u0006 שאפשר היה לכופף את הנר ולהטותו, וכגון לצורך הטבתו (הוצאת השמן והפתילות הישנים שבתוכו), ולאחר מכן לשוב ולזוקפו. ומסבירים את דעת רב ששת: נאמר בפרשת עשיית המנורה \"ועשית זהב טהור מקשה תיעשה המנורה ירכה וקנה גביעיה כפתוריה ופרחיה ממנה יהיו... כולה מקשה אחת זהב טהור. ככר זהב טהור יעשה אותה את כל הכלים האלה\" (שמות כה, לא—לט).","ו\u0003קסבר\u0004 \u0005[סבור הוא\u0006 רב ששת\u0005]:\u0006 \u0003כי כתיב\u0004 \u0005[כאשר נאמר]\u0006 הן מה שנאמר במעשה המנורה \u0003\"ככר\u0004 זהב יעשה אותה\", \u0003ו\u0004הן מה שנאמר בעשייתה \u0003\"מקשה\"\u0004 (שתהא המנורה יחידה אחת, בלתי נפרדת לחלקיה) — גם על ה\u0003מנורה\u0004 עצמה \u0003ו\u0004גם על \u0003נרותיה כתיב\u0004 \u0005[נאמר]\u0006 הדבר. ומעתה, \u0003כיון דמיבעיא\u0004 \u0005[שצריכה]\u0006 המנורה \u0003הטבה\u0004 של נרותיה — חייבים לומר כי הקנים ניתנו לכיפוף ולהטיה. שכן \u0003אי לאו\u0004 \u0005[אם לא]\u0006 של \u0003פרקים הוי\u0004 \u0005[היו]\u0006 הנרות — \u0003לא הוה\u0004 \u0005[לא היה]\u0006 יכול הכהן \u0003מטייבא ליה\u0004 \u0005[להיטיב אותם].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב ששת ממה ששנינו בברייתא \u0005:\u0006 \u0003כיצד\u0004 היה הכהן \u0003עושה\u0004 בהטבת הנרות? — היה \u0003מסלקן\u0004 (מסירם) מעל המנורה \u0003ומניחן באוהל, ומקנחן בספוג,\u0004 ובכך מסיר מהם כל שאריות שמן ופתילות משל אתמול, \u0003ו\u0004לאחר מכן הריהו \u0003נותן בהן שמן, ומדליקן.\u0004 ולדברי ברייתא זו אין צורך שתהא של פרקים, שהרי נאמר במפורש שהנרות היו מוסרים מהמנורה!","ומשיבים: מחלוקת תנאים יש בדבר, ו\u0003הוא\u0004 (רב ששת) \u0003אמר\u0004 את דבריו \u0003כי האי תנא\u0004 \u0005[כמו\u0006 שיטתו של \u0005תנא זה]\u0006 בברייתא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא אחרת\u0003]\u0004 בדרך הטבת נרות המנורה: \u0003חכמים אומרים\u0004 כי \u0003לא היו מזיזין אותה\u0004 (את קני המנורה) \u0003ממקומה\u0004 לצורך ההטבה. והרי שלדעת חכמים הנרות היו חלק בלתי נפרד מהמנורה, כיחידה אחת, ולא היו מוסרים ממנה.","ומקשים על כך: אף שיטת ברייתא זו אינה כדברי רב ששת. שהרי ממה ששנינו בה שלא היו מזיזים את הנרות ממקומם ניתן לדייק: \u0003מכלל דאיבעיא ליה לאוזוזה\u0004 \u0005[מכאן, שאם רצה לו להזיז\u0006 אותם\u0005]\u0006 אף שהלכה היא, לדעתם, שאין להזיז אותם — \u0003מצי מזיז לה\u0004 \u0005[יכול היה להזיז אותה],\u0006 ושלא \u0005כרב ששת, האומר שלא ניתן היה להסיר את נרות המנורה מהמנורה! ומתרצים: אין לשון ברייתא זו מתוקן, ואל תשנה בה \"לא היו מזיזים אותה\",\u0006 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 בה כך: \u0003לא היתה זזה ממקומה.\u0004","\u0003ו\u0004מבררים עוד את דברי הברייתא שהובאה עתה: \u0003מאן\u0004 \u0005[מיהו]\u0006 התנא המכונה בשם \u0003חכמים\u0004 שבברייתא זו? ומשיבים: \u0003ר' אלעזר\u0004 בנו של ר' צדוק \u0003הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא נוספת\u0005],\u0006 \u0003ר' אלעזר בר' צדוק אומר: כמין טס\u0004 (מגש, משטח) \u0003של זהב היה לה\u0004 לכל נר ונר מנרות המנורה, שהיה נתון \u0003על גבה\u0004 (מעליה) ומשמש כעין כיסוי לו. ושימושו — ש\u0003כשהוא\u0004 הכהן \u0003מטיבה\u0004 את הנר — \u0003הריהו\u0004 \u0003דוחקו\u0004 (דוחף את הטס) \u0003כלפי פיה\u0004 (פה הנר, מקום הפתילה והלהבה). וכתוצאה מכך, היה נחשף תוכו של הנר. והיה מטה את הנר, ומוציא החוצה את כל שאריות השמן והפתילה שנותרו משל אתמול. ו\u0003כשהוא נותן בה שמן\u0004 ופתילה חדשים, לשם ההדלקה החדשה — הריהו \u0003דוחקו\u0004 את הטס כלפי חוץ ומחזירו \u0003כלפי ראשה\u0004 של הנר, ושב וזוקף את הנר, ודרך הנקב שהיה באמצעו של הטס, היה נותן את השמן בנר.","\u0003ו\u0004מעירים: מחלוקת תנאים זו, אם הנרות היו במנורה כיחידה אחת בלתי נפרדת (\"מקשה\"), או שהיו ניתנים להסרה — שנוי \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת\u0006 אחרת \u0005של תנאים אלה,\u0006 אחרים\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 הן ה\u0003מנורה ו\u0004הן \u0003נרותיה\u0004 היו \u0003באות\u0004 (נעשות) \u0003מן הככר\u0004 זהב טהור, וכשם שהיו גם המנורה וגם נרותיה באים מאותו ככר זהב, היו גם מקשה אחת. \u0003ואין מלקחיה ומחתותיה\u0004 (הכלים בהם היתה נעשית הטבת הנרות) של המנורה נעשות \u0003מן הככר\u0004 זהב. \u0003ר' נחמיה אומר\u0004 כי \u0003רק ה\u0004\u0003מנורה\u0004 עצמה \u0003היתה באה\u0004 (נעשית) \u0003מן הככר\u0004 זהב, \u0003ולא נרותיה ומלקחיה ומחתותיה באות\u0004 (היו נעשים) \u0003מן הככר\u0004 זהב. וכשם שלדעת ר' נחמיה לא היו הנרות באים מן הככר. אף לא היו בכלל מקשה (ומוסרים היו מן המנורה).","ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 מהו הענין, שבו \u0005הם,\u0006 התנאים הללו, \u0005חלוקים\u0006 בו\u0005]?\u0006 — \u0003בהאי קרא\u0004 \u0005[בפסוק זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא אחרת\u0005]\u0006 ממה שנאמר \u0005במעשה המנורה\u0006 \u0003\"ככר זהב טהור יעשה אתה\"\u0004 (שמות כה, לט) \u0003למדנו למנורה\u0004 עצמה \u0003ש\u0004היא \u0003באה\u0004 (נעשית) \u0003מן הככר\u0004 זהב. ו\u0003מנין\u0004 לנו שיש \u0003לרבות\u0004 גם את \u0003נרותיה,\u0004 שאף הם נעשים מככר הזהב? — \u0003תלמוד לומר\u0004 במעשה המנורה \"ככר זהב טהור יעשה אותה \u0003את כל הכלים האלה\"\u0004 — שאף הנרות נעשים מככר הזהב. ואולם אחר שלמדנו שגם הנרות באים מככר הזהב, \u0003יכול\u0004 יהא הדין \u0003שאני מרבה\u0004 לענין זה \u0003אף\u0004 את \u0003מלקחיה ומחתותיה\u0004 של המנורה, שאף הם נעשים מככר הזהב? לכך \u0003תלמוד לומר\u0004 \"ככר זהב יעשה \u0003אתה\"\u0004 — בלשון מיעוט, לומר שדווקא היא נעשית מככר הזהב, ולא מלקחיה ומחתותיה. אלו \u0003דברי ר' נחמיה.\u0004","ולפני שממשיכים בציטוט דברי הברייתא, תוהים: \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' נחמיה\u0004 אלה, הסבור שנרות המנורה נעשות מככר הזהב, על דברי \u0003ר' נחמיה\u0004 בברייתא שהובאה למעלה, שאין הנרות נעשים מככר הזהב! ומשיבים: שתי ברייתות אלה הריהן של \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 שונים, \u0003ו\u0004חלוקים הם \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' נחמיה.\u0004","וממשיכים בדברי הברייתא: \u0003ר' יהושע בן קרחה אומר\u0004 כי רק ה\u0003מנורה\u0004 עצמה היתה \u0003באה מן הככר, ואין מלקחיה ומחתותיה ו\u0004כן אין \u0003נרותיה באה מן הככר. ואלא מה אני מקיים\u0004 (מה אני דורש מהכתוב) \"ככר זהב טהור יעשה אותה \u0003את כל הכלים האלה\"?\u0004 — ללמד \u0003שהיו\u0004 אף \u0003כלים\u0004 אלה עשויים מ\u0003של זהב,\u0004 ואולם לא נעשו מככר הזהב של המנורה.","ותוהים: לשם כך אין צורך בלימוד זה, הרי \u0003זהב בהדיא כתיב\u0004 \u0005[במפורש כתוב]\u0006 \u0003בו,\u0004 שכן נאמר \u0003\"ועשית את נרתיה שבעה והעלה את נרתיה והאיר אל עבר פניה. ומלקחיה ומחתתיה זהב טהור\"\u0004 (שם לז—לח)! ומשיבים: \u0003לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 דרשה זו הנלמדת מ\"את כל הכלים האלה\" \u0003אלא ל\u0004למד בדינם של \u0003פי\u0004 ה\u0003נרות,\u0004 שגם הם יהיו של זהב. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ופי נרות\u0004 במקום ששמים את הפתילה הריהו \u0003אשחורי משחר\u0004 \u0005[משחיר]\u0006 מלהבת האש הבוערת, ומתקלקל, והרי כלל הוא בידינו כי \u0003התורה חסה על ממונן של ישראל,\u0004"],["\u0003ו\u0004משום כך אולי מוטב היה \u0003ליעבד\u0004 \u0005[שייעשה]\u0006 פי הנר מ\u0003זהב כל דהו\u0004 \u0005[כל שהוא]\u0006 ואף מאיכות גרועה, ולאו דווקא זהב טהור. לכן \u0003קא משמע לן\u0004 \u0005[היא,\u0006 דרשת \u0005הכתוב הזה\u0006 \u0005משמיעה לנו,\u0006 מלמדת אותנו\u0005]\u0006 שגם פי הנר צריך להיות מזהב טהור.","שנינו במשנתנו כי מידת \u0003חצי לוג\u0004 שהיתה במקדש שימשה למדידת מחצית לוג ה\u0003שמן\u0004 הניתן \u0003ל\u0004שלושת מיני המצה שהיו בלחמי ה\u0003תודה.\u0004","ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 על הנאמר בענין לחמי התודה: \u0005\"אם על תודה יקריבנו והקריב על זבח התודה חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן וסולת מורבכת חלות בלולות בשמן. על חלות לחם חמץ יקריב קרבנו על זבח תודת שלמיו\" (ויקרא ז, יב—\u0006 יג). \u0003ר' עקיבא אומר: מה תלמוד לומר\u0004 (מלמדנו האמור) \u0003\"בשמן\"\u0004 בחלות המצות (\"חלות מצות בלולות בשמן\"), ושוב נאמר \u0003\"בשמן\"\u0004 ברקיקים (\"ורקיקי מצות משוחים בשמן\") \u0003שני פעמים?\u0004 — נצרכים שניהם להיאמר, שכן \u0003אילו לא\u0004 היה \u0003נאמר אלא \"בשמן\" אחד, הייתי אומר: הרי\u0004 דין לחמי התודה \u0003הוא כ\u0004דינם של \u0003כל\u0004 שאר \u0003המנחות ל\u0004ענין מידת השמן, שהוא \u0003לוג\u0004 שמן. \u0003עכשיו שכתב \"בשמן\" \"בשמן\"\u0004 שתי פעמים — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ריבוי אחר ריבוי, ו\u0004כלל הוא בדרכי דרשת הכתוב כי \u0003אין ריבוי אחר ריבוי\u0004 בא \u0003אלא למעט,\u0004 ולמדנו מכאן כי \u0003מיעטו הכתוב\u0004 את השיעור הניתן ללחמי תודה מלוג, \u0003לחצי לוג.\u0004","ותוהים: האם \u0003ריבוי אחר ריבוי\u0004 הוא זה?! הלא רק \u0003חד\u0004 \u0005[אחד]\u0006 \u0003ריבוי הוא,\u0004 \"בשמן\" \u0003האמור בשנית. שהרי \"בשמן\" האמור בפעם הראשונה נצרך לעצמו לומר שדין לחמי התודה כדין שאר המנחות לענין השמן!\u0004","\u0003אלא\u0004 יש לתקן את הנוסח, וכך יש לשנות: \u0003אילו לא נאמר \"בשמן\" כל עיקר\u0004 — \u0003הייתי אומר\u0004 כי דין לחמי התודה \u0003הרי הוא כ\u0004דינם של \u0003כל\u0004 שאר \u0003המנחות ללוג\u0004 שמן הניתן בהן. \u0003עכשיו שנאמר \"בשמן\" \"בשמן\"\u0004 שתי פעמים, וכל אחד מהם הריהו ריבוי — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ריבוי אחר ריבוי, ואין ריבוי אחר ריבוי אלא למעט,\u0004 ובכך \u0003מיעטו הכתוב לחצי לוג.\u0004","וממשיכים בדברי ר' עקיבא: ומעתה שלמדנו מן המיעוט, לענין מידת השמן הניתנת בלחמי התודה, שהוא רק חצי לוג שמן, יש מקום לשאול, \u0003יכול יהא חצי לוג זה מתחלק\u0004 בשווה \u0003ל\u0004כל \u0003שלשת\u0004 ה\u0003מינין\u0004 של לחמי התודה הבאים מצות, \u0003לחלות ולרקיקין ולרביכה? כשהוא,\u0004 הכתוב, \u0003שב ו\u0004\u0003אומר \"בשמן\"\u0004 אף \u0003ברביכה,\u0004 ויש לשאול על כתוב זה: \u0003שאין תלמוד לומר\u0004 (הנאמר מלמדנו) דבר, שהרי יודעים אנו כבר כי מידת השמן בלחמי התודה היא מחצית הלוג, ולא לוג שלם. לכך יש לומר כי בא כתוב נוסף זה, ו\u0003ריבה\u0004 בשיעור ה\u0003שמן\u0004 הניתן \u0003לרביכה\u0004 על פני שיעור השמן הניתן לחלות ולרקיקים. \u0003הא\u0004 \u0005[הרי]\u0006 זה \u0003כיצד\u0004 נוהגים למעשה? \u0003מביא חצי לוג שמן וחוציהו,\u0004 כאשר \u0003חציו\u0004 האחד ניתן \u0003ל\u0004עשר ה\u0003חלות ול\u0004עשרת ה\u0003רקיקין\u0004 גם יחד, \u0003וחציו\u0004 האחר ניתן \u0003ל\u0004עשרת הלחמים שב\u0003רביכה.\u0004","\u0003אמר לו ר' אלעזר בן עזריה\u0004 לר' עקיבא: \u0003עקיבא,\u0004 גם \u0003אם אתה מרבה כל היום כולו \"בשמן\" \"בשמן\"\u0004 — \u0003איני שומע לך\u0004 (איני מקבל דבריך), שיש ללמוד את ההלכות הללו מן הכתובים, \u0003אלא\u0004 ההלכה האומרת ש\u0003חצי לוג\u0004 הוא שיעור ה\u0003שמן\u0004 הניתן \u0003לתודה ו\u0004ההלכה האומרת ש\u0003רביעית\u0004 לוג הוא שיעור ה\u0003שמן\u0004 הניתן \u0003ל\u0004לחמי \u0003נזיר,\u0004 \u0003ו\u0004ההלכה האומרת שהאשה הרואה דם בתוך \u0003אחד עשר\u0004 ה\u0003יום שבין נדה לנדה\u0004 (לאחר שבעת ימי נדתה), הריהי זבה (אם ראתה שלושה ימים) — כל אלה הן \u0003הלכה למשה מסיני,\u0004 ואין ללמדן מן הכתובים.","עוד שנינו במשנתנו כי \u0003ב\u0004כלי המידה של \u0003לוג היה מודד\u0004 שמן לכל המנחות הבאות למקדש, שכן כל עשרון סולת המובא למנחה טעון לוג שמן. ולכך, אפילו היתה זו מנחה של שישים עשרונות סולת — הריהו מביא בה שישים לוג שמן. ואילו לדעת ר' אליעזר בן יעקב אין מביאים שמן למנחה אלא לוג שמן אחד בלבד, ולכך אפילו הביא מנחה של שישים עשרונות סולת — הריהו מביא בה לוג שמן אחד בלבד.","ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003במצורע עני\u0004 המיטהר מטומאת צרעתו, ואין ידו משגת להביא שני כבשים (אחד לעולה ואחד לאשם), וכבשה (לחטאת), נאמר שמביא בקרבנותיו כבש אחד (לאשם) ועשרון אחד סולת למנחה. ובמה שבענין מנחה זו \u0003כתיב\u0004 \u0005[נאמר]\u0006 \"ו \u0003עשרון\u0004 סולת אחד \u0003בלול\u0004 בשמן למנחה \u0003ולוג\u0004 שמן\" (ויקרא יד, כא) \u0003לימד\u0004 הכתוב \u0003על\u0004 כל \u0003עשרון\u0004 סולת הבא למנחות \u0003שטעון לוג\u0004 שמן בפני עצמו, ולמנחה בת שישים עשרון דרושים שישים לוג שמן. אלו \u0003דברי חכמים.\u0004","\u0003ר' נחמיה ור' אליעזר אומרים:\u0004 כל מנחה אינה באה אלא עם לוג שמן אחד, ולכך \u0003אפילו מנחה של ששים עשרונים\u0004 — \u0003אין לה אלא לוגה\u0004 ולא יותר, \u0003ש\u0004כן \u0003נאמר\u0004 בכתוב זה \u0003\"למנחה ולג שמן\". ו\u0004שואלים: לשיטת","\u0003ר' נחמיה ור' אליעזר האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"עשרון... בלול... ולג\"\u0004 שממנו למדו חכמים כי כל עשרון הבא למנחה טעון לוג שמן, \u0003מאי עבדי ליה\u0004 \u0005[מה\u0006 הם \u0005עושים בו]?\u0006 ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 כתוב נצרך \u0003לגופיה\u0004 \u0005[לגופו,\u0006 לעצמו\u0005],\u0006 \u0003דקא אמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003לייתי\u0004 \u0005[שיביא]\u0006 המצורע העני \u0003חד\u0004 \u0005[אחד]\u0006 \u0003עשרון\u0004 סולת, ולא ללמד על כל עשרון.","ושואלים עתה לצד שכנגד: \u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 החולקים עליו, לדעתם, כתוב זה \u0003לגופיה\u0004 \u0005[לגופו]\u0006 של דין המצורע העני שיביא עשרון סולת \u0003לא צריך.\u0004 שכן, \u0003מ\u0004תוך \u0003דגלי רחמנא גבי\u0004 \u0005[שגילתה התורה אצל]\u0006 ה\u0003מצורע\u0004 הרגיל, שאיננו עני, שמביא ביום טהרתו \u0003שלשה קרבנות ושלשה עשרונות,\u0004 הרי אנו יודעים ש\u0003הכא\u0004 \u0005[כאן,\u0006 במצורע העני\u0005]\u0006 \u0003דחד\u0004 \u0005[ש\u0006רק \u0005אחד]\u0006 \u0003קרבן\u0004 הוא מביא, שממילא רק \u0003חד\u0004 \u0005[אחד]\u0006 \u0003עשרון\u0004 הוא מביא, ולא נצרך הכתוב אלא ללמדנו שכל עשרון טעון לוג שמן.","ושואלים עתה לצד שכנגד: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' נחמיה ור' אליעזר\u0005]\u0006 — לדעתם עדיין \u0003איצטריך\u0004 \u0005[נצרך]\u0006 כתוב זה במצורע העני להיאמר. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך,\u0006 היה מקום \u0005לומר]\u0006 כי \u0003הואיל וחס רחמנא עליה\u0004 \u0005[וחסה התורה עליו,\u0006 על המצורע \u0003העני\u0004\u0005],\u0006 ואמרה שעליו \u0003לאתויי\u0004 \u0005[להביא]\u0006 קרבן זה \u0003בדלות, אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא ליבעי מינה\u0004 \u0005[לא יצטרך ממנה]\u0006 \u0003כלל\u0004 שמן. ולכן נצרך כתוב זה להשמיענו שהמצורע העני מביא עשרון סולת ולוג שמן. \u0003ואידך\u0004 \u0005[ואחרים,\u0006 חכמים\u0005]\u0006 אומרים שאין צורך בכך, שכן מנחה ש\u0003לגמרי\u0004 לא יהיה בה שמן \u0003לא אשכחן\u0004 \u0005[לא מצאנו].\u0006","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 החלוקים על ר' נחמיה ור' אליעזר, ב\u0003האי\u0004 \u0005[זה]\u0006 הפסוק \u0003\"למנחה ולג שמן\"\u0004 ממנו למדו ר' נחמיה ור' אליעזר את שיטתם, \u0003מאי עבדי ליה\u0004 \u0005[מה עושים,\u0006 לומדים, \u0005בו]?\u0006 ומשיבים: לדעת חכמים, הפסוק \u0003ההוא\u0004 בא ללמד \u0003ל\u0004עניינו של ה\u0003מתנדב מנחה\u0004 ולא פירש את שיעורה \u0003שלא יפחות מדבר\u0004 (משיעור) \u0003הטעון לוג, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 שיעור זה? — \u0003עשרון,\u0004 שאין מתנדבים מנחה בפחות מזה. ושואלים לצד שכנגד: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' נחמיה \u0005ור' אליעזר\u0006\u0005],\u0006 שלמדו מפסוק זה כמקור לשיטתם, מאין להם הלכה זו? ומשיבים: לדעתם, \u0003תרתי שמעת מינה\u0004 \u0005[שני\u0006 דברים \u0005אתה למד ממנה,\u0006 מפסוק זה\u0005],\u0006 שאין מביאים במנחה (בכל שיעור) אלא לוג שמן אחד, וכי המתנדב למנחה מביא סולת בשיעור \u0003עשרון ולא פחות.\u0004","שנינו במשנתנו כי \u0003ששה\u0004 לוגים שמן (חצי ההין) היו מובאים \u0003ל\u0004מנחת נסכי ה\u0003פר, ארבעה\u0004 לוגים (שליש ההין) \u0003ל\u0004מנחת נסכי ה\u0003איל,\u0004 ו\u0003שלשה\u0004 לוגים (רבע ההין) \u0003ל\u0004מנחת נסכי ה\u0003כבש.\u0004 ודנים בדברים הללו: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ונסכיהם חצי ההין יהיה לפר\u0004 ושלישית ההין לאיל ורביעית ההין לכבש יין\" (במדבר כח, יד).","והרי שיעור ה\u0003הין\u0004 — \u0003תריסר לוגי הויין\u0004 \u0005[שנים\u0006 \u0003עשר לוגים הוא],\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ו \u0003שמן זית הין\"\u0004 (שמות ל, כד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 לאחר מכן, עוד \u0005בשמן\u0006 \u0005:\u0006 \u0003\"שמן משחת קדש יהיה זה לי לדרתיכם\"\u0004 (שם לא), וכך למדו: המלה \u0003\"זה\" בגימטריא\u0004 — \u0003תריסר הויין\u0004 \u0005[שנים עשר הם].\u0006 ומכאן, ששיעור הנסכים \u0003שנאמר בתורה שהוא מחצית ההין, שלישית ההין ורביעית ההין, הריהו (בהתאם) ששה לוגים (לפר), וארבעה לוגים (לאיל), ושלושה לוגים (לכבש), כנשנה במשנתנו.\u0004","עוד שנינו במשנתנו כי \u0003שלשה ומחצה\u0004 לוגים שמן היו מובאים \u0003ל\u0004הדלקת ה\u0003מנורה\u0004 במקדש, \u0003חצי לוג לכל נר\u0004 משבעת נרות המנורה. ודנים בדברים הללו: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 שכך הוא שיעור השמן הניתן למנורה? — \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים\u0006 בברייתא\u0005]:\u0006 נאמר בהדלקת המנורה \"...ויקחו אליך שמן זית זך כתית למאור להעלות נר תמיד... וערך אותו אהרן ובניו מערב עד בקר לפני ה' חוקת עולם לדורותם מאת בני ישראל\" (שמות כז, כ— כא). והגדרת הזמן \u0003\"מערב עד בקר\"\u0004 באה להורות: \u0003תן לה\u0004 למנורה שמן כ\u0003מדתה\u0004 הראויה של הדלקה, שהוא כדי \u0003שתהא\u0004 המנורה \u0003דולקת והולכת מערב עד בקר. דבר אחר\u0004 אמרו חכמים לפרש פסוק זה בענין אחר: \u0003\"מערב עד בקר\"\u0004 בא לומר ש\u0003אין לך\u0004 עוד \u0003עבודה\u0004 במקדש \u0003ש\u0004היא \u0003כשירה\u0004 אם נעשתה \u0003מערב\u0004 (לאחר הקרבת קרבן התמיד של בין הערביים) \u0003עד בקר אלא\u0004 עבודה \u0003זו בלבד. ושיערו חכמים\u0004 כמה שמן נדרש להדלקה זו — \u0003חצי לוג\u0004 שמן בכל נר ונר משבעת נרות המנורה, להדלקה רצופה \u0003מאורתא ועד צפרא\u0004 \u0005[מהערב\u0006 ועד \u0005הבוקר].\u0006 וכיצד הגיעו חכמים לקביעה זו?","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 כי \u0003מלמעלה למטה שיערו.\u0004 כלומר, מתחילה נתנו כמות שמן הגדולה מחצי לוג בהדלקת הערב, ולמחרת לכשראו שנותר מהשמן, עמדו והפחיתו, והדליקו בערב הבא בכמות מופחתת, עד שהגיעו לכמות השמן שלא נותר ממנה שמן בבוקר, ואפילו בלילות החורף הארוכים. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שדרך הקביעה היתה הפוכה מזו, ש\u0003ממטה למעלה שיערו,\u0004 שנתנו בתחילה פחות ממחצית לוג שמן, ולכשראו שאין כמות זו מספיקה להדלקה עד הבוקר, עמדו והוסיפו עליה, עד שהגיעו לשיעור זה של מחצית לוג שמן.","ומסבירים את נימוקי שתי השיטות הללו: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003ממטה למעלה שיערו\u0004 חכמים ולא מלמעלה למטה — מפני השיקול ש\u0003התורה חסה על ממונן של ישראל,\u0004 ואף חכמים חסו על השמן היתר (על המידה שתיקבע בסוף) המתבזבז. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 כי \u0003ממעלה למטה שיערו\u0004 חכמים ולא מלמטה למעלה (משום השיקול של \"התורה חסה על ממונם של ישראל\") — כי \u0003אין\u0004 נוהגים מנהגי \u0003עניות\u0004 (הנהגות של עניים) \u0003במקום עשירות,\u0004 בבית המקדש, וראוי לעשות את הבדיקה כדרכם של עשירים, ביד רחבה, ואין לדקדק במעט שמן המתבזבז אגב כך.","\u0003מערבין נסכי פרים\u0004 (שמובאים בהם שלושה עשרונים סולת הנבללים בששה לוגים שמן, ונמצא שיעור הבלילה הוא שני לוגים שמן לכל עשרון סולת) \u0003בנסכי אילים\u0004 (שאף בלילתם של אלה היא בשיעור של שני לוגים שמן לכל עשרון סולת. שכן מובאים בנסכי האילים שני עשרונים סולת וארבעה לוגים שמן). וכן מערבים \u0003נסכי כבשים בנסכי כבשים\u0004 אחרים, שכן כל מנחת נסכים של כבשים הריהי באה עשרון של סולת עם שלושה לוגים שמן. וכן מערבים נסכים \u0003של יחיד ב\u0004נסכים \u0003של ציבור,\u0004"],["וכן מערבים נסכים \u0003של\u0004 קרבן שהוקרב ה\u0003יום ב\u0004נסכים \u0003של\u0004 קרבן שהוקרב \u0003אמש,\u0004 אם בלילתם של מנחות הנסכים הללו שווה (כגון ששני הקרבנות הם כבשים, שזה וזה דרך בלילתו היא בשלושה לוגים הניתנים לעשרון סולת אחד). שכן רשאי אדם להביא מנחת נסכיו אף לאחר יום הקרבת קרבנו.","\u0003אבל אין מערבין נסכי כבשים\u0004 (שבלילתם היא בשלושה לוגים שמן הניתנים בעשרון סולת אחד) \u0003בנסכי פרים ואילים\u0004 (שבלילתם היא בשני לוגים שמן הניתנים בעשרון סולת אחד). \u0003ואם בללן\u0004 לאותן המנחות בסלתן ובשמנן כדינן, \u0003אלו\u0004 (מנחות נסכי כבשים) \u0003בפני עצמן ואלו\u0004 (מנחות נסכי פרים ואילים) \u0003בפני עצמן, ו\u0004לאחר \u0003מכן\u0004 \u0003נתערבו\u0004 אלו באלו — הריהם \u0003כשרים\u0004 להקריבן על המזבח. ואולם \u0003אם עד שלא\u0004 \u0003בלל\u0004 את המנחות הללו בסלתן ובשמנן הראוי, נתערבו זו בזו — \u0003פסול\u0004 \u0003להקרבה.\u0004","\u0003הכבש הבא\u0004 (הקרב) \u0003עם\u0004 הנפת \u0003העומר\u0004 למחרת יום טוב ראשון של פסח, \u0003אף על פי שמנחתו\u0004 שהיא שני עשרונים סולת, \u0003כפולה\u0004 משאר מנחות הכבשים, שהן של עשרון סולת — \u0003לא היו נסכיו כפולים\u0004 מנסכיהן של שאר מנחות הכבשים, שאף בו היו מביאים שלושה לוגים שמן ושלושה לוגים יין.","שנינו במשנתנו כי מערבים נסכי פרים בנסכי אילים, ומכאן שמותר לערב את מנחות הנסכים (שדרך בלילתן שווה), \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך, \u0005ממה ששנינו בברייתא\u0006\u0005]\u0006 על הנאמר בדרך הקטרת חלקי קרבן השלמים: \"והקריב מזבח השלמים... את החלב המכסה את הקרב ואת כל החלב אשר על הקרב. ואת שתי הכליות ואת החלב אשר עליהן אשר על פי הכסלים ואת היותרת על הכבד על הכליות יסירנה. והקטירו אותו בני אהרן המזבחה...\" (ויקרא ג, ג— ה).","ובאה בכתוב הלשון \u0003\"והקטירו\u0004 אותו\", בצורת יחיד (אף שמדובר בהקטרתם של דברים רבים, המנויים לפני כן) — להורות שיש להקריב חלביו של כל קרבן לעצמו, \u0003שלא יערב חלבים\u0004 של קרבן זה \u0003בחלבים\u0004 של קרבן זה. וכיוצא בדבר, אין לערב מנחת נסכים של קרבן זה במנחת נסכים של קרבן אחר!","\u0003אמר ר' יוחנן:\u0004 אף משנתנו לא אמרה שמותר לכתחילה לערב נסכים של קרבן זה בנסכים של קרבן אחר, אלא ש\u0003אם נתערבו\u0004 יכול להקריבם \u0003קא אמר\u0004 \u0005[הוא,\u0006 תנא של משנתנו \u0005אומר].\u0006","ומקשים על כך: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמשנתנו מדברת על בדיעבד, יוצא איפוא מכאן כי מה שנאמר בהמשך המשנה \u0003\"ואין מערבין נסכי כבשים בנסכי פרים ואילים\"\u0004 — אין הכוונה לאיסור עירוב לכתחילה, אלא שאסור הדבר מכל וכל, \u0003ואפילו\u0004 אם \u0003נתערבו\u0004 בדיעבד — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יהיו כשרים להקרבה. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 התנא במשנתנו \u0005בסוף\u0006 המשנה\u0005]\u0006 שאם לאחר ש\u0003בללן אלו בפני עצמן ואלו בפני עצמן\u0004 קרה הדבר \u0003ונתערבו\u0004 אלו באלו — \u0003הריהם\u0004 \u0003כשרין\u0004 להקרבה. \u0003ו\u0004\u0003מכלל\u0004 הדברים אתה למד כי ההלכה \u0003דרישא\u0004 \u0005[שבתחילת\u0006 המשנה\u0005]\u0006 הנשנית בלשון \"מערבין\" — ש\u0003לכתחלה\u0004 יכול הוא לערב אותם \u0003קא אמר\u0004 \u0005[הוא אומר]!\u0006","\u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונת דברי משנתנו\u0005]:\u0006 אכן דבר הדומה לחלבים, שאף הוא קרב על המזבח, וכגון סלתן ושמנן של המנחות — אין לערבו, \u0005ואולם\u0006 \u0003מערבין\u0004 את נסכי \u0003יינן\u0004 של הקרבנות שאינם דומים לחלבים שהרי אינם \u0003מוקטרים על המזבח. ואולם אף הם אינם מותרים בעירוב אלא\u0004 \u0003אם\u0004 כן כבר \u0003נתערב סלתן ושמנן\u0004 של המנחות (וכך, אין עוד מקום לחשש, שמתוך שמערבים את היין, יבואו לערב אף את הסולת והשמן).","ושואלים על כך: \u0003ו\u0004כי כך הוא הדין ש\u0003יינן\u0004 של הקרבנות \u0003לכתחלה לא\u0004 מערבים, אלא אם כן התערב כבר סלתן ושמנן של המנחות? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שאינו מערב? — דווקא \u0003בסלת ו\u0004ב\u0003שמן, אבל יין מערבין.\u0004 ומשמע איפוא שמערבים יין בכל אופן, גם אם לא התערבו קודם לכן הסולת והשמן!","\u0003אלא אמר אביי\u0004 בהסבר הדברים: כשאמר התנא של משנתנו \"מערבין נסכי אילים בנסכי פרים\" \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]:\u0006 נסכי היין מותרים לכתחילה בעירוב, ו\u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003הוקטר\u0004 כבר \u0003סלתן ושמנן\u0004 של המנחות — \u0003מערבין יין\u0004 אף \u0003לכתחלה.\u0004 ואף \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003לא הוקטר\u0004 עדיין שמנן וסלתן של המנחות, \u0003אם\u0004 כבר \u0003נתערב סלתן ושמנן\u0004 ושוב אין חשש שמא יבואו לערבם — \u0003מערבין נמי\u0004 \u0005[גם כן]\u0006 את \u0003יינן.\u0004 \u0003ו\u0004אולם \u0003אם לאו\u0004 \u0005[לא]\u0006 נתערבו הסולת והשמן, ועדיין לא הוקטרו — \u0003אין מערבין\u0004 את נסכי היין, מחשש \u0003דלמא\u0004 \u0005[שמא]\u0006 מתוך כך \u0003אתי\u0004 \u0005[יבוא]\u0006 גם \u0003לאיערובי\u0004 \u0005[לערב]\u0006 \u0003סלת ושמן לכתחלה.\u0004","שנינו במשנתנו כי \u0003כבש הבא עם העומר,\u0004 אף שמנחתו היתה כפולה ממנחות שאר קרבנות כבשים, אין נסכיו כפולים משלהם. ובענין זה מביאים עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 במה שנאמר בקרבן העומר \u0003\"ומנחתו שני עשרונים\"\u0004 (ויקרא כג, יב—יג) \u0003לימד\u0004 הכתוב \u0003על כבש הבא עם העומר שמנחתו כפולה\u0004 משאר מנחות הכבשים הבאות רק מעשרון אחד סולת.","\u0003יכול\u0004 שתאמר כי \u0003כשם שמנחתו כפולה\u0004 בשיעורה, \u0003כך\u0004 גם שיעור נסך \u0003יינו\u0004 של כבש זה \u0003כפול\u0004 משל שאר נסכי הכבשים (ששיעורם הוא רבע ההין), ויהא מחצית ההין? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בהמשך הפסוק: \u0003\"ונסכו יין רביעית ההין\"\u0004 — שאינו אלא רביעית ההין. ועדיין \u0003יכול\u0004 שאמנם \u0003לא יהא\u0004 שיעור \u0003יינו\u0004 של הכבש הבא עם העומר \u0003כפול\u0004 משל שאר קרבנות הכבשים, ומהטעם \u0003ש\u0004היין \u0003אינו נבלל עם מנחתו, אבל\u0004 בשמן, שהוא נבלל בסולת המנחה, \u0003יהא\u0004 שיעור \u0003שמנו\u0004 של הכבש הבא עם העומר חצי ההין \u0003כפול\u0004 מזה של שאר קרבנות הכבשים (שהוא רביעית ההין), לפי \u0003ש\u0004הוא \u0003נבלל עם מנחתו?\u0004 לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"ונסכו\u0004 יין רביעית ההין\" — ש\u0003כל נסכיו\u0004 של כבש זה \u0003לא יהו אלא רביעית\u0004 ההין, ולא יותר.","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד]?\u0006 כיצד נלמד הדבר מן הכתוב? \u0003אמר ר' אלעזר:\u0004 ה\u0003כתיב\u0004 של המלה הוא \u0003\"ונסכה\"\u0004 כצורת שיוך המתייחסת לנקבה, \u0003ו\u0004אולם \u0003קרינן\u0004 \u0005[קוראים אנו]\u0006 אותה \u0003\"ונסכו\"\u0004 כצורת שיוך המתייחס לזכר, ומעתה","\u0003כיצד\u0004 ניישב את הדברים? — הרי זה בא ללמד כי \u0003נסכה\u0004 של \u0003מנחה\u0004 זו הריהו \u0003כנסכו\u0004 של \u0003יין, מה\u0004 ה\u0003יין\u0004 לכבש הבא עם העומר שיעורו \u0003רביעית\u0004 ההין, \u0003אף\u0004 ה\u0003שמן נמי\u0004 \u0005[גם כן]\u0006 הניתן במנחתו שיעורו \u0003רביעית\u0004 ההין, ולא יותר.","ומתוך שנידון דינו של הכבש הבא עם העומר, מביאים דברים שיש בהם נגיעה לקרבן זה. \u0003אמר ר' יוחנן: אשם מצורע ששחטו שלא לשמו\u0004 אלא לשם קרבן אחר, אף שלא עלה ולא יצאו בו הבעלים ידי חובתם — הריהו \u0003טעון נסכים\u0004 כאשם מצורע, ושלא כשאר קרבנות אשם, שאין באים אתם נסכים. וטעמו של דבר: \u0003ש\u0004כן הוא כשלעצמו כשר, ו\u0003אם אי\u0004 (אין) \u0003אתה אומר כן\u0004 שהוא בא בנסכים — \u0003פסלתו\u0004 מלקרב על המזבח (שכן אין הוא ראוי לאשם מצורע, כיון שנשחט שלא לשמו, וכן אין הוא ראוי לעולה).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב מנשיא בר גדא: אלא מעתה,\u0004 שכדי למנוע את פסילתו של הקרבן, אתה מטעינו בנסכים, ושלא כדינו המקורי, נאמר כן גם ב\u0003כבש הבא עם העומר ששחטו שלא לשמו,\u0004 ולא יצאו ידי חובתו, ואולם הריהו כשר ודינו כשאר קרבן עולה — יישמר דינו המקורי שהוא בא בשני עשרונים למנחה, ו\u0003תהא מנחתו כפולה\u0004 משל שאר כבשי עולה הבאים בעשרון אחד בלבד. משום השיקול \u0003\"שאם אי אתה אומר כן\u0004 שיובא הכבש כדינו הראשון — \u0003פסלתו\"! ו\u0004כן קרבן","\u0003תמיד של שחר ששחטו שלא לשמו,\u0004 ולא יצאו בכך ידי חובתו, ואולם הריהו כשר ודינו כשאר קרבן עולה — שיישמר דינו הראשון, ו\u0003יהא טעון\u0004 סידור ונתינת \u0003שני גזירין\u0004 של עץ על המזבח, \u0003ב\u0004ידי \u0003כהן אחד,\u0004 וכדרך שעושים בעולת התמיד של שחר (ואין עושים כן בשאר עולות). משום \u0003שאם אי אתה אומר כן\u0004 שיובא הקרבן כדינו הראשון — \u0003פסלתו! ו\u0004כן יש לשאול ביחס לקרבן \u0003ה\u0004\u0003תמיד של בין הערבים ששחטו שלא לשמו,\u0004 שיישמר דינו הראשון, ו\u0003יהא טעון\u0004 סידור ונתינת \u0003שני גזירין\u0004 עצים על המזבח, \u0003ב\u0004ידי \u0003שני כהנים,\u0004 וכדרך שעושים בעולת התמיד של בין הערביים (ואין עושים כן בשאר עולות). משום \u0003שאם אי אתה אומר כן\u0004 שיובא הקרבן כדינו הראשון — \u0003פסלתו!\u0004","ומסכם רב מנשיא בר גדא את שאלתו: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא הדין \u0005גם כן]\u0006 בכל המקרים הללו, שצריך לעשות בהם כאמור. ואולם עדיין קשה מדוע לא הזכיר ר' יוחנן בדבריו אלא אשם מצורע שנשחט שלא לשמו! \u0003אלא אמר אביי:\u0004 אמנם כך הוא הדין, לדעת ר' יוחנן, אף בכל המקרים הללו שנמנו. אלא ש\u0003חדא מינייהו נקט\u0004 \u0005[אחד מהם לקח]\u0006 כדוגמה, וממנו נלמד לשאר המקרים.","ואילו \u0003ר' אבא אמר:\u0004 לא נצרך ר' יוחנן לומר את דבריו בדינם של הקרבנות הללו שנשחטו שלא לשמם, שכן \u0003בשלמא הנך\u0004 \u0005[נניח אלה]\u0006 \u0003עולות נינהו\u0004 \u0005[הם],\u0006"],["ומשום כך יש מקום לומר ש\u0003אי\u0004 \u0005[אם]\u0006 \u0003לא חזו\u0004 \u0005[אינם ראויים]\u0006 \u0003ל\u0004היות קרבים שוב כ\u0003עולת חובה\u0004 (משום שנשחטו שלא לשמם, ולא עלו לחובתם) — לכך \u0003קרבי\u0004 \u0005[יקרבו]\u0006 \u0003לעולת נדבה,\u0004 ויהא דינם כשאר עולות הנדבה. \u0003אלא הכא\u0004 \u0005[כאן,\u0006 באשם מצורע שנשחט שלא לשמו\u0005],\u0006 \u0003אי לא מוקמית ליה במילתיה\u0004 \u0005[אם\u0006 אתה \u0005לא מעמיד אותו בעניינו,\u0006 בדינו הראשון\u0005],\u0006 ולכך מחייבו \u0005אף בנסכים\u0006 — אין לו עוד תקנה כאשם, שהרי \u0003אשם\u0004 הבא ב\u0003נדבה מי איכא\u0004 \u0005[האם יש]?\u0006","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 זו של \u0003ר' יוחנן: אשם מצורע ששחטו שלא לשמו, או שלא נתן\u0004 הכהן \u0003מדמו\u0004 של הקרבן \u0003על גבי\u0004 ה\u0003בהונות\u0004 של המצורע, כנדרש לטהרתו — אין הקרבן עולה למצורע לחובתו, ו\u0003הרי\u0004 בהמה \u0003זו\u0004 תקרב כקרבן \u0003עולה לגבי מזבח, ו\u0004קרבן זה הריהו \u0003טעון נסכים\u0004 כדין נסכי אשם מצורע, \u0003ו\u0004המצורע \u0003צריך אשם אחר\u0004 כדי \u0003להתירו\u0004 מטומאת צרעתו.","\u0003כל\u0004 ה\u0003מדות\u0004 (כלי המדידה) \u0003ש\u0004היו \u0003ב\u0004בית ה\u0003מקדש היו נגדשות\u0004 (שפני הדבר הנמדד בכלים אלה היה נישא מעל לשפת הכלי), \u0003חוץ מ\u0004כלי המידה בו נמדד עשרון הסולת למנחת חביתין \u0003של כהן גדול\u0004 המובאת בכל יום, \u0003שהיה גודשה לתוכה,\u0004 שהיו מודדים עשרון זה במידה גדולה מהרגיל, המכילה עשרון גדוש כשפני הדבר הנמדד בתוך הכלי משתווים לשפת הכלי.","בכלי המשמש \u0003ל\u0004\u0003מדת הלח,\u0004 דין \u0003בירוציהן\u0004 (הדבר הגודש את הכלי וגולש אל מחוצה לו) שהם \u0003קדש. ו\u0004אילו ב\u0003מדת היבש בירוציהן\u0004 \u0003חול,\u0004 שהכלי אינו מקדש אלא את שבתוכו ממש.","\u0003ר' עקיבא אומר:\u0004 בכל \u0003מדת הלח\u0004 כיון שהם עצמם \u0003קדש, לפיכך\u0004 אף \u0003בירוציהן קדש.\u0004 מה שאין כן ב\u0003מדת היבש,\u0004 כיון שהם \u0003חול, לפיכך\u0004 אף \u0003בירוציהן חול. ר' יוסי אומר\u0004 כנגד דברי ר' עקיבא הללו: \u0003לא משום\u0004 טעם \u0003זה,\u0004 \u0003אלא\u0004 הטעם להבדל הוא, \u0003ש\u0004כן הדבר \u0003הלח\u0004 מטבעו \u0003נעקר\u0004 (נייד, נוזלי), ולכך יש מקום לומר שהדבר הלח שנשפך אל מחוץ לכלי עתה, הוא זה שהיה בתוכו בתחילה (והתקדש בו), ובא הנוזל שגדש את הכלי ודחהו אל מחוץ לכלי. \u0003ו\u0004אילו הדבר \u0003היבש\u0004 מטבעו \u0003אינו נעקר\u0004, ולכך יש לומר שהדבר הנגדש אל מחוץ לכלי, לא היה בו אף בתחילתו, ולא התקדש בו.","שנינו במשנתנו כי כל המידות שהיו במקדש היו נגדשות. ותוהים: שנינו לעיל (מנחות פז,א) שנחלקו חכמים ור' מאיר באשר למידות היבש שהיו במקדש, שלדעת חכמים לא היו אלא שני סוגי כלי מדידה, של חצי עשרון ושל עשרון (ובסוגיה למעלה, פז,ב, הוכח כי מחוק היה). ולדעת ר' מאיר היו שלושה: של עשרון מחוק ועשרון גדוש וחצי עשרון. ומעתה יש לשאול, כשיטת \u0003מני\u0004 \u0005[מי,\u0006 מדעות אלה, \u0005היא]\u0006 משנתנו? שכן \u0003אי\u0004 \u0005[אם]\u0006 היא שיטת \u0003ר' מאיר\u0004 — והלוא לשיטתו רק כלי עשרון \u0003חד\u0004 \u0005[אחד]\u0006 \u0003גדוש הוה\u0004 \u0005[היה],\u0006 והאחר היה מחוק, ואילו במשנתנו שנינו שכל המידות שבמקדש היו נגדשות. ו\u0003אי\u0004 \u0005[אם]\u0006 משנתנו היא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — והרי לשיטתם, רק עשרון \u0003חדא\u0004 \u0005[אחד]\u0006 היה, \u0003ומחוק הוה\u0004 \u0005[היה],\u0006 ושלא כדברי משנתנו!","\u0003אמר רב חסדא: לעולם\u0004 משנתנו הריהי כשיטת \u0003ר' מאיר, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 הנאמר בה \u0003\"כל מדות\u0004 שהיו במקדש\"? אין הכוונה לכלי המידה אלא ל\u0003כל\u0004 ה\u0003מדידות\u0004 שהיו במקדש, שכולן נעשו בעשרון גדוש.","עוד שנינו במשנתנו כי \u0003מדת הלח בירוציהן קדש\u0004 ואילו בירוצי מידות היבש אינם קדושים. ובעקבות דברי תנא קמא אלה הובאו דברי ר' עקיבא ודברי ר' יוסי בהסברת ההבדל. ושואלים: מאחר ומוסכם על שלושת החכמים הללו דין הבירוצים \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון הלכתי, \u0005הם חלוקים]?\u0006","ומשיבים: \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]\u0006 כי \u0003מדת הלח נמשחה\u0004 בשמן המשחה, כשאר כלי השרת שבמקדש, \u0003בין\u0004 על פני דפנותיה \u0003מבפנים\u0004 ו\u0003בין\u0004 על פני דפנותיה ש\u0003מבחוץ,\u0004 והתקדשו איפוא גם צדדיה החיצוניים, ולכך הבירוצים הנשפכים על צידו החיצוני של כלי למדידת לח הריהם קדושים. ואילו \u0003מדת\u0004 ה\u0003יבש נמשחה מבפנים\u0004 בלבד, \u0003ולא נמשחה מבחוץ,\u0004 ולכך אין בירוצי מידת היבש מתקדשים.","\u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי \u0003מדת הלח נמשחה בין מבפנים בין מבחוץ,\u0004 ולכך בירוציה התקדשו. בעוד ש\u0003מדת\u0004 ה\u0003יבש לא נמשחה כל עיקר,\u0004 ולכך \u0003אמר ר' עקיבא במשנתנו כי מידת היבש היא עצמה חול, וברור הוא כי בירוציה גם הם חול.\u0004","\u0003ור' יוסי סבר\u0004 \u0005[סבור]\u0006 כי \u0003אידי ואידי\u0004 \u0005[זו וזו,\u0006 מידת הלח ומידת היבש\u0005]\u0006 \u0003נמשחה מבפנים ולא נמשחה מבחוץ, והכא\u0004 \u0003היינו טעמא\u0004 \u0005[וכאן,\u0006 במידת הלח \u0005זהו הטעם]\u0006 שבירוציה מתקדשים — משום שטיבו של ה\u0003לח\u0004 שהוא \u0003נעקר\u0004 ממקומו, \u0003ו\u0004יש מקום לומר כי \u0003מגווה דמנא קא אתי\u0004 \u0005[מתוכו של הכלי הוא,\u0006 חלק הבירוצים, \u0005בא],\u0006 וכבר התקדש מה שנשפך אל מחוץ לכלי, בהיותו בתוך הכלי. \u0003ו\u0004אילו \u0003היבש אינו נעקר\u0004 ממקומו, ולכך הבירוצים לא באו מתוך הכלי, ואין הם קדושים.","ושואלים על טעם זה: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003נעקר מאי הוי\u0004 \u0005[מה נהיה],\u0006 שיתקדשו בכך הבירוצים, והלא \u0003גברא\u0004 \u0005[האדם]\u0006 הנותן את הלח לכלי מדידתו, רק \u0003למאי\u0004 \u0005[למה]\u0006 שהוא \u0003צריך קא מכוין\u0004 \u0005[הוא מכוין]\u0006 שיתקדש, ולא ליותר מזה, ואם כן לא התכוון לקדש את חלק הבירוצים!","\u0003אמר רב דימי בר שישנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב, זאת אומרת\u0004 (מכאן נסיק) כי \u0003כלי שרת מקדשין\u0004 את הנמצא בהם, אף \u0003שלא מדעת\u0004 האדם שנתנו בהם. \u0003רבינא אמר\u0004 הסבר אחר לשאלה זו: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי אכן \u0003כלי שרת אין מקדשין אלא מדעת\u0004 האדם. \u0003ו\u0004מה שהתקדשו הבירוצים, אף שלא היתה כוונת האדם עליהם — אין זה מדין תורה, אלא \u0003גזרה\u0004 היא שגזרו חכמים שיתקדשו, מתוך החשש שאם לא ינהגו קדושה בבירוצים, \u0003שמא\u0004 מתוך כך \u0003יאמרו\u0004 (יבואו אנשים לומר) ש\u0003מוציאין\u0004 (מותר להוציא) \u0003מ\u0004דבר שהתקדש ב\u0003כלי שרת לחול.\u0004","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זירא\u0004 על סברה זו, ממה ששנינו: שולחן הפנים עורכים עליו את לחם הפנים ואת בזיכי הלבונה בשבת, והריהם מונחים על השולחן עד לשבת הבאה, ובשבת הבאה מוקטרת הלבונה שבבזיכים, והלחמים הותרו לאכילה על ידי הקטרה זו. ו\u0003אם\u0004 \u0003סידר\u0004 (ערך) \u0003את הלחם ו\u0004כן \u0003את הבזיכין\u0004 שלא בזמנם הראוי אלא \u0003לאחר השבת, והקטיר את הבזיכין בשבת\u0004 הקרובה — הקטרה זו \u0003פסולה,\u0004 ופוסלת את הלחם (שלא היה ערוך על השולחן משבת לשבת). \u0003כיצד יעשה\u0004 (ינהג) בלחם ובבזיכים הללו כדי שלא ייפסלו? — \u0003יניחנו\u0004 (ישאיר) את הלחם ואת הבזיכים על שולחן הפנים אף \u0003לשבת הבאה,\u0004 ולא יסלק אותם מעל השולחן בשבת הקרובה. וכך יימצא שיתקדשו הלחם והבזיכים בשבת הקרובה, שהרי היו על השולחן משבת לשבת, ובשבת שלאחריה יוחלפו בלחם אחר, וייאכל הלחם. ומותר הדבר, \u0003ש\u0004הרי \u0003אפילו הוא\u0004 הלחם והבזיכים נמצאים \u0003על\u0004 ה\u0003שלחן ימים רבים\u0004 — \u0003אין בכך כלום.\u0004 שכל זמן שלא הורידום מהשולחן, אין בהם דין לינה.","\u0003ו\u0004עתה שאמרנו שחכמים גזרו מפני האומרים מוציאים מכלי שרת לחול, יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הותר הדבר להיעשות כן, והרי \u0003התם נמי לימא\u0004 \u0005[שם,\u0006 בלחם הפנים \u0005גם כן\u0006 יש מקום \u0005לומר]\u0006 שאין לעשות כן, משום \u0003גזירה, שמא יאמרו\u0004 האנשים הרואים שמשאירים לחם על שולחן הפנים מעבר למידת הזמן הרגילה כי \u0003מפקידין\u0004 (מותר להפקיד, לשמור) דברים \u0003בכלי שרת!\u0004","ודוחים את הקושיה: וכי מדבר הנעשה ב\u0003פנים\u0004 (היכל המקדש), כמעשה לחם הפנים, על דבר שנעשה ב\u0003חוץ\u0004 (בעזרה שבמקדש), כמדידה לצורך המנחות, \u0003קא רמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]?!\u0006 שהרי בדבר הנעשה ב\u0003פנים\u0004 בתוך ההיכל — \u0003לאו כולי עלמא ידעי\u0004 \u0005[אין הכל יודעים]\u0006 מה נעשה בו. ואין חשש שהבריות יראו ויבואו לכלל טעות. מה שאין כן בדבר שנעשה ב\u0003חוץ,\u0004 כמדידה לצורך המנחות, \u0003כולי עלמא ידעי\u0004 \u0005[הכל יודעים]\u0006 מה נעשה, ויש לחשוש שעלולים הם להסיק מסקנות מוטעות ממה שראו, ולכך גזרו חכמים בדבר.","מתוך שנידון דינם של בירוצי המידות, מביאים עוד מהנשנה בעניינם. \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במסכת שקלים\u0005]:\u0006 הדבר ה\u0003מותר\u0004 (הנשאר) מן ה\u0003נסכים\u0004 הריהו מיועד לקניית עולות שיוקרבו \u0003ל\u0004צורך קרבנות \u0003קיץ המזבח.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"מותר נסכים\"?\u0004","\u0003ר' חייא בר יוסף אמר:\u0004 הכוונה ל\u0003בירוצי\u0004 ה\u0003מדות.\u0004 שבירוצים אלה נאספים, ובדמיהם קונים עולות לקיץ המזבח. ו\u0003ר' יוחנן אמר:\u0004 משמעות \"מותר נסכים\" היא \u0003כאותה\u0004 הלכה \u0003ששנינו\u0004 במסכת שקלים: אדם \u0003המקבל\u0004 (המתחייב) בהסכם עם גזבר המקדש כי \u0003עליו\u0004 \u0003לספק\u0004 למקדש \u0003סלתות\u0004 (מידות רבות של סולת) למקדש כל השנה כולה, תמורת תשלום הניתן לו מקופת ההקדש. ובשעת ההסכם היה שער הסולת ארבע סאים בסלע אחד. ובמהלך השנה התייקרו הסאים, ועלה שערם \u0003מארבע\u0004 סאים בסלע, \u0003ועמדו בשלש\u0004 סאים בסלע — \u0003יספק\u0004 למקדש ככל כמות הסולת שהתחייב לה, וכשער הקודם, שהוא \u0003מארבע\u0004 סאים בסלע."],["ולחילופין, אם בשעת ההסכם היה שער הסולת שלוש סאים בסלע אחד, ובמהלך השנה הוזלו החיטים \u0003משלש\u0004 סאים בסלע \u0003ועמדו\u0004 על שער של \u0003מארבע\u0004 סאים בסלע — הריהו \u0003מספק\u0004 כמות סלתות למקדש כשער \u0003מארבע\u0004 סאים בסלע. ונמצא שבמקרה זה, הריהו מספק עתה למקדש כמות של סאים הגדולה ממה שהיה מספק בשעת ההסכם. וטעם הדבר שבשני המקרים הללו \u0003ספק הסלתות למקדש הוא המפסיד —\u0004 \u0003ש\u0004בכל עסק שבין ההדיוט להקדש — \u0003יד הקדש על העליונה\u0004 (גוברת). ולדעת ר' יוחנן אותן סאים נוספות הניתנות למקדש (במקרה שבו הוזלו החיטים) הן הנקראות במשנה בשקלים \"מותר נסכים\", והם שמובאים לקיץ המזבח.","ובעקבות שני ההסברים הללו מהו \"מותר נסכים\", מעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' חייא בר יוסף\u0004 האומר ש\"מותר נכסים\" הוא בירוצי המידות, ו\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן\u0004 האומר ש\"מותר נכסים\" הוא תוספת הסאים המסופקות למקדש כשהוזל מחיר החיטים.","ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' חייא בר יוסף:\u0004 \u0003בירוצי מידות הללו מה היו עושין בהן? אם יש זבח\u0004 (קרבן) \u0003אחר\u0004 הקרב באותו יום — \u0003יקריבו עמו\u0004 את הנסכים הללו. \u0003ואם\u0004 לא היה זבח אחר שיבואו בו כנסכיו, ו\u0003לנו\u0004 (עבר על הבירוצים הללו לילה, בלא שקרבו) — \u0003יפסלו\u0004 בכך \u0003בלינה. ואם לאו\u0004 \u0005[לא]\u0006 הובאו הבירוצים כנסכי זבח אחר, ולא נפסלו בלינה — \u0003מקיצין בהן את המזבח, ו\u0004מסבירים: \u0003קיץ\u0004 המזבח \u0003ה\u0004\u0003זה מהו\u0004 עניינו? יפדו אותם, ויקנו בדמיהן בהמות ל\u0003עולות,\u0004 ויתקיים בהם דין העולה: \u0003הבשר\u0004 קרב כולו \u0003לשם\u0004 על המזבח, \u0003ו\u0004ה\u0003עורות\u0004 ניתנים \u0003לכהנים.\u0004","וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: המקבל עליו לספק\u0004 למקדש במשך השנה \u0003סלתות,\u0004 ובאותה שעה היה שער החיטים \u0003מארבע\u0004 סאים בסלע, והתייקרו החיטים \u0003ועמדו\u0004 על שער \u0003משלש\u0004 סאים בסלע — הריהו \u0003מספק\u0004 למקדש כשער הזול שהוא \u0003מארבע\u0004 סאים בסלע. וכן אם כאשר קיבל עליו לספק את הסלתות למקדש היה שער החיטים \u0003משלש\u0004 סאים בסלע, ולאחר מכן הוזלו החיטים, \u0003ועמדו\u0004 בשער שהוא \u0003מארבע\u0004 סאים בסלע — הריהו \u0003מספק\u0004 למקדש כשער הזול, שהוא \u0003מארבע\u0004 סאים בסלע. וטעם הדבר הוא משום \u0003שיד הקדש על העליונה, וזהו ששנינו: מותר נסכים לקיץ המזבח.\u0004","\u0003כל קרבנות הציבור והיחיד טעונין נסכים, חוץ מן ה\u0004קרבנות הבאים: \u0003בכור\u0004 הבהמה, \u0003ו\u0004קרבן \u0003המעשר\u0004 הבא מן הבהמה, \u0003ו\u0004קרבן \u0003הפסח, והחטאת, והאשם\u0004 שאינם טעונים הבאת נסכים עם הקרבתם. ואין זה כלל מוחלט ביחס לחטאות ואשמות, \u0003אלא שחטאתו של מצורע ואשמו\u0004 יוצאים מן הכלל, ששני קרבנות אלה, אף שהם חטאת ואשם \u0003טעונין נסכים.\u0004","שנינו במשנתנו כי כל הקרבנות, הן של ציבור והן של יחיד, חייבים בהבאת נסכים. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא \u0005על הנאמר בכתובי פרשת הנסכים. שכן בתחילה נאמר \"...כי תבואו אל ארץ מושבותיכם אשר אני נותן לכם. ועשיתם אשה לה' עולה או זבח לפלא נדר או בנדבה או במועדיכם לעשות ריח ניחוח לה' מן הבקר או מן הצאן\" (במדבר טו, ב—\u0006 ג). ובדינם של הקרבנות הללו נאמר בהמשך הכתובים \"והקריב המקריב קרבנו לה' מנחה סולת עשרון בלול ברביעית ההין שמן. ויין לנסך רביעית ההין תעשה על העולה או לזבח לכבש האחד\" (שם ד—ה).","ומעתה יש לדון בכתובים הללו: מן האמור \u0003\"ועשיתם אשה לה' \"\u0004כשלעצמו — \u0003יכול\u0004 היית ללמוד כי \u0003כל העולה לאישים\u0004 (על אש המזבח לקרבן) \u0003יהא טעון\u0004 הבאת \u0003נסכים\u0004 עימו, ש\u0003אפילו מנחה\u0004 תהא חייבת בנסכים. לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בכתוב זה \u0003\"עלה\",\u0004 שאין דין הנסכים אמור אלא בעולה, ולא במנחה. ומעתה \u0003שלמים מנין\u0004 לנו שאף הם טעונים נסכים? לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"זבח\",\u0004 שאף השלמים בכלל חיוב נסכים. קרבן \u0003תודה מנין\u0004 לנו שאף הוא טעון נסכים? \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"או זבח\",\u0004 שהוא לשון ריבוי.","ומעתה, לאחר \u0003שריבינו אף את התודה לענין חיוב הנסכים, יש לשאול:\u0004 \u0003יכול שאני מרבה\u0004 מכתוב זה לחיוב נסכים \u0003אף\u0004 \u0003את\u0004 \u0003בכור\u0004 הבהמה, \u0003ו\u0004את \u0003מעשר\u0004 בהמה, \u0003ו\u0004את קרבן ה\u0003פסח, ו\u0004את קרבנות ה\u0003חטאת ו\u0004ה\u0003אשם?\u0004 \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"לפלא נדר או בנדבה\"\u0004 — לומר: רק קרבן ה\u0003בא בנדר ונדבה\u0004 (כקרבנות העולה, השלמים והתודה, שלמדנו בהם שהם חייבים בנסכים) הוא ה\u0003טעון נסכים.\u0004 ואילו זה \u0003שאינו בא בנדר ונדבה\u0004 — \u0003אין\u0004 הוא \u0003טעון נסכים,\u0004 ולכך הקרבנות הללו, הבאים רק כחובה, אינם טעונים נסכים.","וממשיכים ודנים: אם כן, אחר ש\u0003משמע\u0004 (שנשמע, שלמדנו) שיש \u0003להוציא\u0004 (למעט) \u0003את אלו\u0004 (בכור, מעשר, פסח, חטאת ואשם) מכלל הטעונים נסכים, משום שהם באים בחובה, אבוא ו\u0003אוציא\u0004 גם \u0003את\u0004 קרבנות \u0003חובות הבאות מחמת הרגל ברגל, ומאי נינהו\u0004 \u0005[ומה הם]?\u0006 \u0003עולות ראייה ושלמי חגיגה?\u0004 לכך \u0003תלמוד לומר\u0004 עוד בכתוב זה \u0003\"או במועדיכם\"\u0004 — להורות: \u0003כל הבא במועדיכם\u0004 (אף שהוא של חובה, כעולות ראיה ושלמי חגיגה) הריהו \u0003טעון נסכים.\u0004","אם כן, \u0003משמע\u0004 (לאחר ששמעתי) כי יש \u0003להביא\u0004 (לרבות) לחיוב נסכים אף \u0003את אלו\u0004 הבאים במועדים, \u0003אביא\u0004 אף את \u0003שעירי חטאת\u0004 של מוספי הרגלים שיהיו טעונים נסכים, \u0003הואיל ו\u0004הם \u0003באין חובה ברגל?\u0004 \u0003תלמוד לומר\u0004 בהמשך אותם כתובים \u0003\"וכי\u0004 תעשה בן בקר עולה או זבח לפלא נדר או שלמים לה'. והקריב על בן הבקר מנחה סולת... ויין תקריב לנסך חצי ההין אשה ריח ניחוח לה' \" (במדבר טו, ט—י). ויש לשאול: והלא \u0003בן\u0004","\u0003בקר\u0004 כבר \u0003בכלל היה,\u0004 שהריהו נמנה בתחילת הפרשה (\"מן הבקר\") \u0003ולמה יצא?\u0004 להזכירו שוב? על מנת \u0003להקיש אליו\u0004 את הקרבנות האחרים החייבים אף הם בנסכים, שיהיו קרבנות אלה בדומה לבן בקר: \u0003מה בן בקר\u0004 הריהו \u0003מיוחד\u0004 שהוא \u0003בא\u0004 בקרבן \u0003בנדר ונדבה, אף כל\u0004 קרבן ה\u0003בא בנדר ונדבה\u0004 הוא החייב בנסכים. ודורשים עוד בפסוקי פרשת הנסכים.","זה שנאמר בה \u0003\"לעשות ריח ניחח לה' מן הבקר או מן הצאן\" מה תלמוד לומר?\u0004 ומסבירים: \u0003לפי שנאמר\u0004 בפסוק זה לפני כן \u0003\"עלה\",\u0004 ומלשון זו אפשר כי \u0003שומע\u0004 (מבין) \u0003אני\u0004 שהכוונה לכל סוגי העולות, ו\u0003אפילו עולת העוף במשמע\u0004 הדברים, ונתחייבה בנסכים. לכך \u0003תלמוד לומר\u0004 \"לעשות ריח ניחוח לה' \u0003מן הבקר או מן הצאן\",\u0004 ללמד שאין מביאים נסכים אלא בקרבן הבהמה ולא בקרבן העוף. אלו \u0003דברי ר' יאשיה.\u0004","ואילו \u0003ר' יונתן אומר:\u0004 כדי ללמדנו שעולת העוף אינה טעונה נסכים, \u0003אינו צריך\u0004 לכך פסוק זה, ש\u0003הרי הוא\u0004 הכתוב \u0003אומר \"זבח\", ועוף אינו\u0004 נקרא \u0003\"זבח\". אם כן מה תלמוד לומר\u0004 \"לעשות ריח ניחוח לה' \u0003מן הבקר או מן הצאן\"? לפי שנאמר\u0004 בפתיחה לפרשת העולה: \u0003\"...אדם כי יקריב מכם קרבן לה' מן הבהמה מן הבקר ומן הצאן\u0004 תקריבו את קרבנכם\" (ויקרא א, ב), \u0003יכול\u0004 שנלמד מכתוב זה בדינו של האדם \u0003ה\u0004מקדיש קרבן והריהו \u0003אומר\u0004 בלשון \u0003\"הרי עלי עולה\"\u0004 בלא שפירט בלשונו איזו עולה כוונתו, ש\u0003יביא\u0004 בפרעון נדרו \u0003משניהם.\u0004 לכך \u0003תלמוד לומר \"מן הבקר או מן הצאן\",\u0004 לומר: \u0003רצה אחד\u0004 מהם — \u0003מביא, רצה שנים\u0004 — \u0003מביא.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יונתן, למה לי קרא\u0004 \u0005[מקרא]\u0006 ללמדנו ענין זה? \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' יונתן עצמו ככלל בדרך דרשת הכתובים: אין משמעם של שני דברים הנזכרים במקרא כאשר וי\"ו החיבור מאגדם, לומר שיהיו שניהם כאחד, \u0003עד שיפרוט\u0004 (יפרש) \u0003לך הכתוב\u0004 ויאמר בהם את המלה \u0003\"יחדו\".\u0004 ואם כן, אף בענייננו, אין מקום לומר ש\"מן הבקר ומן הצאן\" כוונתו לומר שיביא את שניהם כאחד!","ומשיבים: אף שאכן כך הוא הכלל לשיטת ר' יונתן, בענייננו \u0003איצטריך\u0004 \u0005[נצרך]\u0006 כתוב מיוחד להשמיענו שאין הכוונה לשניהם כאחד, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006"],["\u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 מלבד \"מן הבקר \u0003ומן הצאן\"\u0004 \u0003(ויקרא א, ב), ולא נאמר \"מן הצאן\" בלבד\u0004 — הרי זה \u0003כמאן דכתיב\u0004 \u0005[כמו שנכתב]\u0006 \u0003\"יחדו\" דמי\u0004 \u0005[נחשב].\u0006 ומשום כך, הוצרך כתוב מיוחד המלמד שאין שניהם באים כאחד.","ושואלים: \u0003ול\u0004דעת \u0003ר' יאשיה\u0004 החלוק על שיטת ר' יונתן ו\u0003אמר\u0004 לגבי הכתובים המצורפים ביניהם באמצעות אות וי\"ו החיבור כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא כתיב\u0004 \u0005[לא כתוב]\u0006 \u0003\"יחדו\"\u0004 — הרי זה \u0003כמאן דכתיב\u0004 \u0005[כמו שנכתב]\u0006 \u0003\"יחדו\" דמי\u0004 \u0005[נחשב],\u0006 ולשיטתו, \u0003ליבעי קרא\u0004 \u0005[נצרך ה\u0006\u0003מקרא\u0004 \"מן הבקר או מן הצאן\"\u0003]\u0004 ללמד שאין הכוונה לשניהם כאחד, ומעתה אין הוא יכול לדרוש מכתוב זה שבא למעט את עולת העוף מנסכים!","ומשיבים: לדעת \u0003ר' יאשיה אין אנו נזקקים לכתוב \"מן הבקר או מן הצאן\" כדי ללמדנו זאת, שכן\u0004 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 בפרשת עולה שבתחילת ספר ויקרא \u0005:\u0006 \u0003\"אם עלה קרבנו מן הבקר\"\u0004 (שם ג), ולאחר מכן נאמר \u0003\"ואם מן הצאן קרבנו\"\u0004 (שם י), והרי זה מורה שהאומר \"הרי עלי עולה\" מביא קרבן עולה אחד, ולא שניים.","ושואלים עתה לצד שכנגד, \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יונתן\u0005]\u0006 שלא אמר כן, ונצרך לו הכתוב שבספר במדבר \"מן הבקר או מן הצאן\", מדוע אין הוא אומר כר' יאשיה? ומשיבים: עדיין \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הכתוב \"מן הבקר או מן הצאן\" ללמד שהנודר \"הרי עלי עולה\" מביא קרבן אחד. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה],\u0006 שאמר הכתוב שיביא הנודר עולה בנדרו או מבן הבקר או מן הצאן, אמורים דווקא \u0003ב\u0004מקרה שהנודר \u0003מפרש\u0004 את נדרו, שיהא מן הבקר או מן הצאן. \u0003אבל\u0004 זה הנודר \u0003בסתמא\u0004 \u0005[בסתם],\u0006 שלא פירש מה הוא מביא — היה מקום לומר \u0003לייתי מתרוייהו\u0004 \u0005[\u0006ש\u0005יביא משניהם],\u0006 לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \"מן הבקר או מן הצאן\" \u0005משמיע לנו]\u0006 שמביא אחד מהם בלבד.","ודנים עוד בדברי הברייתא. \u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 קרבן \u0003תודה מנין\u0004 לנו שאף הוא טעון נסכים? \u0003—\u0004 \u0003תלמוד לומר \"או זבח\"\u0004 (במדבר טו, ג). ותוהים: מדוע נזקקים אנו לריבוי זה, \u0003אטו\u0004 \u0005[וכי]\u0006 קרבן \u0003תודה לאו\u0004 \u0005[לא]\u0006 בכלל \u0003זבח הוא,\u0004 וכדרך שנלמדו קרבנות השלמים מהכתוב \"זבח\" לענין הנסכים, כך יילמד קרבן התודה! ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לימוד מיוחד זה (\"או זבח\"), שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואיכא\u0004 \u0005[ויש]\u0006 \u0003לחם\u0004 הבא \u0003בהדה\u0004 \u0005[עימה,\u0006 עם התודה\u0005],\u0006 מעתה שוב \u0003לא תיבעי\u0004 \u0005[לא תצטרך]\u0006 התודה אף \u0003נסכים.\u0004","ושואלים: ומדוע נחשוב כך, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 קרבן התודה \u0003מ\u0004קרבן \u0003איל\u0004 שלמים שאותו מביא ה\u0003נזיר,\u0004 \u0003דאיכא בהדיה\u0004 \u0005[שיש עימו]\u0006 \u0003לחם\u0004 (כאמור בו \"וזאת תורת הנזיר ביום מלאת ימי נזרו... והקריב את קרבנו לה'... ואיל אחד תמים לשלמים. וסל מצות סולת חלות בלולות בשמן ורקיקי מצות משוחים בשמן ומנחתם ונסכיהם\". שם ו, יג— טו), \u0003ו\u0004בכל זאת \u0003בעי\u0004 \u0005[צריך]\u0006 להביא עימו גם \u0003נסכים?\u0004","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שיש להבדיל בין קרבן תודה לקרבן איל נזיר, שכן \u0003התם\u0004 \u0005[שם,\u0006 באיל נזיר\u0005]\u0006 הריהו מביא רק \u0003שני מינין\u0004 של לחם מצה (חלות, ורקיקים), ולכן עליו להוסיף ולהביא אף נסכים, ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 בקרבן תודה\u0005]\u0006 הריהו מביא \u0003ארבעת מינין\u0004 של לחם (שלושה של מצה: חלות, רקיקים, ורבוכה, ואחד של חמץ). והיה מקום לומר כי בשל ריבוי לחמיה לא תצטרך התודה לנסכים, לכך בא ריבוי זה \"או זבח\" ו\u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שבכל זאת היא טעונה נסכים.","עוד שנינו בברייתא על האמור בראשית פרשת הנסכים \"ועשיתם אשה לה' עולה או זבח לפלא נדר או בנדבה או במועדיכם לעשות ריח ניחוח לה' מן הבקר או מן הצאן\" (שם טו, ג), שמן האמור \"ועשיתם אשה לה' \" היה מקום לומר שכל קרבן העולה על המזבח חייב בנסכים, ולכך בא הכתוב \"עולה\" לומר שכך הדין רק בקרבן העולה. ובהמשך שנינו שהיה מקום לומר שאף קרבנות הבכור והמעשר והפסח והחטאת יהיו טעונים נסכים, לכך בא הכתוב \"לפלא נדר או בנדבה\" ללמד שאין מביאים נסכים אלא בקרבנות הבאים בנדר. \u0003ו\u0004שואלים: עתה שלמדנו כן מהכתוב \"לפלא נדר או בנדבה\", \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב\u0006 \u0003התורה]\u0004 רק את הכתוב \u0003\"לפלא נדר או לנדבה\" ולא בעי\u0004 \u0005[ולא צריך]\u0006 לומר במפורש \u0003\"עלה\",\u0004 שהרי אף העולה הריהי בכלל הקרבנות הבאים בנדר!","ומשיבים: \u0003אי לא כתב רחמנא\u0004 \u0005[אם לא היתה כותבת התורה]\u0006 \u0003\"עלה\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי כך יש לדרוש את הפסוק שלפנינו: \u0003\"ועשיתם אשה לה' \"\u0004— הרי זה \u0003כלל\u0004 (הכולל את כל הקרבנות העולים על אש המזבח), והכתוב \u0003\"לפלא נדר או לנדבה\"\u0004 — הרי זה \u0003פרט\u0004 (שהרי אין עניינו אלא בקרבנות הבאים בנדר), ובכתוב הבא לאחר מכן \u0003\"לריח ניחח\"\u0004 — \u0003חזר וכלל\u0004 (שכן כל הקרבנות עניינם הריצוי), ואם כן, הרי זה \u0003כלל ופרט וכלל,\u0004 ולפי כללי מדרש הלכה בזמן שכלל ופרט וכלל לפנינו — \u0003אי\u0004 (אין) \u0003אתה דן\u0004 (למד את דינם של הדברים המתרבים על ידי הכלל) \u0003אלא\u0004 רק אותם הדברים שהם \u0003כעין הפרט.\u0004 ובענייננו היה מקום לומר: \u0003מה הפרט מפורש\u0004 בכתוב שהוא \u0003דבר שאינו בא על חטא\u0004 אלא בנדר ונדבה, שהוא הטעון נסכים. \u0003אף כל\u0004 קרבן \u0003שאין בא על חטא,\u0004 טעון נסכים.","ומעתה, \u0003אוציא\u0004 מכלל הטעונים נסכים רק את קרבנות ה\u0003חטאת ו\u0004ה\u0003אשם, ש\u0004הרי \u0003הן באין על חטא.\u0004 ומן הצד האחר, שמא תאמר כי \u0003אביא\u0004 (ארבה) בכלל הקרבנות הטעונים נסכים אף \u0003את ה\u0004\u0003בכור ו\u0004את ה\u0003מעשר ו\u0004את ה\u0003פסח, ש\u0004הרי \u0003אין\u0004 הם \u0003באין על חטא\u0004 — לכך \u0003תלמוד לומר \"עלה\"\u0004 הממעט אף את הבכור, מעשר ופסח.","ושואלים: \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 הכתוב \u0003\"עלה\"\u0004 הממעט את אלה, אם כן \u0003כלל ופרט\u0004 וכלל המופיעים בפסוק זה, \u0003מה מרבית ביה\u0004 \u0005[אתה מרבה בו]\u0006 שאף הוא יהא טעון נסכים? ומסבירים: \u0003מה הפרט\u0004 (\"לפלא נדר או בנדבה\") \u0003מפורש ש\u0004הוא \u0003דבר ש\u0004\u0003אינו מחוייב ועומד\u0004 בלא התחייבותו בנדרו, \u0003אף כל\u0004 דבר \u0003שאינו מחוייב ועומד\u0004 בו טעון נסכים, ומכאן יש","\u0003להביא\u0004 (לרבות) לחיוב נסכים אף את \u0003ולדות\u0004 ה\u0003קדשים\u0004 (הנולדים מבהמות נקבות, של שלמים) \u0003ו\u0004כן את \u0003תמורתן\u0004 של קרבנות (כגון שהמיר את העולה בבהמת חולין, שאף בהמה זו קרבה לעולה וטעונה נסכים). \u0003ו\u0004כן את קרבן ה\u0003עולה הבאה מן המותרות.\u0004","\u0003ו\u0004כן את קרבן ה\u0003אשם\u0004 שהתכפרו בעליו בקרבן אחר, \u0003ש\u0004הריהו \u0003ניתק\u0004 (מוצא) \u0003לרעיה\u0004 עד שיפול בו מום, ומשנפל בו מום הריהו נפדה ודמיו ניתנים לקרבן עולה כקיץ המזבח. \u0003ו\u0004כן הרי זה בא לרבות לחיוב נסכים את \u0003כל הזבחים שנזבחו שלא לשמן.\u0004","וממשיכים לדון בדברי הברייתא: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמרת\u0004 שהלשון \u0003\"או\u0004 זבח\" בא \u0003לדרשא,\u0004 להורות שאף התודה טעונה נסכים, והכתוב \u0003\"לפלא נדר או לנדבה\"\u0004 מלמד שכל הבא בנדבה טעון נסכים, והתודה בכלל, אם כן \u0003למה לי\u0004 עוד לדרוש את הכתוב \"או זבח\" \u0003לחלקם,\u0004 את הבא בנדר ואת הבא בנדבה? ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר לחלקם, כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 שאין חיוב הנסכים אלא בנדר ונדבה כאחד, ו\u0003עד דמייתי\u0004 \u0005[שמביא]\u0006 \u0003נדר\u0004 לחוד \u0003ונדבה\u0004 לחוד, \u0003לא ליבעי\u0004 \u0005[לא יצטרך]\u0006 \u0003נסכים,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[\u0006הכתוב \"או זבח\", \u0005משמיע לנו],\u0006 שאף \u0003דאייתי\u0004 \u0005[שהביא]\u0006 \u0003נדר לחודיה\u0004 \u0005[לחוד]\u0006 — \u0003ליבעי\u0004 \u0005[שיצטרך]\u0006 \u0003נסכים, ואי אייתי\u0004 \u0005[ואם הביא]\u0006 \u0003נדבה לחודיה\u0004 \u0005[לחוד]\u0006 — \u0003לייתי\u0004 \u0005[שיביא]\u0006 \u0003נסכים.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' יאשיה\u0004 שאם לא נאמר בשני דברים הנאמרים ביחד הלשון \"או\" — לא היינו יודעים שיש לחלק ביניהם. ואף בענייננו נזקקים אנו למלה \"או\" כדי לחלק בין נדר ונדבה. \u0003אלא ל\u0004שיטת \u0003ר' יונתן\u0004 (המובאת שם) כי כל עוד לא נאמר בכתוב במפורש \"יחדו\" הכוונה היא לכל אחד מהדברים המנויים בו לחוד, \u0003למה לי\u0004 כתוב זה \"או זבח\"? ומשיבים: לולא כתוב זה \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 שאם \u0003אייתי\u0004 \u0005[הביא]\u0006 \u0003נדר לחודיה\u0004 \u0005[לבדו]\u0006 — \u0003ליבעי\u0004 \u0005[שיצטרך]\u0006 \u0003נסכים,\u0004 ואם \u0003אייתי\u0004 \u0005[הביא]\u0006 \u0003נדבה לחודיה\u0004 \u0005[לעצמה]\u0006 — \u0003ליבעי\u0004 \u0005[שיצטרך]\u0006 \u0003נסכים,\u0004 ואולם אם \u0003אייתי\u0004 \u0005[הביא]\u0006 שני קרבנות, האחד של \u0003נדר ו\u0004האחר של \u0003נדבה\u0004 — \u0003תיסגי\u0004 \u0005[שיהיה די]\u0006 \u0003בנסכים דחד\u0004 \u0005[של אחד\u0006 מהם\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 הכתוב \"או\" \u0005משמיע לנו]\u0006 שצריך להביא נסכים לכל אחד ואחד בנפרד.","עוד שנינו בברייתא כי הכתוב \"או במועדיכם\" בא להורות כי כל הבא במועד (עולות ראיה ושלמי חגיגה), אף שהוא חובה, טעון נסכים. ושואלים עתה: הכתוב הנוסף \u0003\"או במועדיכם\" למה לי?\u0004 ומשיבים: נצרך הכתוב, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 באשר לחיוב נסכים של עולות ראיה ושלמי חגיגה אמורים רק בזמן \u0003דקא מייתי\u0004 \u0005[שהוא מביא]\u0006 קרבן \u0003עולה בנדר ושלמים בנדבה,\u0004 ואלו הם שני קרבנות שונים הבאים בחיובים שונים. \u0003אי נמי איפכא\u0004 \u0005[או גם כן ההיפך],\u0006 כאשר הוא מביא עולה בנדבה ושלמים בנדר.","\u0003אבל היכא דקא מייתי\u0004 \u0005[היכן,\u0006 במקרה \u0005שהוא מביא]\u0006 \u0003עולה ושלמים בנדר,\u0004 והרי אלה שני קרבנות שונים הבאים בסוג חיוב אחד, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 בדומה לכך כאשר הוא מביא \u0003עולה ושלמים בנדבה,\u0004 היינו אומרים שכיון ש\u0003שם נדר אחד\u0004 הוא, \u0003ושם נדבה אחת היא, ו\u0004משום כך \u0003תיסגי ליה\u0004 \u0005[יהיה די]\u0006 \u0003בנסכים דחד\u0004 \u0005[של אחד\u0006 מהם\u0005]\u0006 לשניהם גם יחד, לכך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 בכתוב \u0003\"או במועדיכם\"\u0004 שכל אחד ואחד מהם טעון נסכים.","ודנים עוד בדברי הכתובים המוזכרים בברייתא. נאמר \u0003\"וכי תעשה בן בקר עלה או זבח\u0004 לפלא נדר או שלמים לה'. והקריב על בן הבקר מנחה סולת... ויין תקריב לנסך חצי ההין אשה ריח ניחוח לה' \" (במדבר טו, ט— י). ויש לשאול: לשון \"או\" האמורה בכתוב \u0003(\"עולה או זבח\")\u0004 \u0003למה לי,\u0004 מה מלמדנו בכך הכתוב? ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 האמורים בתורה בחיוב הנסכים הן בעולה והן בשלמים, נוהגים רק \u0003היכא דקא מייתי\u0004 \u0005[היכן,\u0006 בזמן, \u0005שהוא מביא]\u0006 שני קרבנות שונים, \u0003עולה ושלמים בנדר, אי נמי\u0004 \u0005[או גם כן]\u0006 כאשר הוא מביא \u0003עולה ושלמים בנדבה,\u0004 וכיון שהם קרבנות שונים (אף שבאים בסוג חיוב זהה) הריהם חייבים בשני נסכים.","\u0003אבל היכא דקא מייתי\u0004 \u0005[היכן,\u0006 בזמן \u0005שהוא מביא]\u0006 \u0003שתי עולות, חדא\u0004 \u0005[אחת]\u0006 \u0003בנדר וחדא\u0004 \u0005[ואחת]\u0006 \u0003בנדבה, אי נמי\u0004 \u0005[או גם כן]\u0006 כאשר הוא מביא \u0003שני שלמים, אחד בנדר ואחד בנדבה, אימא\u0004 \u0005[\u0006היה מקום ש\u0005תאמר]\u0006 כי כיון ש\u0003שם שלמים אחת היא\u0004 \u0003וכן\u0004 \u0003שם עולה אחת היא, ו\u0004משום כך בכל אחד מהאופנים הללו \u0003תיסגי ליה\u0004 \u0005[יהיה די לו]\u0006 \u0003בנסכים דחד\u0004 \u0005[של אחד],\u0006 לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \"או\" \u0005משמיע לנו]\u0006 שיש לחלק ולהביא שני נסכים נפרדים, לזה ולזה\u0005.\u0006","עוד הוזכר בברייתא הכתוב \"וכי תעשו בן בקר עולה או זבח \u0003לפלא נדר או שלמים\u0004 לה'. והקריב על בן הבקר מנחה סולת... ויין תקריב לנסך חצי ההין אשה ריח ניחוח לה' \". ויש לשאול: לשון \"או\" האמורה בכתוב \u0003(\"לפלא נדר או שלמים\")\u0004 \u0003למה לי?\u0004 ומשיבים: נצרך הדבר להיאמר. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 האמורים בתורה, בחיוב הנסכים הן בעולה והן בשלמים, נוהגים רק \u0003היכא דמייתי\u0004 \u0005[היכן,\u0006 בזמן, \u0005שמביא]\u0006 שני קרבנות שווים, ואולם הריהם באים מסוגי חיוב שונים, וכגון שמביא \u0003שתי עולות, חדא\u0004 \u0005[אחת]\u0006 \u0003בנדר, וחדא\u0004 \u0005[ואחת]\u0006 \u0003בנדבה. אי נמי\u0004 \u0005[או גם כן]\u0006 כשהוא מביא \u0003שני\u0004 קרבנות \u0003שלמים, חדא\u0004 \u0005[אחת]\u0006 \u0003בנדר, וחדא\u0004 \u0005[ואחת]\u0006 \u0003בנדבה.\u0004","\u0003אבל היכא דקא מייתי\u0004 \u0005[היכן,\u0006 בזמן \u0005שהוא מביא]\u0006 \u0003שתי עולות בנדר, ו\u0004כן בזמן שמביא \u0003שתי עולות בנדבה, אי נמי\u0004 \u0005[או גם כן]\u0006 כשהוא מביא \u0003שני\u0004 קרבנות \u0003שלמים בנדר ו\u0004כן כשמביא \u0003שני שלמים בנדבה,\u0004 הייתי אומר במקרים אלה, שכיון \u0003שהן\u0004 \u0003שם\u0004 ה\u0003עולה אחד הוא ו\u0004הן \u0003שם נדר אחד הוא\u0004 — \u0003ותיסגי ליה\u0004 \u0005[ויהיה די לו]\u0006 \u0003בנסכים דחד\u0004 \u0005[של אחד],\u0006 לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \"או\" \u0005משמיע לנו]\u0006 שמביא שני נסכים, לזה ולזה\u0005.\u0006","עוד הוזכר בברייתא הכתוב בפרשת הנסכים \"מן הבקר או מן הצאן\", ולמדנו בעמוד הקודם כי ר' יאשיה למד מכתוב זה שבא למעט את עולת העוף מחיוב הנסכים, ואילו ר' יונתן למד שבא הכתוב לחלק, שאם נדר אדם ואמר \"הרי עלי עולה\" בלא שפירש את כוונתו, שאינו מביא מן הבקר ומן הצאן יחד, אלא אחד מהם, איזה שירצה. ועתה שואלים: \u0003ו\u0004לדעת \u0003ר' יאשיה האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"מן הבקר או מן הצאן\"\u0004 שנאמר בו \"או\" \u0003למה לי,\u0004 מה הוא דורש בו?","ומשיבים: נצרך הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שלמדנו, שהריהו מביא שני נסכים בשני קרבנות, אמורים דווקא \u0003[ב\u0004מקרה שמביא \u0003תרי מיני\u0004 \u0005[שני מינים]\u0006 של בהמה, אחד מן הצאן והשני מן הבקר\u0005,\u0006 \u0003אבל ב\u0004זמן שהביא \u0003חד מינא\u0004 \u0005[מין אחד]\u0006 — \u0003תסגי ליה\u0004 \u0005[יהיה די לו\u0006] \u0003בנסכים דחד\u0004 \u0005[של אחד\u0006 מהם\u0005],\u0006 לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 הכתוב \"או\" \u0005משמיע לנו]\u0006 שהריהו מביא שני נסכים, לזה ולזה.","עוד נאמר בפרשת הנסכים בדין נסכי כל שור או איל או שה הקרבים \"כמספר אשר תעשו \u0003ככה תעשו לאחד\u0004 כמספרם\" (שם יב), ושואלים: \u0003למה לי\u0004 מקרא זה? ומשיבים: נצרך הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 שכל קרבן מאלה \u0005טעון נסכים, ואולם\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006\u0003]\u0004 אמורים רק כאשר הם מובאים \u0003בזה אחר זה. אבל\u0004 אם הם מובאים \u0003בבת אחת\u0004 — \u0003תיסגי ליה\u0004 \u0005[יהיה די לו]\u0006 \u0003בנסכים דחד\u0004 \u0005[של אחד\u0006 מהם\u0005],\u0006 לכך הכתוב \"ככה תעשו לאחד כמספרם\" \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמביא שני נסכים, לזה ולזה.","שנינו במשנתנו שאף שככלל קרבנות החטאת והאשם אינם טעונים נסכים, \u0003אלא\u0004 שקרבן \u0003חטאתו של מצורע ו\u0004כן קרבן \u0003אשמו\u0004 נבדלים משאר חטאות ואשמות, ו\u0003הריהו\u0004 \u0003טעון נסכים.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין\u0006 נלמדים \u0005הדברים הללו]\u0006 שחטאתו ואשמו של המצורע טעונים נסכים? ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 בברייתא: מה שנאמר בסדר טהרת המצורע שהתרפא \"וביום השמיני יקח שני כבשים... \u0003ושלשה עשרונים סלת מנחה\u0004 בלולה בשמן ולוג אחד שמן\" (ויקרא יד, י) — \u0003במנחה הבאה עם הזבח הכתוב מדבר.\u0004","ועדיין יש לדון בדבר: \u0003אתה אומר\u0004 כי מדובר כאן \u0003במנחה הבאה עם הזבח, או\u0004 שמא פסוק זה \u0003אינו אלא\u0004 \u0003במנחה הבאה בפני עצמה?\u0004 אלא \u0003כשהוא אומר\u0004 בהמשך דבריו \u0003\"והעלה הכהן את העלה ואת המנחה\"\u0004 (שם כ) — \u0003הוי אומר\u0004 מכאן כי \u0003במנחה הבאה עם הזבח הכתוב מדבר.\u0004","\u0003ועדיין איני יודע אם טעונה\u0004 מנחה זו גם \u0003נסכים\u0004 (של יין) \u0003ואם לאו.\u0004 לכך \u0003תלמוד לומר\u0004 בפרשת הנסכים \u0003\"ויין לנסך רביעית ההין תעשה על העלה או לזבח לכבש האחד\"\u0004 (במדבר טו, ה), וכיון שמקרא זה יתר, הריהו בא ללמד: \u0003\"עלה\"\u0004 — \u0003זו עולת מצורע,\u0004 שאף היא טעונה נסכי יין. ו\u0003\"זבח\"\u0004 (בכתוב \"או לזבח\") — \u0003זו חטאת מצורע\u0004 שהריהי טעונה נסכי יין. \u0003\"או לזבח\"\u0004 — \u0003זו אשם מצורע,\u0004 שאף הוא טעון נסכי יין.","ושואלים: \u0003ותיפוק ליה תרוייהו\u0004 \u0005[ושיוציאו,\u0006 יילמדו \u0005לו שניהם]\u0006 גם חטאת מצורע וגם אשמו \u0003מ\u0004המלה \u0003\"זבח\"\u0004 עצמה, וללא תוספת המלה \u0003\"או\".\u0004"],["וראיה לדבר שיכולים שני אלה להידרש מהמלה \"זבח\" כשלעצמה, שכן \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003חטאת ואשם מנין? תלמוד לומר: \"זבח\"!\u0004","ומשיבים: נזקקים אנו ללימודים הללו לענין נסכי יין בחטאת המצורע ובאשמו, ואין למדים מהאמור בו \"זבח\", \u0003שכן\u0004 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שחיוב נסכים בחטאת ואשם נלמדים מהמלה \"זבח\" אמורים רק \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 שבו \u0003ת\u0004 \u0003רוייהו\u0004 \u0005[שניהם,\u0006 החטאת והאשם\u0005]\u0006 — \u0003כי הדדי נינהו\u0004 \u0005[זה כמו זה הם],\u0006 ששניהם באים למטרה אחת, לאפשר (\"להכשיר\") למביא הקרבנות הללו לעשות את מה שהיה אסור עליו קודם לכן. \u0003אבל היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 כמו זה שלפנינו, במצורע, ששני הקרבנות הללו באים למטרות שונות, שקרבן ה\u0003אשם\u0004 בא \u0003להכשיר\u0004 את המצורע לשוב אל המחנה, שמקודם היה אסור בו. \u0003ו\u0004אילו קרבן ה\u0003חטאת\u0004 בא \u0003לכפר\u0004 על המצורע מהחטא שהביא עליו את צרעתו — אין הם נלמדים מהכתוב \"זבח\", ולכך \u0003בעינן תרי קראי\u0004 \u0005[צריכים אנו שני מקראות]\u0006 אלה שהובאו למעלה, כדי ללמדנו בדין חטאת המצורע ואשמו.","עוד שנינו בברייתא כי \u0003\"זבח\"\u0004 שנאמר באותו כתוב \u0003זו חטאת\u0004 ה\u0003מצורע,\u0004 וללמד שאף \u0005היא טעונה נסכי יין.\u0006 ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי \u0003זו חטאת\u0004 המובאת על ידי הנזיר הטהור המסיים את ימי נזירותו, \u0003ואשם\u0004 המובא על ידי ה\u0003נזיר\u0004 שנטמא בתוך ימי נזירותו, וללמד ששני קרבנות אלה טעונים נסכים!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הנאמר בפרשת הנזיר \"וזאת תורת הנזיר ביום מלאת ימי נזרו... והקריב את קרבנו לה' כבש בן שנתו תמים אחד לעולה וכבשה אחת בת שנתה תמימה לחטאת ואיל אחד תמים לשלמים. וסל מצות סולת חלות בלולות בשמן ורקיקי מצות משוחים בשמן ומנחתם ונסכיהם\" (במדבר ה, יג— טו), ופירשו חכמים את הנאמר \u0003\"ומנחתם ונסכיהם\"\u0004 — \u0003ב\u0004מנחות ונסכים של \u0003עולתו\u0004 של הנזיר, \u0003וב\u0004מנחות ונסכים של \u0003שלמיו\u0004 של הנזיר \u0003הכתוב מדבר.\u0004","ודנים: \u0003אתה אומר\u0004 שכוונת הדברים היא \u0003ב\u0004מנחות ונסכים של \u0003עולתו\u0004 של הנזיר, \u0003וב\u0004מנחות ונסכים של \u0003שלמיו\u0004 של נזיר. \u0003או אינו אלא\u0004 שכוונת הדברים היא לומר ש\u0003אפילו חטאת\u0004 הנזיר הטהור צריכה מנחה ונסכים? לכך \u0003תלמוד לומר\u0004 לאחר מכן \"והקריב הכהן לפני ה' ועשה את חטאתו ואת עולתו. \u0003ואת האיל יעשה זבח שלמים\u0004 לה' על סל המצות \u0003ו\u0004עשה הכהן את \u0003מנחתו\u0004 \u0003ו\u0004את \u0003נסכו\"\u0004 (שם טז— יז), ויש לדון: שהרי ה","\u0003איל בכלל\u0004 כל קרבנות השלמים \u0003היה\u0004 (כנאמר \"ואיל אחד תמים לשלמים\"), \u0003ולמה\u0004 איפוא \u0003יצא\u0004 להזכירו לעצמו? — על מנת \u0003להקיש\u0004 (להשוות) \u0003אליו\u0004 את שאר קרבנות הנזיר לחיוב נסכים. \u0003מה איל מיוחד\u0004 בכך שהריהו \u0003בא בנדר ונדבה\u0004 (כקרבן שלמים) וטעון נסכים — \u0003אף כל\u0004 קרבן הנזיר ה\u0003בא בנדר ונדבה\u0004 טעון נסכים, יצאו מכלל זה חטאת הנזיר הטהור ואשם הנזיר הטמא שאין הם טעונים נסכים, שהרי אינם באים בנדר ונדבה.","עוד שנינו בברייתא כי \u0003\"עלה\"\u0004 שנאמר בכתוב — \u0003זו עולת\u0004 ה\u0003מצורע,\u0004 שאף היא טעונה נסכים. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי \u0003זו עולת\u0004 ה\u0003יולדת\u0004 הטעונה נסכים!","\u0003אמר אביי\u0004 בדחיית השאלה: \u0005אין כתוב זה בא לענין נסכי עולת יולדת, שכן חובת הבאת הנסכים ב\u0006\u0003עולת יולדת מסיפא דקרא נפקא\u0004 \u0005[מסופו של המקרא\u0006 הנאמר בפרשת הנסכים היא \u0005יוצאת,\u0006 נלמדת\u0005].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0003],\u0004 על הנאמר בפרשת הנסכים \"ויין לנסך רביעית ההין תעשה על העולה או לזבח לכבש האחד\" (שם טו, ה), \u0003ר' נתן אומר:\u0004 מקרא יתר זה (\"לכבש האחד\") הנאמר בסוף הפסוק יש לדורשו כך: \u0003\"לכבש\"\u0004 — \u0003זו עולת יולדת,\u0004 שאף היא \u0005טעונה נסכים.\u0006 \u0003\"האחד\"\u0004 — \u0003זה\u0004 הבהמה שבזמן ספירת הבהמות היוצאות מן הדיר, לצורך הפרשת העשירי למעשר בהמה, היתה היא ה\u0003אחד עשר של\u0004 הבהמות הנמנות ל\u0003מעשר\u0004 בהמה, ובטעות הכריז עליה \"עשירי\", שדינו של זה \u0003ש\u0004הוא \u0003קרב\u0004 כקרבן \u0003שלמים,\u0004 ולימדנו כתוב \u0005זה שהריהו אף טעון נסכים (הגם שמעשר בהמה עצמו אינו טעון נסכים). ויש צורך בכתוב להשמיענו כן, ש\u0006","הרי זה \u0005חידוש,\u0006 \u0003ש\u0004כן \u0003לא מצינו\u0004 (מצאנו) \u0003לה בכל התורה\u0004 הלכה כגון זו, \u0003שיהא\u0004 דינו של הדבר ה\u0003טפל\u0004 (הנספח) לדבר עיקר, \u0003חמור מן\u0004 הדין של \u0003העיקר,\u0004 שמעשר הבהמה עצמו אינו טעון נסכים, ואילו האחד עשר, הנטפל לו, טעון נסכים.","\u0003רבא אמר\u0004 הסבר אחר מדוע הכתוב \"עולה\" בא ללמד לענין עולת מצורע, ולא לענין עולת יולדת, שהרי לפנינו בכתוב שלוש דרשות ריבוי (\"עולה\" \"או\" \"לזבח\"), ומעתה יש לשאול: \u0003איזהו דבר\u0004 הוא זה \u0003ש\u0004מובאים בו שלושה קרבנות, ולכך הריהו \u0003צריך שלשה רבויין\u0004 לענין הבאת נסכים? \u0003הוי אומר: זו\u0004 ה\u0003מצורע\u0004 (המביא עולה וחטאת ואשם). ולכן נדרשים שלושת הריבויים הללו דווקא בקרבנותיו של המצורע.","עוד נאמר בפרשת הנסכים: \"או לאיל תעשה מנחה סולת שני עשרונים בלולה בשמן שלישית ההין. ויין לנסך שלישית ההין תקריב ריח ניחוח לה' \" (שם ו— ז). ושואלים: זה שנאמר \u0003\"לאיל\u0004 תעשה מנחה\" \u0003למה לי?\u0004 שהרי בפרשת פינחס, \u0005בדיני המוספים (שם פרק כח) נאמר כי מנחתו של האיל היא שני עשרונים סולת הבלולה בשלישית ההין שמן, ומעתה כיון שנאמר בפסוק שלפנינו שכך היא מנחתו, שוב אין צורך לציין כי מדובר באיל!\u0006 \u0003אמר רב ששת\u0004 בהסבר הדברים: כתוב יתר זה בא \u0003לרבות\u0004 לענין חיוב הנסכים אף את \u0003אילו של אהרן\u0004 (איל כהן גדול, הקרב לעולה, בסדר העבודה ביום הכיפורים).","ותוהים: ללמד על חובת נסכים ב\u0003אילו של אהרן\u0004 אין צורך בכתוב זה, שהרי הלכה זו \u0003מ\u0004הכתוב \u0003\"\u0004\u0003במועדיכם\"\u0004 האמור בפרשת הנסכים \u0003נפקא\u0004 \u0005[\u0006היא \u0005יוצאת,\u0006 נלמדת\u0005].\u0006 שכן למדנו בדף הקודם (צ,ב) כי מכתוב זה נלמד שכל קרבנות חובות הרגלים טעונים נסכים, ואף אילו של כהן גדול בכלל זה! ומשיבים: עדיין נזקקים אנו לדרשה זו שאילו של כהן גדול טעון נסכים, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי מה שאמרנו שקרבנות חובות הרגלים טעונים נסכים, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים בקרבנות חובה של \u0003צבור, אבל\u0004 חובות הרגל של \u0003יחיד,\u0004 כאילו של הכהן הגדול ביום הכיפורים — \u0003לא\u0004 טעונים נסכים, ולכך משמיע לנו הכתוב \"לאיל\" שאף אילו של אהרן טעון נסכים.","ושואלים על כך: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 אילו של הכהן הגדול \u0003מעולת יולדת,\u0004 שאף הוא קרבן חובה של יחיד, והריהי טעונה נסכים, ומדוע נזקק הוא לדרשה מיוחדת להטעינו נסכים?","ומשיבים: נצרך הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי זה שאמרנו שאף קרבן חובתו של יחיד, כעולת \u0005יולדת, טעון נסכים,\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003דבר שאין קבוע לו זמן\u0004 להבאתו, וכעולת יולדת. \u0003אבל דבר שקבוע לו זמן\u0004 להבאתו, כאילו של כהן גדול, הבא ביום הכיפורים דווקא, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה טעון נסכים. לכך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 בדרשה זו \"לאיל\", שאף אילו של אהרן טעון נסכים.","וממשיכים בביאור הכתובים בפרשת הנסכים. לאחר שהוסבר כי הכתוב \"לאיל\" מלמד שאילו של כהן גדול טעון נסכים, שואלים: די שיהא כתוב \"לאיל\", והלשון היתירה \u0003\"או לאיל\"\u0004 \u0003למה לי,\u0004 מה הריבוי הנלמד מהמלה \"או\"? ומסבירים: \u0003הרי זה בא\u0004 \u0003לרבות\u0004 לענין חיוב הנסכים אף \u0003את הפלגס\u0004 (כבש בן שלושה עשר חודשים, המצוי בשלב ביניים: שיצא כבר מכלל כבש בן שנתו, ועדיין לא הגיע לכלל איל בשנתו השנית, כיון שטרם עברו שלושים יום בשנתו השנית), שאף הוא טעון נסכים, כנסכי האיל.","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח,\u0006 מובן\u0005],\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי הפלגס כ\u0003בריה\u0004 בפני עצמה \u0003הוא\u0004 נחשב, שאין הוא כבש ואין הוא איל, ולכך נזקקים אנו ללימוד מיוחד ביחס לפלגס שאף הוא טעון נסכים כאיל. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם עמד אדם ו\u0003הקריבו\u0004 את הפלגס — הריהו \u0003מביא עליו נסכי איל\u0004 (שני עשרונים סולת ושלישית ההין שמן ושלישית ההין יין) \u0003ו\u0004אולם קרבן זה \u0003אינו עולה\u0004 (נחשב) \u0003לו מ\u0004כלל \u0003זבחו,\u0004 שכיון שנדר להביא איל או שנדר להביא כבש — אין הפלגס נחשב כפרעון נדרו. \u0003ו\u0004בפירושם של דברי המשנה הללו \u0003אמר ר' יוחנן\u0004 שטעם הדבר שמביא עליו נסכי איל, הרי זה מדרשת הכתוב \u0003\"או לאיל\"\u0004 — \u0003לרבות את הפלגס.\u0004","\u0003אלא ל\u0004שיטת \u0003בר פדא\u0004 ש\u0003אמר\u0004 בהסבר דברי המשנה הללו, כי הריהו \u0003מייתי\u0004 \u0005[מביא]\u0006 נסכי יין, \u0003ומתני\u0004 \u0005[ומתנה]\u0006 שאם איל הוא פלגס זה — הרי אלה נסכיו כראוי לקרבן האיל. ואם כבש הוא פלגס זה — עשרון סולת מכלל שני העשרונים המובאים, ורביעית ההין שמן ורביעית ההין יין, מכלל שליש ההין שמן ושליש ההין יין המובאים יהיו לנסכי הכבש, והשאר יהיו לנדבה. שכן לדעת בר פדא, הפלגס \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא\u0004 אם זה כבש או איל, ולשיטת בר פדא יש לשאול: וכי \u0003אצטריך קרא לרבויי ספיקא\u0004 \u0005[הוצרך הכתוב לרבות\u0006 את \u0005הספק]?\u0006 שיש דרכים קבועות לדון בכל מיני הספיקות!","ומשיבים: אכן, \u0003ודאי ל\u0004שיטת \u0003בר פדא קשיא\u0004 \u0005[קשה]\u0006 הדבר.","וממשיכים בדרשת הנאמר בפרשת הנסכים. נאמר \u0003\"ככה יעשה לשור האחד או לאיל האחד או לשה בכבשים או בעזים\"\u0004 (במדבר טו, יא). ולכאורה הלשון \"אחד\" שנאמרה בכתוב ביחס לשור מיותרת, ואם כן \u0003\"לשור האחד\"\u0004 — \u0003מה תלמוד לומר?\u0004 — \u0003לפי שמצינו\u0004 (שמצאנו) \u0003שחלק הכתוב בין\u0004 דין \u0003נסכי\u0004 ה\u0003איל\u0004 \u0003ל\u0004בין דין \u0003נסכי\u0004 ה\u0003כבש.\u0004 מעתה \u0003יכול\u0004 שאף \u0003נחלק\u0004 כיוצא בזה \u0003בין\u0004 דין \u0003נסכי\u0004 ה\u0003פר\u0004 (שהוא הפר המגודל, בשנתו השלישית) \u0003לנסכי\u0004 ה\u0003עגל\u0004 — לכך \u0003תלמוד לומר \"לשור האחד\",\u0004 שדין נסכים אחד הוא לכל אלה, לפר ולעגל, שאף העגל הוא בכלל \"שור\".","הכתוב \u0003\"או לאיל\u0004 האחד\" — \u0003מה תלמוד לומר\u0004 מהו הריבוי מהמילה \"או\"? — \u0003לפי שמצינו שחלק הכתוב\u0004 בדין הנסכים \u0003בין נסכי בן שנה\u0004 (הכבש) \u0003ל\u0004בין \u0003נסכי בן שתים\u0004 (האיל). מעתה \u0003יכול\u0004 שאף \u0003נחלק בין\u0004 דין \u0003נסכי\u0004 \u0003בן שתים ל\u0004דין \u0003נסכי בן שלש\u0004 — לכך \u0003תלמוד לומר\u0004 \u0003\"או לאיל האחד\",\u0004 שדין הנסכים אחד הוא לכל אלה, שהכל קרויים \"איל\".","הכתוב \u0003\"או לשה בכבשים\"\u0004 — \u0003מה תלמוד לומר?\u0004 — \u0003לפי שמצינו\u0004 \u0003שחלק הכתוב\u0004 בדין הנסכים \u0003בין נסכי\u0004 ה\u0003כבש\u0004 (הזכר) \u0003לנסכי\u0004 ה\u0003איל\u0004 (הכבש הזכר הבוגר), \u0003יכול\u0004 ש\u0003נחלק\u0004 אף \u0003בין\u0004 דין \u0003נסכי\u0004 ה\u0003כבשה\u0004 (הנקיבה) \u0003לנסכי\u0004 ה\u0003רחלה\u0004 (הכבשה הבוגרת, בשנתה השניה) — לכך \u0003תלמוד לומר\u0004 \u0003\"או לשה בכבשים\",\u0004 שדין אחד הוא לכל נקבות הכבשים.","הכתוב \u0003\"או בעזים\"\u0004 — \u0003מה תלמוד לומר?\u0004 — \u0003לפי שמצינו\u0004 \u0003שחלק הכתוב\u0004 בדין הנסכים \u0003בין נסכי\u0004 ה\u0003כבש לנסכי\u0004 ה\u0003איל,\u0004 מעתה \u0003יכול\u0004 היה אדם לומר שכיוצא בדבר אף \u0003נחלק בין נסכי גדי\u0004 (העז \u0003הצעיר)\u0004 \u0003ל\u0004בין \u0003נסכי\u0004 ה\u0003שעיר\u0004 (העז הבוגר) — לכך \u0003תלמוד לומר \"או בעזים\",\u0004 שכל שהוא בעיזים דינו אחד.","ומתוך שהוזכר דין נסכי הרחלה, מביאים את מה ש\u0003אמר רב פפא: בדיק לן\u0004 \u0005[בדק,\u0006 בחן \u0005אותנו]\u0006 \u0003רבא\u0004 בשאלה זו,"],["\u0003נסכי רחלה\u0004 (כבשה בת שנתיים) הבאה כקרבן, \u0003בכמה\u0004 יין הוא מביא בנסכיה, האם כשל כבש או כשל איל? \u0003ופשטינא ליה ממתניתין\u0004 \u0005[ופתרנו לו\u0006 את שאלתו \u0005זו\u0006 \u0005ממשנתנו\u0006 במסכת שקלים\u0005],\u0006 בסדר הבאת התרומות כי ארבעה סוגי חותמות נהגו במקדש, ועל אחד מהם היה כתוב \u0003\"גדי\",\u0004 והוא היה \u0003משמש\u0004 כסימן לצורך \u0003נסכי צאן של גדולים ושל קטנים, של זכרים ושל נקבות, חוץ משל אילים.\u0004 ונמצאנו למדים שאין הבדל בין הנסכים של כבש וכבשה, בין שהם מבוגרים בין שהם \u0003צעירים, ואף הרחלה כמותם. ורק נסכי האיל שונים מנסכי שאר הצאן.\u0004","\u0003כל קרבנות הצבור אין\u0004 \u0003בהן\u0004 דין ה\u0003סמיכה\u0004 של הידים על ראש הקרבן \u0003חוץ מן\u0004 קרבן \u0003הפר הבא על כל המצו‍ת\u0004 (הנקרא כרגיל \"פר העלם דבר של ציבור\"), מובא כאשר הורו סנהדרין הוראת טעות, והתירו עשייתו של דבר שהוא אסור מן התורה באיסור חמור (שעונש העושה כן במזיד הריהו כרת, ובשוגג — בחטאת), והלך רוב עם ישראל ועשה כן, ולאחר מכן נודע לסנהדרין כי שגגו בהוראתם. וקרבן זה טעון סמיכת ידיהם של שלושה מחברי הסנהדרין עליו. \u0003ו\u0004כן טעון סמיכה גם ה\u0003שעיר המשתלח\u0004 לעזאזל ביום הכיפורים, שהכהן הגדול סומך את ידיו עליו. \u0003ר' שמעון אומר:\u0004 בדומה לפר העלם דבר של ציבור, כן הדין \u0003אף\u0004 בקרבן חטאת \u0003ה\u0004\u0003שעיר\u0004 הבא על הוראת הסנהדרין בטעות להתיר מעשה \u0003עבודה זרה,\u0004 ועשה רוב עם ישראל על פי הוראתם זו, ולאחר מכן נודעה להם טעות הוראתם זו — סומכים בית דין ידיהם עליו.","אבל \u0003כל קרבנות היחיד טעונין סמיכה, חוץ מן\u0004 קרבנות \u0003הבכור והמעשר והפסח. ו\u0004קרבנו של","\u0003היורש,\u0004 המביא את קרבן מורישו (כגון שהקדיש האב בהמה לקרבן עולה או שלמים, ומת) הריהו \u0003סומך\u0004 על קרבן זה \u0003ומביא\u0004 עימו מנחת \u0003נסכים. ו\u0004כיוצא בדבר, נחשב היורש כבעלים של הקרבן אף לענין שהוא \u0003מימר\u0004 (שיש בו דין תמורה: שאם המיר בהמת חולין בבהמת קרבן זו של אביו — הרי זו תמורה, שעבר על איסור תמורה, ושתיהן קדושות).","שנינו במשנתנו כי לדעת תנא קמא כל קרבנות הציבור אינם טעונים סמיכה, חוץ מקרבן פר העלם דבר של ציבור (\"פר הבא על כל המצוות\") ושעיר המשתלח ביום הכיפורים. ולדעת ר' שמעון אף שעיר שגגת עבודה זרה של ציבור טעון סמיכה. ובענין מחלוקת זו עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003כל קרבנות הצבור אין בהן סמיכה, חוץ מפר הבא על כל המצו‍ת ושעירי עבודה זרה,\u0004 אלו \u0003דברי ר' שמעון. ר' יהודה אומר: שעירי עבודה זרה אין בהן סמיכה, ואת מי\u0004 מכלל קרבנות הציבור \u0003אביא\u0004 בדין הסמיכה \u0003תחתיהם\u0004 של שעירי עבודה זרה? את \u0003שעיר המשתלח.\u0004","ותחילה דנים בדבריו, וכי \u0003לא סגיא\u0004 \u0005[לא די]\u0006 לדעת ר' יהודה בכך ש\u0003לא מעייל\u0004 \u0005[לא יכניס]\u0006 קרבן ציבור אחר במקום שעירי עבודה זרה, ויהיה דין הסמיכה נוהג רק בפר העלם דבר של ציבור? \u0003אמר רבינא\u0004 בהסבר הדברים: \u0003גמירי\u0004 \u0005[למודים,\u0006 מקובל במסורת בידי חכמים\u0005]\u0006 כי \u0003שתי סמיכות\u0004 יש \u0003ב\u0004קרבנות \u0003צבור.\u0004 ולכך, כאשר \u0005הוציא ר' יהודה את שעירי עבודה זרה מדין סמיכה, צריך הוא להביא תחתם קרבן ציבור אחר שנוהג בו דין סמיכה.\u0006","\u0003אמר לו ר' שמעון\u0004 לר' יהודה כקושיה על שיטתו: \u0003והלא\u0004 אי אפשר לומר שינהג דין סמיכה בשעיר המשתלח, שהרי \u0003אין\u0004 ה\u0003סמיכה\u0004 נעשית \u0003אלא ב\u0004ידי ה\u0003בעלים\u0004 של הקרבן, \u0003ו\u0004אילו \u0003זה,\u0004 השעיר המשתלח, \u0003אהרן\u0004 הכהן הגדול \u0003ו\u0004כמותו כן הכהן שיעמוד מ\u0003בניו\u0004 לשמש ככהן גדול, הם \u0005ה\u0006\u0003סומכין בו,\u0004 ואין הם בעליו של הקרבן המתכפרים בו בסמיכתם עליו! \u0003אמר לו\u0004 ר' יהודה לר' שמעון בתשובה לשאלתו זו: \u0003אף זה\u0004 השעיר המשתלח גם \u0003אהרן ובניו מתכפרין בו,\u0004 והרי זו איפוא סמיכה בבעלים.","ובהסבר מחלוקת זו \u0003אמר ר' ירמיה: ואזדו לטעמייהו\u0004 \u0005[והולכים\u0006 ר' יהודה ור' שמעון במחלוקתם זו \u0005לפי טעמיהם,\u0006 לשיטתם\u0005],\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הפסוק (האמור בסוף סדר כפרת יום הכיפורים) העוסק בהזאת דם פר החטאת שמביא הכהן הגדול, ובהזאת דם שעיר החטאת המובא מאת בני ישראל: \"וכפר את מקדש הקודש ואת אהל מועד ואת המזבח יכפר ועל הכהנים ועל כל עם הקהל יכפר\" (ויקרא טז, לג), ובכוונת הדברים האמורים בכתוב זה אמרו: \u0003\"וכפר את מקדש הקדש\"\u0004 — כתוב \u0003זה\u0004 עניינו בכפרה על טומאת מקדש \u0005וקדשיו שאירעה בתחום\u0006 \u0003לפני ולפנים\u0004 (קודש הקדשים). \u0003\"ואת אהל מועד\"\u0004 — כתוב \u0003זה\u0004 עניינו בכפרת הטומאה שאירעה \u0005ב\u0006\u0003היכל.\u0004 \"ואת ה\u0003מזבח\u0004 יכפר\" — הרי זה \u0003כמשמעו.\u0004 \u0005והכתוב היתר\u0006 \u0003\"יכפר\"\u0004 \u0005האמור בכתוב \"ואת המזבח יכפר\" (שהרי די היה לומר \"ואת המזבח\")\u0006 — כוונתו: \u0003אלו\u0004 טומאות שאירעו בתוך \u0003העזרות,\u0004 שאף הן מתכפרות \u0005בהזאת דם הפר ודם השעיר של יום הכיפורים. \"ועל\u0006 \u0003ה\u0004\u0003כהנים\"\u0004 — \u0003כמשמען,\u0004 שהזאת דם הפר מכפרת על טומאת מקדש וקדשיו שנעשתה על ידי הכהנים. \"ו \u0003על כל עם הקהל\"\u0004 — \u0003אלו ישראל,\u0004 שאף הם מתכפרים, בהזאת דם השעיר, על טומאות מקדש וקדשיו שעשו. \u0005והכתוב היתר\u0006 \u0003\"יכפר\"\u0004 \u0005האמור בכתוב \"ועל כל עם הקהל יכפר\"\u0006 — כוונתו: \u0003אלו הלוים,\u0004 שמתכפרים על טומאת מקדש וקדשיו שעשו.","ולאחר שלמדנו מכתובים נפרדים כי הכהנים והישראליים והלויים מתכפרים על טומאת מקדש וקדשיו בדם הפר ובדם שעיר החטאת, נמצא ש\u0003הושוו כולן לכפרה אחת\u0004 על שאר עבירות, \u0003שמתכפרין\u0004 הם כולם \u0003ב\u0004וידוי הנעשה על \u0005ה\u0006\u0003שעיר המשתלח\u0004 לעזאזל. אלו \u0003דברי ר' יהודה.\u0004 הרי שר' יהודה מגלה דעתו שאף הכהנים מתכפרים בשעיר המשתלח.","ואילו \u0003ר' שמעון אומר: כשם ש\u0004הזאת \u0003דם\u0004 ה\u0003שעיר הנעשה בפנים\u0004 בקדש הקדשים \u0003מכפר על ישראל על\u0004 חטא \u0003טומאת מקדש וקדשיו, כך\u0004 הזאת \u0003דם הפר מכפר על הכהנים על טומאת מקדש וקדשיו.\u0004 ו\u0003כשם שוידוי של שעיר המשתלח מכפר על ישראל בשאר עבירות, כך וידוי של פר מכפר על הכהנים בשאר עבירות.\u0004 נמצא שלדעת ר' שמעון אין הכהנים מתכפרים על שאר עבירות בשעיר המשתלח, ומכאן שאין סמיכתם עליו סמיכת בעלים.","\u0003ו\u0004שואלים על שיטתו זו של \u0003ר' שמעון: הא\u0004 \u0005[הרי]\u0006 \u0003ודאי\u0004 למדים אנו מן הכתוב שלפנינו כי \u0003הושוו\u0004 כולם, כהנים וישראליים, לכפרה על שאר עבירות, ומדוע הוא מחלק ביניהם, שכהנים מתכפרים בוידויו של פר ואילו ישראל מתכפרים בוידוי של שעיר המשתלח? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 אמנם \u0003הושוו\u0004 כהנים וישראליים לענין זה \u0003ש\u0004\u0003בני כפרה נינהו\u0004 \u0005[הם]\u0006 על שאר עבירות שעשו, \u0003מיהו\u0004 \u0005[ואולם]\u0006 \u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מהם הריהו \u0003מכפר בדנפשיה\u0004 \u0005[מתכפר בשל עצמו]:\u0006 כהנים מתכפרים בוידויו של פר (המובא על ידי הכהן), וישראליים מתכפרים בוידויו של שעיר המשתלח.","\u0005ובסיכום:\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 — על \u0003טומאת מקדש וקדשיו ישראל מכפרי\u0004 \u0005[מתכפרים]\u0006 \u0003ב\u0004הזאת ה\u0003דם\u0004 של ה\u0003שעיר הנעשה בפנים\u0004 (שעיר החטאת), \u0003ו\u0004ה\u0003כהנים\u0004 מתכפרים על טומאה זו \u0003ב\u0004הזאת דם ה\u0003פר של אהרן,\u0004 ואילו \u0003בשאר עבירות אלו ואלו\u0004 (כהנים וישראליים) \u0003מכפרי\u0004 \u0005[מתכפרים]\u0006 \u0003בוידוי שעיר המשתלח\u0004 לעזאזל. \u0003ול\u0004שיטת \u0003ר' שמעון\u0004 — \u0003בשאר עבירות נמי\u0004 \u0005[גם כן]\u0006 \u0003כהנים בוידוי\u0004 של \u0003פר מתכפרי\u0004 \u0005[מתכפרים],\u0006","\u0003כדקתני\u0004 \u0005[כמו ששנינו]\u0006 בברייתא אחרת: \u0003אחד\u0004 (בין) \u0003ישראל ואחד\u0004 (ובין) \u0003כהנים ואחד\u0004 (ובין) \u0003כהן משיח\u0004 כולם שווים לכפרה ביום הכיפורים על שאר עבירות שעשו, שכולם מתכפרים בשעיר המשתלח לעזאזל. \u0003מה\u0004 איפוא הוא ההבדל \u0003בין\u0004 כפרתם של \u0003ישראל ל\u0004כפרה ל\u0003כהנים ולכהן משיח? אלא שדם הפר מכפר על הכהנים על טומאת מקדש וקדשיו,\u0004 ואילו הישראליים מתכפרים על טומאת מקדש וקדשיו בדם שעיר החטאת. \u0003זו דברי ר' יהודה. ו\u0004אילו","\u0003ר' שמעון אומר: כשם שדם השעיר הנעשה בפנים מכפר על ישראל, כך דם הפר מכפר על הכהנים.\u0004 ו\u0003כשם שוידויו של שעיר המשתלח מכפר על ישראל, כך וידויו של פר\u0004 \u0003מכפר על הכהנים.\u0004","ועוד במחלוקתם של ר' יהודה ור' שמעון, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 נאמר בפר העלם דבר של ציבור \u0003\"וסמכו זקני העדה את ידיהם על ראש הפר\"\u0004 (ויקרא ד, טו), ובא לשון הדגשה זו (\"הפר\") להורות כי דווקא \u0003פר\u0004 העלם דבר של ציבור \u0003טעון סמיכה, ואין שעירי עבודה זרה טעונין סמיכה,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר:\u0004 בא הכתוב להורות כי דווקא \u0003פר טעון סמיכה בזקנים, ואין שעירי עבודה זרה טעון סמיכה בזקנים, אלא באהרן,\u0004 כלומר, הכהן הגדול סומך עליו.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במקום אחר על הנאמר בשעיר המשתלח לעזאזל \"וסמך אהרן את שתי ידיו על ראש השעיר \u0003החי\u0004 והתודה עליו את כל עונות בני ישראל ואת כל פשעיהם לכל חטאתם...\" (שם טז, כא), ובא לשון הדגשה זו (\"החי\") לומר — דווקא השעיר \u0003החי\u0004 (שעיר המשתלח לעזאזל) הוא ה\u0003טעון סמיכה, ואין שעירי עבודה זרה טעונין סמיכה,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ואילו \u0003ר' שמעון אומר:\u0004 הכתוב בא להורות כי דווקא השעיר ה\u0003חי טעון סמיכה באהרן,\u0004 כלומר, בכהן גדול,"],["\u0003ואין שעירי עבודה זרה טעונין סמיכה ב\u0004ידי \u0003אהרן\u0004 (הכהן) \u0003אלא בזקנים,\u0004 ונמצא שדברי ר' שמעון \u0005הללו סותרים את דבריו שהובאו בברייתא הקודמת כי סמיכת שעירי עבודה זרה היא בכהנים!\u0006","\u0003אמר רב ששת\u0004 בתירוץ \u0005הסתירה:\u0006 \u0003ותסברא דהך קמייתא מתרצתא\u0004 \u0005[וכי סבור אתה שברייתא הראשונה הזו מתורצת,\u0006 מתוקנת\u0003]\u0004 \u0003היא,\u0004 שאפשר להקשות מן האמור בה? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' שמעון\u0004 ש\u0003סמיכה בבעלים בעינן\u0004 \u0005[צריכים אנו]\u0006 ואילו על השעיר המשתלח סומך הכהן הגדול אף שהבעלים הם כל ישראל. ואם גם שעירי עבודה זרה לדעת ר' שמעון סמיכתם בכהנים — אין זו סמיכה הראויה שהרי אינה בבעלים שהם ישראל. הרי שלדעת ר' שמעון סמיכתם של שעירי עבודה זרה היא בזקנים, ולא בכהנים. נמצא שאין דברי הברייתא הראשונה מתוקנים.","\u0003אלא\u0004 את דברי הברייתא הזו \u0003תריץ הכי\u0004 \u0005[תרץ,\u0006 תקן, וגרוס בה \u0005כך]:\u0006 נאמר בפר העלם דבר של ציבור \"וסמכו זקני העדה את ידיהם על ראש הפר\" (ויקרא ד, טו), ובאה לשון הדגשה זו \u0003\"הפר\"\u0004 לומר: דווקא \u0003פר\u0004 העלם \u0005דבר של ציבור הוא ה\u0006\u0003טעון סמיכה, ואין שעירי עבודה זרה טעונין סמיכה,\u0004 אלו הם \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 נאמר בשעיר המשתלח לעזאזל \"וסמך אהרן את שתי ידיו על ראש השעיר החי והתודה עליו את כל עונות בני ישראל ואת כל פשעיהם לכל חטאתם...\"\u0005(שם טז, כא), ובאה לשון הדגשה זו\u0006 \u0003\"החי\"\u0004 לומר: דווקא ה\u0003חי\u0004 (שעיר המשתלח) הוא ה\u0003טעון סמיכה באהרן,\u0004 בכהן גדול, \u0003ואין שעירי עבודה זרה טעונין סמיכה באהרן אלא בזקנים. ו\u0004מסבירים עתה את טענת ר' שמעון כנגד דעת ר' יהודה,","\u0003הכי קא אמר ליה\u0004 \u0005[כך הוא אמר לו]\u0006 \u0003ר' שמעון לר' יהודה: שעירי עבודה זרה בעו\u0004 \u0005[צריכים]\u0006 \u0003סמיכה,\u0004 \u0003ואי שמיע\u0004 \u0005[ואם נשמע,\u0006 יש בקבלה\u0005]\u0006 \u0003לך\u0004 מרבותיך ש\u0003לא בעו\u0004 \u0005[לא צריכים]\u0006 שעירי עבודה זרה \u0003סמיכה\u0004 — \u0003באהרן\u0004 בכהן הגדול דווקא \u0003הוא דשמיע\u0004 \u0005[שנשמע]\u0006 \u0003לך\u0004 שאין הם טעונים סמיכה, ואולם בסמיכה עצמה הם טעונים. \u0003ומיעוטא\u0004 \u0005[והמיעוט]\u0006 המלמד בדין סמיכה בשעירי עבודה זרה — \u0003מ\u0004מה \u0003שנאמר\u0004 \u0003\"החי\" הוא.\u0004","ושואלים עתה לשיטת \u0003ר' יהודה: למה לי למעטינהו\u0004 \u0005[למעט אותם,\u0006 את שעירי עבודה זרה\u0005]\u0006 מדין סמיכה \u0003מקרא\u0004 \u0005[מ\u0006דרשת \u0005הכתוב,\u0006 \"הפר\"\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבינא\u0004 כי \u0003גמירי\u0004 \u0005[למודים היו,\u0006 מקובל בידי חכמים\u0005]\u0006 ש\u0003שתי סמיכות\u0004 בלבד ישנן \u0003ב\u0004קרבנות ה\u0003צבור,\u0004 ומאחר ומצאנו כי נוהגת הסמיכה בפר העלם דבר של ציבור ובשעיר המשתלח, מוכח מכאן כי אין היא נוהגת בקרבנות אחרים ובכלל זה בשעירי עבודה זרה! ומשיבים: לדעת ר' יהודה, מסורת לימוד זו, אינה \u0003כמסורת הלכה למשה מסיני, אלא\u0004 \u0003גירסא בעלמא\u0004 \u0005[לימוד בלבד]\u0006 היא, ושגורה בפי חכמים, ואולם מקורה של הלכה זו הוא מדרשת הכתוב.","\u0003ו\u0004שואלים עתה לשיטת \u0003ר' שמעון, שעירי עבודה זרה\u0004 דין זה \u0003דבעיא\u0004 \u0005[שצריכים]\u0006 \u0003סמיכה מנלן\u0004 \u0005[מנין לנו]?\u0006","ומשיבים: \u0003נפקא לן מדתניא\u0004 \u0005[יוצא לנו,\u0006 נלמד הדבר \u0005מ\u0006מה \u0005ששנינו\u0006 בברייתא\u0005]\u0006 על הנאמר בפרשת שעיר הנשיא \"אשר נשיא יחטא... והביא את קרבנו שעיר עזים תמים זכר תמים. וסמך ידו על ראש השעיר...\" (שם ד, כב— כד). ובא הכתוב היתר \"השעיר\" האמור בפסוק \u0003\"וסמך ידו על ראש השעיר\" לרבות שעיר נחשון\u0004 (שעירי חטאת שהביאו נשיאי העדה בכלל קרבנותיהם בזמן חנוכת המשכן, במדבר ז, ב— פח, ולפי שראשון להם היה נחשון בן עמינדב נשיא שבט יהודה, שם יב— יז נקראו על שמו) \u0003ל\u0004חיוב \u0003סמיכה,\u0004 שאף הם טעונים סמיכה. אלו \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 מקרא זה בא \u0003לרבות שעירי עבודה זרה ל\u0004חיוב \u0003סמיכה. שהיה ר' שמעון אומר: כל חטאת שנכנס דמה לפנים,\u0004 כלומר, לקודש הקדשים, הריהי \u0003טעונה סמיכה.\u0004","ושואלים: \u0003למה לי למימרא\u0004 \u0005[לומר]\u0006 \u0003\"שהיה\u0004 ר' שמעון אומר שכל חטאת שנכנס דמה לפנים הריהי טעונה סמיכה\", שנראים הדברים כהסבר לשיטתו ששעירי עבודה זרה חייבים בסמיכה, והלא מקור שיטתו זו היא דרשת הכתוב \"השעיר\", וכדרך שהראינו למעלה? ומשיבים: אין הדברים הללו באים כראיה לשיטת ר' שמעון, אלא הרי זה כעין \u0003סימנא בעלמא\u0004 \u0005[סימן בלבד],\u0006 לזכור על ידו את שיטת ר' שמעון.","ומקשים: \u0003ו\u0004\u0003ר' שמעון, מנין לו לרבות מלשון הריבוי \"השעיר\" סמיכה בשעירי עבודה זרה,\u0004 \u0003אימא\u0004 \u0005[אמור]\u0006 לרבות מכאן לסמיכה את ה\u0003שעיר הנעשה בפנים,\u0004 שעיר של יום הכיפורים הנעשה בקודש הקדשים! ומשיבים: ר' שמעון סבור כי יש לרבות מהכתוב \"השעיר\" האמור בחטאת נשיא, דבר שהוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שעיר נשיא\u0004 ה\u0003מכפר על עבירות\u0004 ה\u0003מצוה\u0004 ה\u0003ידועה\u0004 לו, מה שאין כן שעיר הנעשה בקודש הקדשים על ידי הכהן הגדול ביום הכיפורים, שבא על עבירה שלא נודעה לו (שהרי אם כבר נודעה לו עבירה שעבר, הריהו מביא קרבן עולה ויורד).","ושואלים עוד: \u0003ול\u0004דברי \u0003רבינא\u0004 ש\u0003אמר\u0004 כי \u0003גמירי\u0004 \u0005[למודים\u0006 חכמים\u0005]\u0006 שיש \u0003שתי סמיכות בציבור,\u0004 דרשת \u0003קראי\u0004 \u0005[כתובים]\u0006 אלה (\"השעיר\") \u0003למה לי?\u0004 ומדוע אין די בהלכה זו ללמוד ממנה ששעירי עבודה זרה טעונים סמיכה, שהרי בהם משלימים מנין שתי סמיכות בציבור!","ומשיבים: \u0003איצטריך הלכתא ואיצטריך קראי\u0004 \u0005[נצרכת ההלכה\u0006 המקובלת, \u0005ונצרכת\u0006 גם דרשת \u0005המקראות].\u0006","משום \u0003דאי\u0004 \u0005[שאם]\u0006 היינו למדים \u0003מקרא\u0004 \u0005[מן המקרא]\u0006 הזה בלבד, ובלא ההלכה ששתי סמיכות הן — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאף \u0003זבחי שלמי ציבור\u0004 (שני הכבשים הבאים עם שתי הלחם בחג השבועות) יהיו חייבים בסמיכה מקל וחומר,","\u0003כי קשיא אמתניתין דהך פירקא\u0004 \u0005[כמו שהיה קשה\u0006 לנו \u0005על המשנה של\u0006 אותו \u0005פרק],\u0006 ששנינו בו ש\u0003כל המנחות באות\u0004 מצה, ששם \u0003אמר ר' שמעון\u0004 כי \u0003שלשה מינין\u0004 של קרבנות (זבחי שלמי ציבור, זבחי שלמי יחיד, ואשם מצורע) הם ה\u0003טעונין שלש מצו‍ת,\u0004 תנופה בעודם חיים, סמיכה בעודם חיים, ותנופה לאחר שחיטתם, בכל אחד מהם שנים מתוך השלושה, ולכאורה יש מקום לומר כי","\u0003ליתי\u0004 \u0005[שיילמד]\u0006 הדבר \u0003בקל וחומר, ויהו זבחי שלמי ציבור טעונין סמיכה מקל וחומר,\u0004 ובאופן הזה: \u0003מה שלמי יחיד\u0004 הקלים, \u0003ש\u0004הרי \u0003אין\u0004 הם \u0003טעונין תנופה\u0004 בהיותם ב\u0003חיים\u0004 — ובכל זאת הריהם \u0003טעונין סמיכה\u0004 בהיותם ב\u0003חיים.\u0004 שלמי ציבור, החמורים, שטעונים תנופה בהיותם בחיים — בודאי שטעונים סמיכה בהיותם בחיים. על כן \u0003איצטריך הלכתא\u0004 \u0005[הוצרכה ההלכה]\u0006 האומרת כי רק שתי סמיכות יש בקרבנות ציבור, שהם פר העלם דבר של ציבור ושעירי עבודה זרה.","ולהיפך, \u0003ואי\u0004 \u0005[ואם]\u0006 היינו למדים רק \u0003מהלכתא\u0004 \u0005[מההלכה]\u0006 האומרת ששתי סמיכות הן בקרבנות ציבור, ולא מדרשת הכתוב — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי עדיין \u0003לא ידעינן הי נינהו\u0004 \u0005[איננו יודעים אילו הם]\u0006 קרבנות הציבור הטעונים סמיכה. לכן \u0003קמשמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 אף את דרשת הכתוב \"השעיר\" ממנו למדים שיש לרבות דבר שהוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שעיר נשיא,\u0004 ש\u0003מכפר על עבירות מצוה ידועה.\u0004","שנינו במשנה ש\u0003כל קרבנות היחיד טעונין סמיכה, חוץ מבכור ומעשר ופסח.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על לשונות \"קרבנו\" הנאמרות בפרשת השלמים, המשמשים כלשונות מיעוט: \u0003\"קרבנו\"\u0004 האמור בפרשה זו, שלמים, הוא הטעון סמיכה — \u0003ולא הבכור\u0004 טעון סמיכה. \u0003ש\u0004כן \u0003יכול\u0004 הייתי לומר \u0003והלא דין\u0004 (קל וחומר) \u0003הוא\u0004 זה המלמד \u0005שבכור טעון סמיכה:\u0006 \u0003ומה שלמים\u0004 הקלים, \u0003ש\u0004הרי \u0003אין קדושתן\u0004 באה \u0003מרחם\u0004 — \u0003טעונין סמיכה.\u0004 קרבן ה\u0003בכור\u0004 החמור, \u0003ש\u0004הרי \u0003ק\u0004 \u0003דושתו מרחם\u0004 — \u0003אינו דין שטעון סמיכה!\u0004 לכך \u0003תלמוד לומר \"קרבנו\"\u0004 — למעט: \u0003ולא הבכור.\u0004","ועוד דרשו: \u0003\"קרבנו\"\u0004 האמור בפרשה זו, שלמים, הוא הטעון סמיכה — \u0003ולא\u0004 קרבן \u0003מעשר. ש\u0004כן \u0003יכול\u0004 הייתי לומר \u0003והלא דין הוא\u0004 זה המלמד \u0005שמעשר טעון סמיכה, ובזה האופן:\u0006 \u0003ומה שלמים\u0004 הקלים בדינם, \u0003ש\u0004הרי \u0003אין\u0004 הם \u0003מקדשין\u0004 את הבהמות ש\u0003לפניהם ו\u0004ש\u0003לאחריהם\u0004 — הריהם \u0003טעונין סמיכה.\u0004 קרבן ה\u0003מעשר\u0004 החמור בדינו, \u0003ש\u0004הרי הוא \u0003מקדש\u0004 אף את הבהמה \u0005ש\u0006\u0003לפניו ו\u0004ש\u0003לאחריו\u0004 (כגון זה שקרא \"עשירי\" לבהמה שיצאה כתשיעית מן הדיר, תוך כדי ספירתן לצורך הפרשת מעשר בהמה, או שקרא לבהמה האחת עשרה \"עשירי\", שאף הן, מלבד הבהמה העשירית קדושות) — \u0003אינו דין ש\u0004הריהו \u0003טעון סמיכה!\u0004 לכך \u0003תלמוד לומר\u0004 עוד \u0003\"קרבנו\"\u0004 — למעט, \u0003ולא מעשר.\u0004","ועוד דרשו: \u0003\"קרבנו\"\u0004 האמור בפרשה זו, שלמים, הוא הטעון סמיכה — \u0003ולא\u0004 קרבן ה\u0003פסח, ש\u0004כן \u0003יכול\u0004 הייתי לומר \u0003והלא דין הוא\u0004 זה המלמד \u0005שפסח טעון סמיכה, ובזה האופן:\u0006 \u0003ומה\u0004 קרבן \u0005ה\u0006\u0003שלמים\u0004 הקל בדינו, \u0003ש\u0004הרי הוא \u0003אינו ב\u0004כלל הקרבנות \u0005בהם אומרים לאדם\u0006 \u0003\"עמוד והבא\u0004 את קרבנך\", שהרי אין מצות עשה להביא שלמים בנדבה — בכל זאת \u0003טעונין סמיכה.\u0004 קרבן ה\u0003פסח\u0004 החמור בדינו, \u0003ש\u0004הרי \u0003הוא ב\u0004כלל הקרבנות ש\u0005אומרים לו לאדם\u0006 \u0003\"עמוד והבא\u0004 את קרבנך\", שהרי מצות עשה להביא פסח — \u0003אינו דין ש\u0004הריהו \u0003טעון סמיכה!\u0004 לכך \u0003תלמוד לומר \"קרבנו\"\u0004 — למעט: \u0003ולא\u0004 קרבן ה\u0003פסח.\u0004","ושואלים: כל אחת משלוש הדרשות הללו באה להוציא מקל וחומר שיכול היה להיאמר, ואולם \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]\u0006 את כל אחד מהקל וחומר הללו, בפירכה הבאה: \u0003מה לשלמים שכן\u0004 יש בהם צד חמור שאין בשלושת אלה, בכור ומעשר ופסח, שהרי השלמים \u0003טעונין נסכים ותנופת חזה ושוק,\u0004 מה שאין כן בבכור מעשר ופסח! ומשיבים: דרשות \u0003קראי\u0004 \u0005[המקראות]\u0006 הללו שהבאנו הריהם \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד].\u0006","ושואלים: אם כן, \u0003אלא\u0004"],["שלושת \u0003קראי\u0004 \u0005[מקראות]\u0006 הללו (\"קרבנו\") \u0003למה לי?\u0004 ומשיבים: \u0003\"קרבנו\"\u0004 כלשון המיעוט באה להורות כי דווקא על קרבנו הוא סומך, \u0003ולא\u0004 סומך על \u0003קרבן חבירו. \"קרבנו\"\u0004 — דווקא על קרבן של ישראל הריהו סומך, \u0003ולא\u0004 על \u0003קרבן\u0004 של \u0003גוי. \"קרבנו\"\u0004 — \u0003לרבות כל בעלי קרבן\u0004 (השותפים בקרבן) \u0003ל\u0004ענין ה\u0003סמיכה,\u0004 שכולם צריכים לסמוך על קרבנם, ואין יוצאים בסמיכה שסומך אחד מהם עבור כולם.","שנינו במשנה ש\u0003היורש סומך\u0004 על קרבנו של מורישו.","ובענין זה \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב חנניה קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא\u0004 את דברי משנתנו כך: ה\u0003יורש אינו סומך\u0004 על קרבנו של מורישו, וכן \u0003ה\u0004\u0003יורש אינו מימר\u0004 (מחיל דין תמורה) בקרבנו של מורישו. תהה על כך רבא, \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 שלא כדברים הללו, אלא ש\u0003היורש סומך\u0004 על קרבן מורישו, \u0003ומביא את נסכיו\u0004 של אותו קרבן, \u0003ומימר\u0004 בקרבנו של מורישו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חנניה לרבא, האם עלי \u0003איפכאי\u0004 \u0005[להפוך]\u0006 את גירסת המשנה ששניתי, ולומר בה כי היורש סומך והיורש מימר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בתשובה: \u0003לא,\u0004 אינך נצרך להפוך את גירסת המשנה, שכן \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 זו שאתה שנית, כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 ה\u0003יורש סומך,\u0004 ה\u0003יורש מימר.\u0004 ואילו \u0003ר' יהודה אומר:\u0004 ה\u0003יורש אינו סומך,\u0004 ה\u0003יורש אינו מימר.\u0004","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מה מקור שיטתו\u0005]\u0006 זו של \u0003ר' יהודה?\u0004 ומסבירים: לענין הסמיכה הריהו דורש את הכתוב \u0003\"קרבנו\"\u0004 למעט: דווקא על קרבנו הוא סומך, \u0003ולא\u0004 סומך על \u0003קרבן אביו. ו\u0004אילו לענין שאין היורש ממיר, הריהו \u0003יליף\u0004 \u0005[למד]\u0006 בהיקש את הדין הנוגע ל\u0003תחלת הקדש\u0004 (מעשה התמורה, שמחיל הקדש על בהמת החולין) \u0003מ\u0004הדין הנוגע ל\u0003סוף הקדש\u0004 (מעשה הסמיכה, הנעשה לאחר שכבר הוקדשה הבהמה). \u0003מה סוף הקדש\u0004 — \u0003ה\u0004\u0003יורש אינו סומך אף תחילת הקדש\u0004 — ה\u0003יורש אינו מימר.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים שיורש סומך ויורש ממיר, מה מקור שיטתם? לענין התמורה — שאמר הכתוב בדין התמורה לשון ריבוי \u0003\"המר ימיר\"\u0004 (\"ואם המר ימיר בהמה בבהמה והיה הוא ותמורתו יהיה קודש\". ויקרא כז, י), שבאה \u0003לרבות\u0004 לענין התמורה אף \u0003את היורש\u0004 שממיר בקרבן מורישו. \u0003ו\u0004אילו לענין שהיורש סומך, \u0003יליף\u0004 \u0005[למד]\u0006 היקש הדין הנוגע ל\u0003סוף הקדש\u0004 (סמיכה) \u0003מ\u0004הדין הנוגע ל\u0003תחלת הקדש\u0004 (תמורה): \u0003מה\u0004 \u0003תחלת הקדש\u0004 — \u0003יורש\u0004 \u0003מימר, אף סוף הקדש\u0004 — \u0003יורש סומך.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[\u0006מיעוט \u0005זה]\u0006 \u0003\"קרבנו\"\u0004 שר' יהודה למד ממנו למעט את היורש מסמיכה על קרבן מורישו, \u0003מאי עבדי ליה\u0004 \u0005[מה\u0006 הם \u0005עושים,\u0006 לומדים \u0005בו]?\u0006 ומשיבים: הם למדים מכתוב זה: \u0003\"קרבנו\"\u0004 — \u0003ולא קרבן גוי, \"קרבנו\"\u0004 — \u0003ולא קרבן חבירו, \"קרבנו\"\u0004 — \u0003לרבות כל בעלי קרבן לסמיכה.\u0004","ושואלים מצד שני: \u0003ור' יהודה,\u0004 שלמד מ\"קרבנו\" למעט את היורש, מנין הוא לומד את הדברים הללו? ומשיבים: הלכה זו שיש \u0003לרבות כל בעלי קרבן לסמיכה\u0004 — \u0003לית ליה\u0004 \u0005[אין לו],\u0006 אין הוא מקבל. \u0003ואי נמי אית ליה\u0004 \u0005[ואם גם כן\u0006 תאמר כי \u0005יש לו,\u0006 הריהו מקבל\u0005]\u0006 הלכה זו, אפשר לומר כי את המיעוט ביחס ל\u0003גוי ו\u0004ביחס ל\u0003חבירו\u0004 שאינם סומכים, לדעת ר' יהודה \u0003מחד קרא נפקא\u0004 \u0005[ממקרא אחד\u0006 הוא \u0005יוצא,\u0006 נלמד\u0005].\u0006 ומעתה, \u0003אייתרו ליה תרי קראי\u0004 \u0005[נותרו לו,\u0006 לר' יהודה, איפוא \u0005שני מקראות]\u0006 לדרוש: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 כדי לדרוש \u0003\"קרבנו\"\u0004 — \u0003ולא קרבן אביו,\u0004 שאין היורש סומך. \u0003ואידך\u0004 \u0005[והאחר]\u0006 — \u0003לרבות כל בעלי קרבן לסמיכה.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יהודה,\u0004 הסבור שאין היורש ממיר, \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"המר ימיר\"\u0004 שחכמים דרשו ממנו שהיורש ממיר, \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה,\u0006 דורש \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 פסוק זה כדי \u0003לרבות את האשה,\u0004 שאף בה נוהג דין תמורה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0003]:\u0004 \u0003לפי שכל הענין כולו\u0004 של פרשת התמורה \u0003אינו מדבר אלא בלשון זכר, מה סופינו,\u0004 כלומר, כיצד אנו מגיעים \u0003לרבות\u0004 אף \u0003את האשה\u0004 לדין התמורה? לכך \u0003תלמוד לומר\u0004 הריבוי \u0003\"המר ימיר\".\u0004","ושואלים לצד שכנגד \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 שלמדו מ\"המר ימיר\" לענין שהיורש ממיר, מנין להם שאף האשה בכלל דין התמורה? ומשיבים: חכמים \u0003דרשי\u0004 \u0005[דורשים\u0006 זאת\u0005]\u0006 \u0003מ\u0004מה שנאמר \u0003\"ואם\u0004 המר ימיר\", שבאה תוספת המלה \"ואם\" להורות שאף האשה בכלל. \u0003ו\u0004אילו \u0003ר' יהודה,\u0004 שדרש כן מהלשון \"המר ימיר\" — את המלה \u0003\"ואם\"\u0004 הוא \u0003לא דריש\u0004 \u0005[לא דורש].\u0006","ועוד בדיני הסמיכה על הקרבן. \u0003הכל\u0004 כשהם מביאים את קרבנם, הריהם \u0003סומכין\u0004 עליו, \u0003חוץ מ\u0004ה\u0003חרש\u0004 (זה שאינו שומע, ואינו מדבר), וה\u0003שוטה, ו\u0004ה\u0003קטן.\u0004 \u0003ו\u0004כן אין סומכים על קרבנם ה\u0003סומא, ו\u0004ה\u0003גוי, והעבד, והשליח\u0004 המביא את קרבנו של זה שמשלחו לכך, \u0003והאשה.\u0004","\u0003וסמיכה\u0004 על הקרבן אינה מעכבת את הכפרה, שכן הריהי כ\u0003שירי\u0004 (נספח ותוספת) בלבד לעצם ה\u0003מצוה.\u0004","ודרך הסמיכה היא שסומכים \u0003על הראש\u0004 של בהמת הקרבן, \u0003בשתי\u0004 ה\u0003ידים\u0004 של הסומך. \u0003וב\u0004אותו \u0003מקום\u0004 במקדש \u0003ש\u0004בו \u0003סומכין\u0004 על הקרבן, שם גם \u0003שוחטין\u0004 אותו. \u0003ו\u0004טעם הדבר: לפי ש\u0003תכף\u0004 (מיד) \u0003ל\u0004אחר \u0003ה\u0004\u0003סמיכה\u0004 צריכה להיעשות ה\u0003שחיטה.\u0004","שנינו במשנתנו שהחרש השוטה והקטן והסומא והגוי אינם סומכים. ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 זה מובן\u0005]\u0006 מדוע \u0005ה\u0006\u0003חרש\u0004 וה\u0003שוטה ו\u0004ה\u0003קטן\u0004 אינם סומכים, הרי זה משום \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003בני דעה נינהו\u0004 \u0005[הם],\u0006 וכן ה\u0003גוי נמי\u0004 \u0005[גם כן]\u0006 אינו סומך, שהרי נאמר במצות סמיכת הקרבן \"דבר אל \u0003בני ישראל\u0004 ואמרת אליהם אדם כי יקריב מכם קרבן לה'... וסמך ידו על ראש העולה ונרצה לו לכפר עליו\" (ויקרא א, ב— ד). ומכאן למדים: דווקא בני ישראל הם ש\u0003סומכין\u0004 על קרבנם, \u0003ואין\u0004 ה\u0003גוים סומכין\u0004 על קרבנם. \u0003אלא סומא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 סומך על קרבנו?","נחלקו בכך \u0003רב חסדא ורב יצחק בר אבדימי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 בטעם הדבר כי \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת הלכה זו\u0005]\u0006 מתוך היקשה של מצות ה\u0003סמיכה\u0004 בכל \u0003הקרבנות למצות ה\u0004\u0003סמיכה\u0004 הנעשית בפר העלם דבר של ציבור (\"וסמכו זקני העדה את ידיהם על ראש הפר...\". שם ד, טו), שכן דינם של \u0003זקני עדה\u0004 (הסנהדרין) הסומכים על הקרבן שהסומא פסול בהם.","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת הלכה זו\u0005]\u0006 מתוך היקשה של מצות ה\u0003סמיכה\u0004 בכל \u0003הקרבנות למצות ה\u0004\u0003סמיכה\u0004 האמורה ב\u0003עולת ראייה,\u0004 שכן הסומא פטור מעולת ראייה, ואין נוהגת בו איפוא סמיכה כלל.","ומבררים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שאת הדין שסומא אינו סומך בשאר הקרבנות למדים \u0003מעולת ראייה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא יליף\u0004 \u0005[לא למד]\u0006 זאת \u0003מן\u0004 הסמיכה הנעשית על ידי \u0003זקני\u0004 ה\u0003עדה?\u0004"],["ומשיבים: לדעתו ראוי ללמוד את פטור הסמיכה בסומא מעולת ראייה, ולא מפר העלם דבר של ציבור, שכן \u0003דנין\u0004 (למדים דין) קרבנו של \u0003יחיד מ\u0004קרבנו של \u0003יחיד,\u0004 כעולת \u0003ראייה,\u0004 \u0003ואין דנין\u0004 קרבנו של \u0003יחיד מ\u0004קרבנו של \u0003ציבור,\u0004 כפר העלם דבר של ציבור.","ושואלים לצד האחר: \u0003ולמאן דיליף\u0004 \u0005[ולמי שלמד]\u0006 את פטור הסמיכה בסומא \u0003מזקני עדה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא יליף\u0004 \u0005[לא למד]\u0006 זאת \u0003מעולת ראייה?\u0004 ומשיבים: \u0003דנין מידי דכתיב ביה\u0004 \u0005[דבר שכתוב בו]\u0006 מצות ה\u0003סמיכה בגופיה\u0004 \u0005[בעצמו,\u0006 מפורש בתורה\u0005],\u0006 \u0003ממידי דכתיב ביה\u0004 \u0005[מדבר שכתוב בו]\u0006 מצות ה\u0003סמיכה בגופיה\u0004 \u0005[בעצמו],\u0006 כבפר העלם דבר של \u0003ציבור. ו\u0004\u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 מן האמור ב\u0003עולת ראייה,\u0004 שכן \u0003היא גופה\u0004 \u0005[עצמה]\u0006 שצריכה סמיכה לא נאמר במפורש, אלא \u0003מעולת נדבה גמרה\u0004 \u0005[נלמדת].\u0006","\u0003דתני\u0004 \u0003תנא קמיה\u0004 \u0005[ששנה חוזר המשניות לפני]\u0006 \u0003רב יצחק בר אבא:\u0004 נאמר בפרשת היום השמיני לימי המילואים, בדין קרבן חובתו של אהרן (\"עגל בן בקר לחטאת ואיל לעולה\". ויקרא ט, ב), \u0003\"ויקרב את העלה ויעשה כמשפט\"\u0004 (שם טז). ובאה לשון \"כמשפט\" לומר: דין עולת חובתו של אהרן הריהו \u0003כמשפט עולת נדבה.\u0004 ומכאן \u0003לימד\u0004 הכתוב \u0003על\u0004 כל \u0003עולת חובה ש\u0004הריהי \u0003טעונה סמיכה.\u0004 ואף דין עולת ראייה שטעונה סמיכה נלמד מכאן.","שנינו במשנתנו כי אין \u0003העבד והשליח והאשה\u0004 סומכים. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר בדין הסמיכה על הקרבן \"וסמך \u0003ידו\u0004 על ראש העולה ונרצה לו לכפר עליו\" (שם א, ג), והרי הדגשה זו של המלה \u0003\"ידו\"\u0004 באה לומר: דווקא ידו של בעל הקרבן היא הסומכת, \u0003ולא יד עבדו.\u0004 \u0003\"ידו\"\u0004 — דווקא של בעל הקרבן \u0003ולא יד שלוחו.\u0004 \u0003\"ידו\"\u0004 — דווקא של בעל הקרבן \u0003ולא יד אשתו.\u0004","ושואלים: \u0003כל הני\u0004 \u0005[אלה]\u0006 שלושת המיעוטים \u0003למה לי?\u0004 והרי לכאורה, די היה להשמיענו דבר אחד, ללמדנו שרק בעל הקרבן הוא הסומך, ואין אחרים סומכים. ומשיבים: \u0003צריכא\u0004 \u0005[נצרך]\u0006 הדבר להיאמר באופן זה, שכן \u0003אי כתב רחמנא חד\u0004 \u0005[אם היתה כותבת התורה\u0006 רק מיעוט \u0005אחד],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי בא מיעוט זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 מסמיכה רק את ה\u0003עבד,\u0004 וטעם הדבר: משום \u0003דלאו בר\u0004 \u0005[ש\u0006כן \u0005אינו בן]\u0006 חיוב ב\u0003מצו‍ת,\u0004 \u0003אבל שליח דבר\u0004 \u0005[שבן]\u0006 \u0003מצוה הוא ו\u0004כלל הוא בדיני השליחות כי \u0003שלוחו של אדם\u0004 הריהו \u0003כמותו, אימא לסמוך\u0004 \u0005[אמור שיסמוך]\u0006 על קרבן משלחו, לכך נצרכים אנו למיעוט נוסף, לגבי השליח.","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואם היה\u0006 הכתוב \u0005משמיע לנו\u0006 רק את \u0005אלה שני\u0006 המיעוטים\u0005],\u0006 הייתי אומר כי דווקא שני אלה (עבד, ושליח) אינם סומכים על קרבן האדון והמשלח, וטעם הדבר: משום \u0003דלאו כגופיה דמיא\u0004 \u0005[שאינם נחשבים כגופו],\u0006 \u0003אבל אשתו, דכגופיה דמיא\u0004 \u0005[שכגופו\u0006 של בעלה הריהי \u0005נחשבת]\u0006 \u0003אימא תיסמך\u0004 \u0005[אמור שתסמוך]\u0006 על קרבנו של בעלה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 לומר מיעוט נוסף, שאף האשה אינה סומכת.","שנינו במשנתנו שאין ה\u0003סמיכה\u0004 אלא \u0003שירי מצוה,\u0004 ולכך אינה מעכבת את כפרת הקרבן. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על הכתוב \u0003\"וסמך\u0004 ידו על ראש העולה \u0003ונרצה\u0004 לו לכפר עליו\". ויש לשאול: \u0003וכי\u0004 ה\u0003סמיכה\u0004 היא ה\u0003מכפרת? והלא אין\u0004 ה\u0003כפרה\u0004 באה \u0003אלא ב\u0004הזאת ה\u0003דם, ש\u0004כן \u0003נאמר\u0004 במפורש בעניינו של הדם \"כי נפש הבשר בדם היא ואני נתתיו לכם על המזבח לכפר על נפשותיכם \u0003כי הדם הוא בנפש יכפר\"\u0004 (שם יז, יא)! \u0003אלא\u0004 בא הכתוב \u0003לומר לך, שאם עשאה לסמיכה,\u0004 מתוך זלזול שהיא רק \u0003שירי מצוה,\u0004 ולא כחלק מההקרבה, \u0003מעלה עליו הכתוב כאילו לא כיפר\u0004 כפרה גמורה בקרבן זה, \u0003ו\u0004אף שלהלכה למעשה הרי בכל זאת \u0003כיפר\u0004 הקרבן.","\u0003ו\u0004בדומה לכך גם \u0003תניא\u0004 \u0005[שנויה]\u0006 ברייתא נוספת ל\u0003גבי\u0004 \u0005[אצל]\u0006 מצות ה\u0003תנופה\u0004 בקרבן המצורע \u0003כי האי גוונא\u0004 \u0005[כעין זה].\u0006 שכן נאמר בקרבן המצורע הדל \"...ולקח כבש אחד אשם \u0003לתנופה לכפר\u0004 עליו...\" (שם יד, כא). ואף על הנאמר בכתוב זה יש לתהות: \u0003וכי\u0004 ה\u0003תנופה\u0004 היא ה\u0003מכפרת?\u0004 \u0003והלא אין\u0004 ה\u0003כפרה\u0004 באה \u0003אלא ב\u0004הזאת ה\u0003דם, ש\u0004כן \u0003נאמר \"כי הדם הוא בנפש יכפר\"\u0004 (שם יז, יא)! \u0003אלא\u0004 בא הכתוב \u0003לומר לך שאם עשאה לתנופה,\u0004 מתוך התייחסות אליה רק כ\u0003שירי מצוה, מעלה עליו הכתוב כאילו לא כיפר\u0004 כפרה של ממש בקרבן זה, \u0003ו\u0004הגם שלהלכה למעשה הרי בכל זאת \u0003כיפר\u0004 הקרבן.","שנינו במשנה במעשה הסמיכה שהריהי נעשית \u0003על הראש\u0004 של הקרבן. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על הכתוב \"וסמך \u0003ידו על\u0004 ראש העולה\": הדגשה זו על \u0003הראש\u0004 באה להוראה: דווקא על ראש הקרבן תהא ידו של הסומך, \u0003ולא\u0004 שתהא \u0003ידו על הצואר\u0004 (גרון הבהמה) וכן שתהא \u0003ידו\u0004 של הסומך \u0003על הראש\u0004 של הקרבן, \u0003ולא\u0004 שתהא \u0003ידו על ה\u0004\u0003גביים\u0004 (גב הבהמה). וכן שתהא \u0003ידו על הראש\u0004 של הקרבן, \u0003ולא\u0004 שתהא \u0003ידו על\u0004 \u0003החזה\u0004 של הבהמה.","ושואלים: \u0003כל\u0004 ההוראות \u0003הני\u0004 \u0005[הללו]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003צריכי\u0004 \u0005[נצרכות]\u0006 כולן להיאמר, \u0003דאי כתב רחמנא חד\u0004 \u0005[שאם היתה כותבת התורה\u0006 רק \u0005אחת\u0006 מהם\u0005],\u0006 הייתי אומר כי באה הוראה זו \u0003למעוטי\u0004 \u0005[למעט]\u0006 דווקא את מקום ה\u0003צואר\u0004 מכלל הסמיכה, וטעם הדבר: משום \u0003דלא קאי בהדי\u0004 \u0005[ש\u0006הצואר, הגרון \u0005אינו עומד\u0006 בגובה שווה \u0005יחד]\u0006 עם \u0003ראשו\u0004 של הקרבן. \u0003אבל גבו\u0004 של הקרבן, \u0003דקאי להדי\u0004 \u0005[שעומד\u0006 הוא \u0005ביחד]\u0006 עם \u0003ראשו אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ואפשר לסמוך עליו כך. לכך \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר גם הוראה זו.","\u0003ואי אשמעינן הני תרי\u0004 \u0005[ואם\u0006 הכתוב \u0005היה משמיע לנו\u0006 רק את \u0005שתי\u0006 ההוראות \u0005הללו],\u0006 היינו אומרים כי דווקא שני מקומות אלה אינם ראויים לסמיכה בבהמה, וזאת \u0003משום\u0004 ש\u0003לא\u0004 \u0003איתרבי\u0004 \u0005[לא התרבו]\u0006 שני \u0005איברים אלה בקרבן\u0006 \u0003ל\u0004ענין דין ה\u0003תנופה,\u0004 \u0003אבל חזה דאיתרבי\u0004 \u0005[שהתרבה]\u0006 \u0003לתנופה\u0004 בקרבן (תנופת חזה ושוק), \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ואפשר לסמוך עליו כך. לכך \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר גם הוראה זו.","שנינו במשנה שהסמיכה צריכה להיות על ראש הבהמה, ומעתה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמי בית המדרש\u0005]:\u0006 אם היתה הסמיכה על ראש הבהמה, ואולם הסומך שם \u0003ידו על הצדדין\u0004 של ראש הקרבן, \u0003מהו\u0004 דינו, האם עלתה לו בכך סמיכה? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו מהלכה זו \u0003דתניא\u0004 \u0005[ששנויה\u0006 בברייתא\u0003],\u0004 \u0003אבא ביראה בר' אליעזר בן יעקב אומר:\u0004 הכתוב \"וסמך \u0003ידו\u0004 על ראש העולה\" בא להורות \u0005כי דווקא\u0006 \u0003על\u0004 גובה \u0003ראשו\u0004 של הקרבן, \u0003ולא\u0004 שתהא \u0003ידו על הצדדין\u0004 של ראש הקרבן.","ועוד בדיני הסמיכה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 כרך \u0005הסומך\u0006 \u0003מטלית\u0004 על ידו, \u0003מהו\u0004 הדין \u0003שתחוץ\u0004 (שתיחשב המטלית לחציצה) בין ידו של הסומך לבין ראש הקרבן? ואומרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו מברייתא, ששנינו בה: \u0003ובלבד שלא תהא דבר חוצץ בינו לבין הזבח.\u0004","\u0003ו\u0004עוד שנינו במשנתנו כי הסמיכה נעשית \u0003ב\u0004הנחת \u0003שתי\u0004 ה\u0003ידים\u0004 של הסומך על ראש הקרבן. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 מה מקורם בתורה? \u0003אמר ריש לקיש,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בסדר עבודת יום הכיפורים \u0003\"וסמך אהרן את שתי ידו\u0004 על ראש השעיר החי והתודה עליו...\" (ויקרא טז, כא), ואף שהקריאה בכתוב היא \"ידיו\", \u0003כתיב\u0004 \u0005[נאמר]\u0006 בו, בכתיב חסר, \u0003\"ידו\", ו\u0004כן \u0003כתיב\u0004 \u0005[נאמר]\u0006 בו עוד המלה \u0003\"שתי\"\u0004 — הרי \u0003זה בנה\u0004 (בנין) \u0003אב,\u0004 הנוגע להלכות אחרות, המלמד כי ב\u0003כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו \u0003\"ידו\"\u0004 — \u0003הרי\u0004 הכוונה \u0003כאן\u0004 היא ל\u0003שתים, עד שיפרט לך הכתוב\u0004 ויאמר במפורש \u0003\"אחת\".\u0004","מסופר כי \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' אלעזר\u0004 ו\u0003אמרה להא שמעתא בבי מדרשא\u0004 \u0005[את השמועה,\u0006 ההלכה, \u0005הזו\u0006 שאמר ריש לקיש \u0005בבית המדרש],\u0006 \u0003ולא אמרה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ריש לקיש. שמע\u0004 על כך \u0003ריש לקיש ואיקפד\u0004 \u0005[והקפיד]\u0006 על שלא נמסרו הדברים בשם אומרם. ומשום שהקפיד הקשה עליו, ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' אלעזר: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר \u0003כי\u0004 \u0003כל היכא דכתיב\u0004 \u0005[מקום שכתוב]\u0006 בו \u0003\"ידו\"\u0004 — \u0003תרתי נינהו\u0004 \u0005[שתי\u0006 ידיים \u0005הן],\u0006 אם כן, \u0003למה לי למכתב\u0004 \u0005[לכתוב]\u0006 בתורה \u0003\"ידיו\" \"ידיו\"\u0004 בלשון רבים, והרי די לומר \"ידו\"?","ונמסר כי ריש לקיש \u0003אקשי ליה\u0004 \u0005[הקשה לו]\u0006 לר' אלעזר מ\u0003עשרים וארבע\u0004 מקומות שכתוב בהם \u0003\"ידיו\",\u0004 וכגון \u0003\"...ידיו\u0004 \u0003תביאינה\u0004 את אשי ה' ...\" (שם ז, ל), \u0003\"...ידיו רב לו\u0004 ועזר מצריו תהיה\" (דברים לג, ו), \u0003\"...שכל את ידיו\u0004 כי מנשה הבכור\" (בראשית מח, יד), \u0003אישתיק\u0004 \u0005[שתק]\u0006 ר' אלעזר, שלא מצא תשובה לדבר.","\u0003לבתר דנח דעתיה\u0004 \u0005[לאחר שנחה דעתו\u0006 של ריש לקיש\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' אלעזר: \u0003מאי טעמא לא תימא\u0004 \u0005[מה הטעם לא אמרת]\u0006 \u0003לי\u0004 בתשובה על שאלותיי, כי כלל זה ש\"ידו\" האמורה בתורה הכוונה היא לשתי ידיים — רק ב\u0003ידיו\u0004 של אדם הנאמרים בהקשר ל\u0003סמיכה קאמרי\u0004 \u0005[אני אומר],\u0006 ואילו במקום אחר רק כשנאמר \"ידיו\" הרי זה שתי ידיים. ולכך אין להקשות מדוע נאמר בכל עשרים וארבעה המקומות הללו \"ידיו\".","ומקשים על תירוץ זה: והרי \u0003ב\u0004ענין \u0003סמיכה נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 הלשון \"ידיו\" ולא \"ידו\", כנאמר בסמיכת יהושע על ידי משה: \u0003\"ויסמך את ידיו עליו\u0004 \u0003ויצוהו...\"\u0004(במדבר כז, כג)! ומשיבים: כלל זה שכל מקום שנאמר בו \"ידו\" הכוונה לשתי ידיים — דווקא ב\u0003סמיכה\u0004 של \u0003בהמה קאמרי\u0004 \u0005[אמרתי],\u0006 אבל בסמיכה על האדם (דוגמת סמיכת משה על ראש יהושע) הלשון \"ידו\" משמעה יד אחת, ולכך הוזקק הכתוב לומר \"ידיו\" להורות כי היתה זו סמיכה בשתי ידיים.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003במקום ש\u0004בו \u0003סומכין\u0004 על הקרבן, שם גם \u0003שוחטין\u0004 אותו. והוסיפה המשנה ואמרה \u0005כי\u0006 \u0003תכף לסמיכה שחיטה.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]\u0006 בכך שבמקום שבו סומכים שם שוחטים את הקרבן, די היה לומר כי תיכף לסמיכה על הקרבן היא שחיטתו, ומכך נבין שבמקום שבו סומכים על הקרבן שם הוא נשחט? ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך משמעות הדברים, \u0003במקום ש\u0004בו \u0003סומכין\u0004 על הקרבן שם גם \u0003שוחטין\u0004 אותו, ומדוע? משום \u0003שתכף לסמיכה שחיטה,\u0004 ולכן אין לוקחים את הבהמה למקום אחר.","יש \u0003חומר\u0004 (צד חומרה) הנוהג \u0003בסמיכה\u0004 על הקרבן \u0003מבתנופה,\u0004 שאין נוהג בה צד זה. \u0003ו\u0004כן יש צד חומרה הנוהגת \u0003בתנופה מבסמיכה.\u0004 \u0005ומפרטים: חומרה הנוהגת בסמיכה שאינה נוהגת בתנופה:\u0006 \u0003ש\u0004אם חברו \u0005כמה אנשים לקרבן אחד —\u0006 \u0003אחד\u0004 מהם \u0003מניף ל\u0004מען \u0003כל החברים.\u0004 \u0003ו\u0004אולם \u0003אין אחד\u0004 החברים על הקרבן \u0003סומך לכל החברים,\u0004 אלא כל אחד צריך לסמוך לעצמו. ומצד שני, \u0003חומר\u0004 שיש \u0003בתנופה\u0004 ואין בסמיכה: \u0003שהתנופה נוהגת בקרבנות היחיד\u0004 (כשלמים, שאימוריהם וחזה ושוק \u0005שלהם הריהם מונפים),\u0006 \u0003ובקרבנות הצבור\u0004 (בשני \u0005כבשי עצרת, המונפים חיים עם שתי הלחם).\u0006"],["ונעשית בקרבנות כשהם \u0003בחיים\u0004 (כאשם \u0003מצורע וככבשי העצרת)\u0004 \u0003ו\u0004כן \u0003ב\u0004קרבנות כשהם כבר \u0003שחוטין\u0004 (כתנופת חזה ושוק בשלמי יחיד), מה שאין כן בסמיכה, שאינה נוהגת אלא בעוד הבהמה בחיים. \u0003ו\u0004צד חומרה נוסף בתנופה, שכן התנופה נוהגת הן \u0003בדבר\u0004 קרבן \u0003שיש בו רוח חיים\u0004 (כקרבן בהמה), \u0003ו\u0004הן \u0003בדבר\u0004 קרבן \u0003שאין בו רוח חיים\u0004 (כמנחת העומר, ומנחת הסוטה, ולחמי התודה והנזיר), \u0003מה שאין כן בסמיכה\u0004 שאינה נוהגת אלא בבעלי חיים.","שנינו במשנתנו כי יש צדדי חומרה בסמיכה על פני התנופה ובתנופה על פני הסמיכה. ובענין זה מביאים עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר בדין הסמיכה \"וסמך ידו על ראש קרבנו...\" (ויקרא ג, ב). והלשון \u0003\"קרבנו\"\u0004 באה \u0003לרבות כל בעלי קרבן לסמיכה,\u0004 שיהיו כל השותפים בקרבן סומכים עליו (צג,א). ומסבירים: הוצרכה דרשה זו, \u0003ש\u0004כן \u0003יכול\u0004 הייתי לומר שרק אחד מן השותפים סומך וסמיכתו מועילה לכולם. \u0003והלא\u0004 \u0003דין\u0004 (קל וחומר) \u0003הוא,\u0004 ובזה האופן: \u0003ומה תנופה\u0004 החמורה בדינה (בהשוואה לסמיכה), \u0003ש\u0004הרי \u0003נתרבתה\u0004 להיעשות אף \u0003ב\u0004קרבנות \u0003ה\u0004\u0003שחוטין\u0004 — בכל זאת \u0003נתמעטה בחוברין\u0004 (בשותפים לקרבן), שרק אחד הוא המניף עבור כולם. מעתה, \u0003סמיכה\u0004 הקלה בדינה (בהשוואה לתנופה), \u0003ש\u0004הרי \u0003לא נתרבתה\u0004 להיעשות אף \u0003בשחוטין\u0004 אלא בבהמות החיות בלבד — \u0003אינו דין שתתמעט בחוברין,\u0004 ורק אחד יסמוך! לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"קרבנו\"\u0004 — \u0003לרבות כל בעלי קרבן לסמיכה.\u0004","","","","","","","","","","","ושואלים לצד אחר: \u0003ו\u0004מעתה נלמד \u0003ש\u0004\u0003תתרבה\u0004 ה\u0003תנופה\u0004 להיעשות אף \u0003בחוברין\u0004 שכולם יניפו את קרבנם, ונלמד כך \u0003מקל וחומר: ומה סמיכה\u0004 הקלה בדינה (בהשוואה לתנופה) \u0003ש\u0004הרי \u0003לא נתרבתה\u0004 להיעשות \u0003בשחוטין\u0004 — בכל זאת \u0003נתרבתה בחוברין,\u0004 וסומכים כולם. \u0003תנופה\u0004 החמורה בדינה (בהשוואה לסמיכה), \u0003ש\u0004הרי \u0003נתרבתה\u0004 להיעשות אף \u0003בשחוטין\u0004 (מה שאין כן סמיכה שאינה נעשית אלא בחיים) — \u0003אינו דין שנתרבתה בחוברין!\u0004 ומשיבים: אין למדים כן, \u0003משום\u0004 ש\u0003לא אפשר\u0004 לעשות שכל השותפים בקרבן יניפו אותו. שכן \u0003היכי ליעביד\u0004 \u0005[כיצד יעשה]?\u0006 אם תאמר \u0003לינפו כולהו בהדי הדדי\u0004 \u0005[שיניפו כולם ביחד],\u0006 כאשר כל אחד מהם יניח ידו על יד חבירו — \u0003קא הויא\u0004 \u0005[הרי זו]\u0006 \u0003חציצה,\u0004 שכן ידו של אחד המונחת על הקרבן חוצצת בין הקרבן לבין ידו של המניף אותו, המונחת עליה! ואם תאמר שיניפו כולם לא בבת אחת, אלא בזה אחר זה שבתחילה \u0003ליניף\u0004 \u0005[שיניף]\u0006 אחד מהם, \u0003וליהדר וליניף\u0004 \u0005[ויחזור ויניף]\u0006 חבירו — אין זו תנופה ראויה. שכן \u0003תנופה\u0004 אחת \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שיש לעשות, \u0003ולא תנופות\u0004 רבות. שנינו במשנתנו כי אין הסמיכה נוהגת בשחוטים. ושואלים: \u0003ו\u0004האם \u0003סמיכה ב\u0004קרבנות ה\u0003שחוטין ליתא\u0004 \u0005[אין]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה שבסוף מסכת תמיד\u0005]\u0006 כי רשאי הכהן הגדול להקריב בכל עת שירצה כל קרבן הקרב במקדש. ולכן \u0003בזמן שכהן גדול רוצה להקטיר\u0004 (להקריב) את אברי קרבן התמיד ומנחתו, \u0003היה עולה בכבש\u0004 המזבח אל ראש המזבח, \u0003והסגן\u0004 (הכהן הממונה תחתיו) מהלך עמו \u0003ב\u0004צד \u0003ימינו.\u0004 ואם אירע ו\u0003הגיע\u0004 הכהן הגדול \u0003למחצית הכבש\u0004 והתעייף — \u0003אחז\u0004 ה\u0003סגן בימינו\u0004 ועזר לו \u0003והעלהו\u0004 לראש הכבש, אל המזבח. \u0003והושיט לו\u0004 הכהן \u0003הראשון\u0004 (מתשעת הכהנים שזכו בפייס בהעלאת האברים למזבח) את \u0003הראש והרגל\u0004 של הקרבן. והכהן הגדול \u0003סומך עליהם\u0004 את ידיו, \u0003ו\u0004לאחר מכן הריהו \u0003זורקן\u0004 על אש המזבח. ולאחר מכן \u0003הושיט\u0004 הכהן \u0003השני ל\u0004כהן \u0003ה\u0004\u0003ראשון\u0004 את \u0003שתי\u0004 ה\u0003ידים\u0004 (הרגליים הקדמיות של הקרבן), והכהן הראשון \u0003נותנו לכהן גדול,\u0004 ושוב הכהן הגדול \u0003סומך עליהם וזורקן\u0004 על אש המזבח. ולאחר מכן \u0003נשמט\u0004 (עזב) הכהן \u0003השני והלך לו,\u0004 שהרי אין בו עוד צורך לעבודה. ואילו הכהן הראשון נשאר על מקומו, שהרי הוא המגיש לכהן הגדול את שאר האברים הקרבים. \u0003וכך היו\u0004 שאר הכהנים שזכו בהעלאת האברים למזבח, \u0003מושיטין לו\u0004 לכהן הראשון את \u0003שאר כל האברים,\u0004 כסדר הקרבתם, והכהן הגדול מקבלם מיד הכהן הראשון, ו\u0003סומך עליהם, וזורקן\u0004 על אש המזבח. \u0003ובזמן שהוא\u0004 הכהן הגדול \u0003רוצה\u0004 — \u0003הוא\u0004 רק \u0003סומך\u0004 על אברי הקרבן, \u0003ו\u0004כהנים \u0003אחרים\u0004 הם ש\u0003זורקין\u0004 את האברים על אש המזבח. הרי משמע שיש סמיכה גם בשחוטים! \u0003אמר אביי:\u0004 בכהן גדול המקטיר, אין הסמיכה נעשית משום שכך היא מצות הקרבן, אלא \u0003התם\u0004 \u0005[שם]\u0006 טעם הדבר הוא \u0003משום כבודו\u0004 של \u0003כהן גדול,\u0004 הנראה בכך כמי שהקריב את כולם. \u0003שתי\u0004 חלות \u0003הלחם\u0004 הקרבות בחג השבועות, \u0003נילושות\u0004 מעשרון סולת, כל \u0003אחת\u0004 ו\u0003אחת\u0004 לעצמה. שלאחר שלשו את החלה האחת, חוזרים ולשים את החלה השנית. \u0003ו\u0004כן הריהן \u0003נאפות\u0004 בתנור כל \u0003אחת\u0004 ו\u0003אחת\u0004 לעצמה. שלאחר שאפו את החלה האחת, חוזרים ואופים את החלה השנית. ואילו שתים עשרה חלותיו של \u0003לחם הפנים,\u0004 אותו עורכים על שולחן הפנים שבהיכל בכל שבת ושבת, אף שהן \u0003נילושות\u0004 כל \u0003אחת\u0004 ו\u0003אחת\u0004 לעצמה, \u0003ו\u0004אולם הריהן \u0003נאפות שתים שתים. וב\u0004תוך \u0003דפוס\u0004 (תבנית קבועה) \u0003היה עושה אותן\u0004 (את החלות) בלישתן ובאפייתן, וכן \u0003כשהוא רודן\u0004 (מוציאן מן התנור) היה \u0003נותנן\u0004 שוב \u0003ל\u0004תוך \u0003דפוס, כדי שלא יתקלקלו\u0004 (תישברנה) החלות, אם תינתנה בדבר שאינו דפוס. שנינו במשנתנו כי חלות שתי הלחם היו נילושות ונאפות כל אחת לעצמה, ואילו חלות לחם הפנים, אף שנילושות כל אחת לעצמה, הריהן נאפות בתנור שתים שתים. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו,\u0006 מה מקורם בתורה\u0005]?\u0006 — \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 בברייתא על הכתוב \"ולקחת סולת ואפית אותה שתים עשרה חלות שני עשרונים יהיה החלה האחת. ושמת אותם שתים מערכות שש המערכת על השולחן הטהור לפני ה' \"(ויקרא כד, ה—ו). ודיוק הכתוב \u0003\"שני עשרנים יהיה החלה האחת\"\u0004 \u0003מלמד שנילושות\u0004 כל אחת משתים עשרה החלות \u0003אחת אחת\u0004 לעצמה. ו\u0003מנין\u0004 לנו \u0003שאף\u0004 ב\u0003שתי הלחם כך\u0004 הוא הדין, שנילושים אחד אחד? \u0003תלמוד לומר\u0004 בכתוב זה \u0003\"יהיה\"\u0004 — לרבות אף את שתי הלחם לענין זה. וממשיכים: \u0003ומנין\u0004 לנו \u0003שאפייתן\u0004 של חלות לחם הפנים הריהי \u0003שתים שתים,\u0004 ולא אחת אחת? — \u0003תלמוד לומר \"ושמת אותם\"\u0004 (שם), ומיעוט רבים שנים. \u0003יכול אף\u0004 ב\u0003שתי הלחם כן,\u0004 ששניהם נאפים כאחד? — \u0003תלמוד לומר \"אותם\"\u0004 — למעט, דווקא לחמי הפנים נאפים שנים שנים, ואין שתי הלחם נאפים שנים שנים.","ושואלים על דרשה זו: \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"אותם\" הא אפיקתיה\u0004 \u0005[הרי כבר הוצאת,\u0006 דרשת \u0005אותו]\u0006 לענין אפיית לחמי הפנים שיהיו שנים שנים! ומשיבים: \u0003אם כן\u0004 שבא כתוב זה רק להשמיענו אפיית שני לחמי פנים, \u0003לימא קרא\u0004 \u0005[שיאמר המקרא]\u0006 בקיצור \u0003\"ושמתם\"\u0004 ולא \"ושמת אותם\", ומצורת הרבים הייתי למד את דין אפיית שני לחמי פנים, אלא ודאי \u0003מאי\u0004 \u0005[מה]\u0006 באה ללמד הרחבת הכתוב \u0003\"ושמת אותם\"? שמעת\u0004 (למדת) \u0003מיניה תרתי\u0004 \u0005[ממנו שני\u0006 דינים\u0005],\u0006 הן לענין אפיית שני לחמי פנים, והן למעט את שתי הלחם מאפיית שניים\u0005.\u0006","שנינו במשנתנו כי החלות היו ניתנות בתוך דפוס, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מה שנאמר בלחם הפנים \u0003\"ושמת אותם\"\u0004 — כוונתו \u0003בדפוס.\u0004 ומסבירים: \u0003שלשה דפוסין הם\u0004 שהיו במקדש לעשיית הלחם: לאחר שנילוש הבצק, הריהו \u0003נותנה לדפוס, ועדיין היא בצק\u0004 — הרי זה דפוס ראשון. \u0003וכמין דפוס היה לה בתנור\u0004 כשהיא נאפית — הרי זה דפוס שני. \u0003וכשהוא רודה\u0004 את החלה מן התנור הריהו \u0003נותנה בדפוס, כדי שלא תתקלקל\u0004 — הרי זה הדפוס השלישי. ושואלים: \u0003ו\u0004מדוע נזקקים אנו לדפוס שלישי זה, \u0003להדרה\u0004 \u0005[שיחזיר אותה]\u0006 \u0003לדפוס קמא\u0004 \u0005[הראשון]\u0006 שבו נילושה! ומשיבים: \u0003כיון דאפי לה, נפחה\u0004 \u0005[שאופים אותה, היא מתנפחת]\u0006 ושוב היא אינה יכולה להיכנס לדפוס הראשון בו היא נילושה.","ולאחר שנידון עניינם של דפוסי החלות, דנים עתה בצורתו של לחם הפנים הנתון בהם. \u0003איתמר\u0004 \u0005[נאמר]\u0006 בדברי חכמים \u0005:\u0006 \u0003לחם הפנים, כיצד\u0004 באיזו צורה \u0003עושין אותו?\u0004"],["\u0003ר' חנינא אמר:\u0004 צורתו היתה \u0003כמין תיבה\u0004 (מבנה מרובע, בעל דפנות מקבילות זו לזו, ובעל בסיס רחב) \u0003פרוצה\u0004 ששתי דפנות אחרות לא היו בה. \u0003ר' יוחנן אמר:\u0004 צורתו של לחם הפנים היתה \u0003כמין ספינה\u0004 (מבנה משולש, שבסיסו צר ושתי דפנות יוצאות ממנו והולכות ומשתפעות לצדדים), ובהיעדר בסיס רחב, הריהי \u0003רוקדת\u0004 (נעה מצד לצד). ודנים עתה בשתי השיטות הללו.","ואומרים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר,\u0006 ר' חנינא\u0005]\u0006 שצורתו של לחם הפנים היתה \u0003כמין תיבה פרוצה\u0004 — \u0003היינו דהוו יתבי\u0004 \u0005[זהו\u0006 ההסבר איך \u0005שהיו ישובים,\u0006 מונחים\u0005]\u0006 ה\u0003בזיכין\u0004 של הלבונה. שהרי לשיטה זו היו ללחם הפנים שוליים ישרים ורחבים, וניתן היה איפוא להציב בתוכם את הבזיכים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר,\u0006 ר' יוחנן\u0005]\u0006 שצורת לחם הפנים היתה \u0003כמין ספינה רוקדת,\u0004 ולא היו איפוא ללחם שוליים, וצדדיו החיצוניים של הלחם היו משופעים — \u0003היכי הוו יתבי\u0004 \u0005[היכן היו ישובים,\u0006 מונחים\u0005]\u0006 ה\u0003בזיכין?\u0004 ומשיבים: \u0003מקום עביד להו\u0004 \u0005[היה עושה להם,\u0006 לבזיכים\u0005]\u0006 בצידו של הלחם, שבו הונחו הבזיכים.","ומוסיפים ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר,\u0006 ר' חנינא\u0005]\u0006 שצורתו של לחם הפנים היתה \u0003כמין תיבה פרוצה\u0004 — \u0003היינו דהוו יתבי\u0004 \u0005[זהו\u0006 ההסבר איך \u0005שהיו ישובים,\u0006 מונחים\u0005]\u0006 ארבעת עשר ה\u0003קנים\u0004 שבכל אחת משתי מערכות לחם הפנים, עליהם היו מונחים לחמי הפנים (מלבד החלה התחתונה, שהיתה נתונה על השולחן עצמו), זה למעלה מזה. כאשר כל חלה מונחת על גבי שלושה קנים (מלבד החלה העליונה, המונחת על שני קנים בלבד). \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר,\u0006 ר' יוחנן\u0005]\u0006 שצורת לחם הפנים היתה \u0003כמין ספינה רוקדת,\u0004 ולא היו איפוא ללחם שוליים, וצדדיו החיצוניים של הלחם היו משופעים — ה\u0003קנים\u0004 הללו \u0003היכי הוו יתבי\u0004 \u0005[איך היו ישובים,\u0006 מונחים\u0005]?\u0006 שהרי היו צריכים להחזיק את הלחם ומאחר והיה בסיסו צר לא היה מקום אלא לקנה אחד! ומשיבים: \u0003מורשא עביד להו\u0004 \u0005[פינה,\u0006 תוספת זויתית, \u0005היה עושה להם]\u0006 ללחמים להרחיב את בסיסם במעט ששם היו הקנים נתפסים.","ומוסיפים ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר,\u0006 ר' חנינא\u0005]\u0006 שצורתו של לחם הפנים היתה \u0003כמין תיבה פרוצה\u0004 — \u0003היינו דסמכי ליה\u0004 \u0005[זהו\u0006 ההסבר איך \u0005שהיו סומכים אותו]\u0006 ה\u0003סניפין\u0004 (לוחות הזהב שהיו ניצבים בקצות השולחן אל מול מערכות הלחם, ועולים אל מעל לגובה השולחן. ובראשי לוחות אלה ניתנו הקנים, עליהם ניתנו הלחמים) \u0003ללחם.\u0004 שהרי הלחם היה נתון (באורכו) על כל רוחבו של השולחן, ויתרת אורכו של הלחם שמחוץ לשולחן היתה נזקפת כלפי מעלה, בסמוך ובמקביל ללוחות שהיו תומכים בלחם, כדי שלא יפול ארצה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר,\u0006 ר' יוחנן\u0005]\u0006 שצורת לחם הפנים היתה \u0003כמין ספינה רוקדת,\u0004 וצדדיו החיצוניים של הלחם היו משופעים — \u0003היכי סמכי ליה\u0004 \u0005[כיצד סמכו אותו]\u0006 ה\u0003סניפין\u0004 הללו שהיו ישרים וזקופים \u0003ללחם,\u0004 שהיה משופע, שלא יפול ויתפורר, והלא לא נגעו הסניפים בלחם אלא בקצותיו העליונים בלבד! ומשיבים: \u0003דעגיל להו מיעגל\u0004 \u0005[שהיה מעגל אותם,\u0006 את הסניפים\u0005]\u0006 \u0005באופן שהיו משתפעים פנימה, שהיתה בהם בליטה כלפי פנים במקביל לשיפוע הלחמים, וכך תמכו הסניפים במלוא אורך הלחם, שלא יפול. ושואלים עתה מצד אחר:\u0006","\u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר,\u0006 ר' יוחנן\u0005]\u0006 שצורתו של לחם הפנים היתה \u0003כמין ספינה רוקדת,\u0004 \u0003היינו דבעינן\u0004 \u0005[זהו\u0006 הטעם לכך \u0005שצריכים אנו]\u0006 ל\u0003סניפין,\u0004 שכיון שאין ללחם שולים, ודפנותיו החיצוניים משופעים, לכך נזקק הוא לקנים שיתמכו בו ולסניפים בתוכם יינתנו הקנים, שהרי אין הלחם יכול לעמוד מכח עצמו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר,\u0006 ר' חנינא\u0003]\u0004 שצורת לחם הפנים היתה \u0003כמין תיבה פרוצה,\u0004 יש לשאול: \u0003סניפין למה לי?\u0004 שהרי הלחם יכול לעמוד בעצמו! ומשיבים: נזקקים אנו לסניפים, ובתוכם קנים כדי לשאת על גביהם את הלחמים, שכן אם היו הלחמים מונחים זה על גבי זה, ללא הפרדה של קנים, \u0003אגב יוקרא\u0004 \u0005[מתוך כובדו]\u0006 של ה\u0003לחם\u0004 — היה הלחם המונח תחתיו \u0003תלח\u0004 \u0005[נשבר].\u0006","ושבים ושואלים עוד: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר,\u0006 ר' יוחנן\u0005]\u0006 כי צורת לחם הפנים היתה \u0003כמין ספינה רוקדת\u0004 — מובן הדבר כי ה\u0003סניפין על גבי\u0004 ה\u0003שלחן\u0004 היו \u0003מונחין,\u0004 לצורך תמיכה בלחמים המשופעים, לבל יפלו ארצה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר,\u0006 ר' חנינא\u0005]\u0006 כי צורת לחם הפנים היתה \u0003כמין תיבה פרוצה,\u0004 וצורתם היתה מרובעת, \u0003כאשר יתרת אורכם, היוצאת אל מחוץ לשולחן, עולה כלפי מעלה בזקיפה\u0004 — \u0003את ה\u0004\u0003סניפין היכא מנח להו\u0004 \u0005[היכן מניח אותם]?\u0006 וכי \u0003אארעא מנח להו\u0004 \u0005[על הארץ מניח אותם]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שהרי כך \u0003אמר ר' אבא בר ממל: לדברי האומר כמין ספינה רוקדת\u0004 — \u0003סניפין על גבי שלחן\u0004 היו \u0003מונחין, לדברי האומר כמין תיבה פרוצה\u0004 — \u0003סניפין על גבי קרקע\u0004 היו \u0003מונחין.\u0004","ומבררים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 מבין החכמים הללו, \u0003אזלא הא\u0004 \u0005[הולכת\u0006 ברייתא \u0005זו]\u0006 ש\u0003אמר ר' יהודה: הלחם\u0004 הריהו \u0003מעמיד את הסניפין, והסניפין\u0004 הריהם \u0003מעמידין את הלחם,\u0004 שנשענים הם זה על זה? \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר\u0006\u0003]\u0004 שצורת לחם הפנים היתה \u0003כמין ספינה רוקדת,\u0004 כשיטת ר' יוחנן. שהרי לשיטת ר' חנינא, עמדו הסניפים על הארץ, ולא נזקקו לתמיכת הלחם."],["ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת ר' יוחנן מברייתא אחרת, ששנינו כי \u0003כמין\u0004 (כעין) צורת \u0003כוורת\u0004 של קנים \u0003היה לה\u0004 לדפוס בו נאפה לחם הפנים \u0003בתנור,\u0004 שהיה הדפוס מחורר בדומה לכוורת הקנים, \u0003ודומה\u0004 הוא \u0003כמין טבלא\u0004 (משטח) \u0003מרובעת.\u0004 משמע שצורת לחם הפנים היתה מרובעת! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 בלשון ברייתא זו: כמין כוורת היה לה בתנור, \u0003ופיה\u0004 (חלקו העליון) של הדפוס הריהו \u0003דומה כמין טבלא מרובעת,\u0004 ואולם תחתיתו של הלחם אכן היה קדקד צר, וללא שולים.","ומעירים: \u0003תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006שיטת \u0005מי שאומר]\u0006 שצורת לחם הפנים היתה \u0003כמין ספינה רוקדת, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0003]:\u0004 \u0003ארבעה סניפין של זהב היו שם,\u0004 בשולחן הפנים, והיו הסניפים הללו \u0003מפוצלין מראשיהן, כמין\u0004 קנים \u0003ה\u0004\u0003דקרנין\u0004 (בעלי ענפים מרובים ומפוצלים) \u0003היו, ש\u0004כן \u0003סומכין בהן את הלחם, שהוא דומה כמין ספינה רוקדת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים בבית המדרש\u0005]\u0006 שאלה זו: האם \u0003לחם הפנים\u0004 בזמן המשכן היה \u0003נפסל ב\u0004שעת \u0003מסעות\u0004 בני ישראל במדבר משום דין \"יוצא\", שהרי יצא מחוץ לקודש. שכן כשנסעו בני ישראל ממקום למקום במדבר, היו מפרקים את המשכן ונושאים את השולחן עם הלחם שעליו, \u0003או אינו נפסל במסעות?\u0004 ונחלקו החכמים \u0003ר' יוחנן ור' יהושע בן לוי\u0004 בדבר, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003נפסל\u0004 לחם הפנים במסעות, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003אינו נפסל\u0004 במסעות.","ומסבירים את נימוקיהם: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003נפסל\u0004 לחם הפנים במסעות — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בסדר המסעות \"ונסע אהל מועד מחנה הלוים בתוך המחנות \u0003כאשר יחנו כן\u0004 \u0003יסעו\u0004 איש על ידו לדגליהם\" (שם ב, יז), והרי זה בא להקיש חניה לנסיעה: \u0003מה ב\u0004שעת \u0003חנייתו\u0004 של המשכן — \u0003נפסל\u0004 הלחם \u0003ב\u0004פסול ה\u0003יוצא\u0004 אל מחוץ לעזרה, \u0003אף ב\u0004שעת \u0003נסיעתו\u0004 של המקדש — \u0003נפסל\u0004 הלחם \u0003ב\u0004פסול \u0003יוצא.\u0004","ואילו \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי הלחם \u0003אינו נפסל\u0004 במסעות — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בסדר המסעות \u0003\"ולחם התמיד עליו יהיה\"\u0004 (במדבר ד, ז), ללמד שכל עוד הלחם על השלחן, ואף בשעת מסעות, הריהו בכלל \"לחם התמיד\", ובקדושתו עומד.","ושואלים: \u0003ואידך נמי\u0004 \u0005[ו\u0006החכם \u0005האחר גם כן]\u0006 זה הסבור שאין לחם הפנים נפסל במסעות, ואולם \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"כאשר יחנו כן יסעו\",\u0004 שהוקשה הנסיעה לחניה, ומעתה יש לפסול את הלחם בנסיעה משום יוצא! ומשיבים: היקש זה בא להורות \u0003לאידך גיסא\u0004 \u0005[לצד אחר]:\u0006 \u0003מה בחנייתו, כי\u0004 \u0005[כאשר]\u0006 \u0003לא יצא\u0004 הלחם \u0003ממקומו\u0004 ונשאר על שולחן הפנים — \u0003לא מיפסיל\u0004 \u0005[אינו נפסל]\u0006 משום יוצא. \u0003אף בנסיעתו כי\u0004 \u0005[כאשר]\u0006 \u0003לא יצא\u0004 הלחם \u0003ממקומו\u0004 — \u0003לא מיפסיל\u0004 \u0005[אינו נפסל].\u0006 משום יוצא.","ושואלים לצד האחר: \u0003ואידך נמי\u0004 \u0005[ו\u0006החכם \u0005האחר גם כן]\u0006 זה הסבור שלחם הפנים נפסל במסעות, ואולם \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ולחם התמיד עליו יהיה\",\u0004 ולמדנו מכאן כי כל עוד הלחם על השולחן, הריהו בקדושתו! \u0003אלא\u0004 יש לומר באופן אחר את מחלוקתם זו של ר' יוחנן ור' יהושע בן לוי, ואמנם \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 לחכמים במה נחלקו ר' יוחנן ור' יהושע בן לוי: כאשר הלחם \u0003מסודר\u0004 על שולחן הפנים — \u0003דכולי עלמא\u0004 \u0005[הכל,\u0006 ר' יוחנן ור' יהושע בן לוי\u0005]\u0006 \u0003לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 ולדעת הכל אין הלחם נפסל במסעות. \u0003אלא כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003ב\u0004זמן שהלחם \u0003מסולק\u0004 מעל השולחן קודם הנסיעה.","ואלו נימוקיהם: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003נפסל\u0004 הלחם בפסול יוצא — משום \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בסדר המסעות \u0003\"כאשר יחנו כן יסעו\",\u0004 שהוקשה הנסיעה לחניה, ומעתה יש לומר: \u0003מה בחנייתו נפסל\u0004 הלחם \u0003ביוצא, אף בנסיעתו מיפסל\u0004 \u0005[נפסל]\u0006 הלחם \u0003ביוצא.\u0004","ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003אינו נפסל\u0004 הלחם במסעות — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ונסע אהל מועד\"\u0004 — להורות \u0003כי\u0004 \u0003אף על פי שנסע,\u0004 עדיין \u0003אהל מועד הוא.\u0004 ולכך, אין הלחם נפסל במסעות.","ושואלים: \u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר]\u0006 הסבור שלחם הפנים אינו נפסל במסעות, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"כאשר יחנו כן יסעו\",\u0004 שמקיש הכתוב חניה לנסיעה, ללמד שבדומה לחניה, אף בנסיעה נפסל הלחם ביוצא! ומתרצים: חכם זה מפרש את ההיקש \u0003לאידך גיסא\u0004 \u0005[לצד האחר],\u0006 ובאופן זה: \u0003מה בחנייתו\u0004 — \u0003כי לא מפיק ליה\u0004 \u0005[כאשר לא הוציאו אותו,\u0006 את הלחם\u0005]\u0006 מן העזרה, \u0003לא מיפסיל\u0004 \u0005[לא נפסל]\u0006 משום יוצא, \u0003אף בנסיעתו\u0004 — \u0003כי לא מפיק ליה\u0004 \u0005[כאשר לא הוציאו אותו]\u0006 מן העזרה, \u0003לא מיפסיל\u0004 \u0005[לא נפסל]\u0006 משום יוצא.","ושואלים לצד השני: \u0003ואידך נמי\u0004 \u0005[ו\u0006החכם \u0005האחר גם כן]\u0006 זה הסבור שלחם הפנים נפסל במסעות, ואולם \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ונסע אהל מועד\",\u0004 המלמד שאף בזמן הנסיעה קדושתו עליו, ולא יהא הלחם נפסל משום יוצא! ומשיבים: הכתוב \u0003ההוא\u0004 \"ונסע אוהל מועד\" לא בא להורות לענין קדושת המשכן בזמן המסעות אלא \u0003ל\u0004ענין ה\u0003ד\u0004\u0003גלים הוא דאתא\u0004 \u0005[שבא],\u0006 לגבי מקומו של אוהל מועד בין הדגלים בזמן המסעות.","ושואלים לצד השני: \u0003ואידך\u0004 \u0005[ו\u0006החכם \u0005האחר]\u0006 שלמד מכתוב זה לענין קדושת המשכן בשעת המסעות, מאין \u0005הוא למד על מקום המשכן בין הדגלים בזמן המסעות? ומשיבים: דבר זה\u0006 \u0003מ\u0004מה שנאמר באותו הכתוב \u0003\"\u0004\u0003מחנה הלוים בתוך המחנות\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005].\u0006","ולאחר שהתברר מקור שתי השיטות, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על השיטה הסבורה שלא נפסל הלחם במסעות ממה ששנינו בברייתא. ששנינו \u0003בשעת סילוק מסעות\u0004 כשהיו מפרקים את המשכן וגוללים את הפרוכות — ה\u0003קדשים נפסלין ביוצא,\u0004 שהרי זה נחשב כיציאה אל מחוץ למחנה שכינה. \u0003ו\u0004ה\u0003זבין\u0004 שצריכים לצאת אל מחוץ למחנה שכינה ומחנה לויה, \u0003ו\u0004ה\u0003מצורעין\u0004 שצריכים לצאת אף מחוץ למחנה ישראל הריהם \u0003משתלחין חוץ למחיצתן\u0004 (שהזבים יוצאים אל מחוץ למחנה לויה בזמן המסעות, והמצורעים יוצאים אל מחוץ למחנה ישראל בזמן המסעות). ומעתה \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 ה\"קדשים\" הנזכרים בברייתא זו שנפסלים ביוצא כוללים הכל, ו\u0003אפילו\u0004 את \u0003לחם הפנים,\u0004 ונמצא איפוא שלחם הפנים נפסל ביוצא בשעת המסעות! ודוחים: \u0003לא,\u0004 כוונת הברייתא שרוב הקדשים אכן נפסלים, ואולם \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מלחם הפנים,\u0004 שאינו נפסל ביוצא במסעות.","ועל הבחנה זו שבין לחם הפנים לשאר קדשים תוהים: \u0003מה נפשך\u0004 \u0005[מה רצונך]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 אתה אומר ש\u0003אהל מועד דוקא הוא,\u0004 שעומד הוא בקדושתו אף בזמן המסעות — \u0003אפילו\u0004 שאר \u0003קדשים נמי\u0004 \u0005[גם כן]\u0006 לא יפסלו ביוצא בזמן המסעות. ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003אהל מועד לאו\u0004 \u0005[לא]\u0006 \u0003דוקא הוא,\u0004 שאינו בקדושתו בזמן המסעות — \u0003אפילו לחם הפנים נמי\u0004 \u0005[גם כן]\u0006 יפסל משום יוצא!","\u0003אלא\u0004 יש לומר באופן אחר את דברי ר' יוחנן ור' יהושע בן לוי. ואמנם \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 שלא נחלקו ר' יוחנן ור' יהושע בן לוי, אלא \u0003מר\u0004 \u0005[חכם זה]\u0006 הסבור שאין הלחם נפסל במסעות \u0003אמר\u0004 את דינו \u0003ב\u0004לחם ה\u0003מסודר\u0004 על השולחן. \u0003ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה]\u0006 הסבור שהלחם נפסל במסעות \u0003אמר\u0004 את דינו \u0003ב\u0004לחם ה\u0003מסולק\u0004 מעל השולחן. \u0003ו\u0004נמצא כי \u0003לא פליגי\u0004 \u0005[לא נחלקו]\u0006 זה עם זה, אלא כל אחד אמר את דינו בענין אחר.","למדנו למעלה בדברי הברייתא כי הקדשים נפסלים בשעת המסעות. ועל כך \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003יש סילוק מסעות\u0004 גם \u0003בלילה,\u0004 שלעיתים יצאו בני ישראל למסעם במדבר גם בלילה, ולא רק ביום. וראייתו: \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003אין סילוק מסעות בלילה\u0004 — \u0003אימת מדלי\u0004 \u0005[אימתי היו ניטלים]\u0006 קלעי המשכן, וקפלו את המשכן ויצאו לדרך? אם תאמר כי \u0003לצפרא\u0004 \u0005[בבוקר]\u0006 היה זה, אם כן \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע מסביר שנפסלו הקדשים בשעת מסעות \u0003משום יוצא? תיפוק\u0004 \u0005[תצא,\u0006 תילמד\u0005]\u0006 \u0003לי דאיפסיל ליה\u0004 \u0005[שנפסל לו]\u0006 הקודש \u0003בלינה,\u0004 שהרי עבר עליו הלילה!","ומקשים על דברי אביי: מדוע נצרך להוכיח כי יש סילוק מסעות אף בלילה, והלא \u0003פשיטא\u0004 \u0005[פשוט],\u0006 הוא הדבר, שהרי בפרשה העוסקת בסדר המסעות \u0003\"ללכת יומם ולילה\"\u0004 (שמות יג, כא) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ומשמע שהלכו גם בלילה! \u0005ומשיבים: צריך להשמיענו כן, שכן אין ללמוד זאת מן הכתוב. שהרי\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 האמורים בכתוב \"ללכת יומם ולילה\" עניינם \u0003היכא דעקור ביממא\u0004 \u0005[היכן שעקרו,\u0006 שיצאו למסעם \u0005ביום]\u0006 והשמיענו הכתוב שהמשיכו ללכת אף בלילה, \u0003אבל היכא דלא עקור ביממא\u0004 \u0005[היכן שלא עקרו ביום],\u0006 \u0003בליליא לא מצו עקרי\u0004 \u0005[בלילה לא יכולים לעקור],\u0006 לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 אביי, \u0005משמיע לנו]\u0006 שגם בלילה הם יכולים \u0005לצאת.\u0006","עוד שנינו בברייתא שהובאה למעלה, שבשעת המסעות היו הזבים והמצורעים משתלחים אל מחוץ למחנה, הרי שסבורה היא שאף בשעת המסעות לא הסתלקה קדושת מחנות, \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה על כך\u0005]\u0006 ממה ששנינו כי בזמן מסע המחנות, לאחר ש\u0003הוגללו הפרוכת, הותרו הזבין ומצורעין ליכנס לשם,\u0004 למקום שעמד בו מקודם המשכן, הוא מחנה שכינה, משמע שהסתלקה קדושת מחנות! \u0003אמר רב אשי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ברייתא אחת היא כשיטת \u0003ר' אליעזר,\u0004 ואילו \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האחרת היא כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006"],["\u0003ר' אליעזר אומר: יכול\u0004 יהא הדין, שאם \u0003דחקו\u0004 (נדחקו בכח) \u0003ה\u0004\u0003זבין ו\u0004ה\u0003מצורעין, ונכנסו לעזרה\u0004 שבמקדש, \u0003ב\u0004קרבן \u0003פסח הבא בטומאה\u0004 (שהיו רוב העם טמאים למת), אף שלכתחילה אסור להם להיכנס לשם, \u0003יכול יהו חייבין\u0004 משום טומאה? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\"\u0004 (במדבר ה, ב), שהקיש הכתוב טמא מת לטמא הצרעת והזיבה ללמדנו: \u0003בשעה שטמאי מתים משתלחין\u0004 מן המחנה — אף \u0003ה\u0004\u0003זבין ו\u0004ה\u0003מצורעין משתלחין,\u0004 וחייבים כרת על שהייתם שם.","אבל כאשר \u0003אין טמאי מתים משתלחין,\u0004 כגון שהפסח בא בטומאה — אף \u0003אין זבין ומצורעין משתלחין,\u0004 ואינם חייבים כרת על כך. ומעתה יש לומר, כי אף בשעת המסעות, כיון שאין טמאי מת משתלחים מן המקום שהיה בו מחנה שכינה, אף הזבים והמצורעים אינם משתלחים משם. והברייתא האומרת שבשעה שהוגללו הפרוכת הותרו הזבים והמצורעים להיכנס למחנה שכינה הריהי כשיטת ר' אליעזר. ואילו הברייתא האומרת שאף בשעת המסעות הזבים והמצורעים היו משתלחים אל מחוץ למחנה, היא כשיטת חכמים.","\u0003אחת\u0004 (בין) \u0003שתי הלחם, ואחת\u0004 (ובין) \u0003לחם הפנים\u0004 — \u0003לישתן ועריכתן\u0004 (סידורו של הבצק) נעשים \u0003בחוץ\u0004 לעזרה, \u0003ו\u0004אילו \u0003אפייתן\u0004 נעשית \u0003בפנים\u0004 העזרה. \u0003ו\u0004אפייתן של שתי הלחם ולחם הפנים \u0003אינן דוחות את השבת.\u0004 ואילו \u0003ר' יהודה\u0004 \u0003אומר: כל מעשיהם\u0004 ואף לישתם ועריכתם נעשים \u0003בפנים\u0004 העזרה. \u0003ר' שמעון אומר, לעולם הוי\u0004 (היה) \u0003רגיל לומר: שתי הלחם ולחם הפנים\u0004 הריהם \u0003כשרות\u0004 אם נעשו \u0003ב\u0004תוך ה\u0003עזרה, ו\u0004הריהם \u0003כשרות\u0004 אם נעשתה לישתם ועריכתם ואף אפייתם גם \u0003ב\u0004מקום הנקרא \u0003ב\u0004\u0003ית פאגי\u0004 שמחוץ להר הבית. שלדעתו אף אפייתם יכולה להיות בחוץ.","שנינו במשנתנו כי לדעת התנא קמא לישתם ועריכתם הן של שתי הלחם והן של לחם הפנים נעשים מחוץ לעזרה, ואולם אפייתם נעשית בתוך העזרה. ומקשים על כך: \u0003הא גופא קשיא\u0004 \u0005[זה עצמו קשה].\u0006","שכן בתחילה \u0003אמרת\u0004 כי \u0003לישתן ועריכתן\u0004 נעשית \u0003בחוץ\u0004 לעזרה — \u0003אלמא\u0004 \u0005[מכאן]\u0006 יש ללמוד ש\u0003מדת יבש\u0004 (כלי המקדש ששימשו למדידת הדבר היבש), דוגמת הסולת, \u0003לא נתקדשה,\u0004 שהרי אם כלי מדידת היבש מקדש את הבא לתוכו — התקדש כבר הקמח המובא לשתי הלחם וללחם הפנים, ואין הוא יכול להיות נילוש ונערך בחוץ (שנפסל ביציאה אל מחוץ לעזרה). \u0003ו\u0004לאחר מכן שנינו במשנתנו כי \u0003אפייתן\u0004 של שתי הלחם ולחם הפנים נעשית דווקא \u0003בפנים\u0004 העזרה, ולא מחוצה לה — \u0003אלמא\u0004 \u0005[מכאן]\u0006 יש ללמוד ש\u0003מדת יבש נתקדשה! אמר רבה:\u0004 שאלה זו \u0003הקשה אדם קשה, שהוא קשה כברזל\u0004 (כינוי לתלמיד חכם חריף ביותר), \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 אותו תלמיד חכם? — \u0003רב ששת.\u0004","ותוהים על שאלה זו: \u0003מאי קשיא\u0004 \u0005[מה קושיה]\u0006 היא זו? \u0003דלמא\u0004 \u0005[שמא]\u0006 הכלי העשוי למדידת \u0003עשרון\u0004 הקמח לצורך לחם הפנים ושתי הלחם אכן \u0003לא מקדש\u0004 את הניתן בו, ואולם ה\u0003תנור מקדש\u0004 את הנאפה בו, ולכך אפו אותם דווקא בעזרה!","\u0003אלא\u0004 יש צורך לומר ש\u0003אי קשיא, הא קשיא\u0004 \u0005[אם קשה, זה\u0006 הוא ש\u0005קשה],\u0006 \u0003ו\u0004הסתירה היא מחלק אחר שבמשנתנו: שנאמר בתחילה במשנתנו כי \u0003אפייתן\u0004 של אלה נעשית \u0003בפנים\u0004 — \u0003אלמא\u0004 \u0005[מכאן]\u0006 יש ללמוד שה\u0003תנור מקדש\u0004 את הנאפה בתוכו. \u0003ו\u0004אילו לאחר מכן שנינו במשנתנו כי \u0003אין\u0004 לישתם ועריכתם ואפייתם \u0003דוחות את\u0004 \u0003השבת,\u0004 ולפיכך צריך לעשות אותם מלפני השבת — אם כן, לאחר שנתקדשו \u0003איפסלה\u0004 \u0005[נפסלת]\u0006 היא \u0003בלינה,\u0004 ככל קרבן שעבר עליו לילה, בלא שהוקרב על המזבח! \u0003אלא אמר רבא\u0004 על שאלה זו כי כך \u0003הקשה אדם קשה, שהוא קשה כברזל, ומנו\u0004 \u0005[ומי הוא]?\u0006 — \u0003רב ששת.\u0004","\u0003אמר רב אשי\u0004 על שאלה זו: \u0003מאי קושיא\u0004 \u0005[מה קושיה]\u0006 היא זו? \u0003דלמא\u0004 \u0005[שמא]\u0006 אין התנור מקדש את הנאפה בתוכו, ואין שתי הלחם ולחם הפנים שנאפו בו נפסלים בלינה, ו\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הנאמר במשנתנו בענין אפייתם שהוא \u0003\"מבפנים\"?\u0004 — לאו דווקא בתוך העזרה, אלא \u0003במקום\u0004 בו נמצאים כהנים ה\u0003זריזין\u0004 במלאכתם, האופים את אלה בזריזות, לבל יחמיצו.","ומעירים: \u0003והא\u0004 \u0005[וזו]\u0006 שאמר \u0003רב אשי ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 כלומר, אינה אימרה נכונה, כי \u0003מה נפשך\u0004 \u0005[רצונך]?\u0006 בכל אופן שאתה רוצה קשה: \u0003אי\u0004 \u0005[אם]\u0006 לצורך מלאכת ה\u0003אפייה בעינן\u0004 \u0005[צריכים אנו]\u0006 כהנים ה\u0003זריזין\u0004 במלאכתם — אף לצורך \u0003לישה ועריכה נמי בעינן\u0004 \u0005[גם כן צריכים אנו]\u0006 כהנים \u0003ה\u0004\u0003זריזין\u0004 במלאכתם. \u0003ואי\u0004 \u0005[ואם]\u0006 לצורך \u0003לישה ועריכה לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 כהנים ה\u0003זריזין\u0004 במלאכתם — אף לצורך \u0003אפייה נמי לא בעינן\u0004 \u0005[גם כן אין אנו צריכים]\u0006 כהנים ה\u0003זריזין\u0004 במלאכתם. ואילו משנתנו מבדילה בין לישה ועריכה לבין אפיה! \u0003אלא\u0004 צריך לומר שמה שאמר \u0003רב אשי ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 ואינה אימרה אמיתית.","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 כי \u0003כל מעשיהן\u0004 (לישתם, עריכתם ואפייתם) של לחם הפנים ושתי הלחם נעשים דווקא \u0003בפנים\u0004 העזרה. ואילו ר' שמעון סבור כי כל מלאכתם יכולה להיעשות בחוץ. ובהסבר מחלוקתם \u0003אמר ר' אבהו בר כהנא: ושניהן מקרא אחד דרשו,\u0004 שכן נאמר בדוד שבשעה שברח מפני שאול, בבואו אל אחימלך הכהן בנוב, וביקש ממנו לחם, ענהו הכהן \"...אין לחם חול אל תחת ידי כי אם לחם קודש...\" (שמואל א כא, ה), הוא לחם הפנים. והשיבו דוד \"...ויהיו כלי הנערים קודש (=שטהורים הם), \u0003והוא דרך חול אף כי היום יקדש בכלי\".\u0004","ובפירוש הדברים נחלקו חכמים, ש\u0003ר' יהודה סבר\u0004 כי \u0003ב\u0004יום \u0003חול\u0004 \u0003אשכחינהו\u0004 \u0005[מצאם]\u0006 דוד את הכהנים בעת \u0003דקא אפו ליה\u0004 \u0005[שהיו אופים אותו,\u0006 את לחם הפנים\u0003].\u0004 \u0003אמר להו\u0004 \u0005[להם]\u0006 דוד לכהנים בשאלה: כיצד זה ב\u0003דרך\u0004 (ביום) \u0003חול\u0004 \u0003קא אפיתו ליה\u0004 \u0005[אתם אופים אותו]?\u0006 שהרי בכך ו\u0003אף כי היום יקדש\u0004 הלחם \u0003בכלי\u0004 (בתנור), הלא \u0003איפסיל ליה\u0004 \u0005[יפסל לו]\u0006 למחרת \u0003בלינה.\u0004 ולכך אין אופים את לחם הפנים אלא בשבת. והרי שהתנור מקדש את הלחם, ולכן צריכה אפייתו להיות בפנים.","ואילו \u0003ר'\u0004 \u0003שמעון סבר\u0004 כי כך היו הדברים: \u0003בשבת אשכחינהו דקא אפו ליה\u0004 \u0005[מצא אותם שהם אופים אותו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא\u0004 כך יש לעשות, שכן אין לאפות אותו בשבת, אלא ב\u0003דרך\u0004 (ביום) \u0003חול בעיתו למיעבדיה\u0004 \u0005[צריכים אתם לעשותו\u0006\u0003]!\u0004 ואין לחשוש מלאפות את הלחם ביום חול, שמא התנור מקדש את הלחם, וייפסל בלינה, שהרי \u0003מידי\u0004 \u0005[וכי]\u0006 ה\u0003תנור מקדש\u0004 את הלחם?! והלא נתינת הלחם על ה\u0003שלחן הוא\u0004 ש\u0003מקדש\u0004 אותו.","ותוהים על הסברו של ר' אבהו בר כהנא: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 ש\u0003בשעת אפייה\u0004 של לחם הפנים \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 דוד? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 עוד באותו ענין \u0003\"ויתן לו הכהן קדש כי לא היה שם לחם כי אם לחם הפנים המוסרים מלפני ה'\u0004 לשום לחם \u0003חום ביום הלקחו\" (שם ז). הרי משמע שדוד קיבל מהלחם שכבר הוסר מן השולחן!\u0004","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הכתוב \"והוא \u0003דרך חל\u0004 אף כי היום יקדש בכלי\" \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003אמר להו\u0004 \u0005[להם,\u0006 לכהנים\u0005]?\u0006 — \u0003הכי קא\u0004 \u0005[כך הם]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליכא\u0004 \u0005[אין כאן]\u0006 \u0003לחם\u0004 חול, \u0003כי אם לחם הפנים המוסרים מלפני ה',\u0004 והרי הם אסורים באכילה למי שאינו כהן.","\u0003אמר להו\u0004 \u0005[להם]\u0006 דוד לכהנים: \u0003לא מיבעיא\u0004 \u0005[לא נצרכה לומר]\u0006 ב\u0003האי\u0004 \u0005[זה]\u0006 הלחם שכבר הוסר מהשולחן, שהוא מותר לי באכילה, \u0003שהרי\u0004 \u0003כיון דנפק ליה\u0004 \u0005[ש\u0006כבר \u0005יצא לו]\u0006 הלחם, לאחר שהוקטרו בזיכי הלבונה \u0003מ\u0004כלל איסור \u0003מעילה,\u0004 מעתה \u0003דרך\u0004 (דבר) \u0003חול הוא\u0004 אצל הכהנים, ומותר אני באכילתו. \u0003אלא אפילו\u0004 בלחם \u0003האיך נמי\u0004 \u0005[האחר גם כן],\u0006 זה ש\u0003היום יקדש בכלי,\u0004 שנסדר היום על שולחן הפנים, מכל מקום \u0003הבו ליה דליכול\u0004 \u0005[תנו לו,\u0006 לי \u0005לאכול],\u0006"],["משום ש\u0003מסוכן הוא\u0004 (אני), ומפני סכנת נפשות מותר להאכיל קדשים \u0003לזר.\u0004 \u0003ור' יהודה ור' שמעון\u0004 לא נחלקו בפירוש הפסוקים אלא \u0003בגמרא פליגי\u0004 \u0005[במסורת\u0006 הם \u0005חלוקים],\u0006 שמסורות שונות היו בידיהם, אם התנור מקדש באפייתו.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 הדבר שהם חולקים על סמך המסורות שבידיהם, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנתנו ש\u0003ר' שמעון אומר: לעולם הוי\u0004 \u0003רגיל לומר\u0004 כי \u0003שתי הלחם ולחם הפנים כשרות בעזרה וכשרות אבית פאגי,\u0004 משמע שאין זה ענין של פירוש המקרא אלא \u0003מסורת. ומסכמים: אכן,\u0004 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שתים עשרה החלות של \u0003חביתי כהן גדול\u0004 (מנחת החביתין) שהוא מביא בכל יום, שש מהן בבוקר ושש מהן בערב — \u0003לישתן ועריכתן ואפייתן\u0004 כולן \u0003בפנים\u0004 העזרה, \u0003ו\u0004כל מלאכותיהן \u0003דוחות את השבת.\u0004 שכן אי אפשר לעשות מלאכות אלה ביום אתמול, שכיון שהתקדשו בכלי — הריהן נפסלות בלינה. אבל \u0003טחינתן\u0004 של החיטים הבאות למנחת החביתין, \u0003ו\u0004כן \u0003הרקדתן\u0004 (ניפויים) \u0003אינו דוחה את השבת,\u0004 לפי שניתן לעשות מלאכות אלה ביום אתמול. שזה ה\u0003כלל\u0004 ש\u0003אמר ר' עקיבא:\u0004 \u0003כל מלאכה שאפשר לעשותה מערב שבת\u0004 — \u0003אינה דוחה את השבת,\u0004 \u0003ו\u0004כל מלאכה \u0003שאי אפשר לה לעשותה מערב שבת\u0004 — הריהי \u0003דוחה את השבת.\u0004","\u0003כל\u0004 מעשיהן של \u0003המנחות\u0004 הנעשות בפנים העזרה (כלישתן ועריכתן ואפייתן של חלות מנחת החביתין) — \u0003יש בהן מעשה\u0004 (הריהם נעשים) ב\u0003כלי\u0004 שרת המקודש ומקדש את הנמצא בתוכו, \u0003בפנים\u0004 העזרה. \u0003ו\u0004אילו כל מעשיהן של המנחות הנעשים מחוץ לעזרה (כלישתם ועריכתם של שתי הלחם ולחם הפנים) — \u0003אין בהן מעשה\u0004 (אינם נעשים) ב\u0003כלי\u0004 \u0003שרת,\u0004 \u0003בחוץ.\u0004","ועוד לגבי תיאור חלות שתי הלחם ולחם הפנים: חלות \u0003שתי הלחם\u0004 — \u0003ארכן\u0004 של כל חלה היה \u0003שבעה טפחים, ורחבן\u0004 היה \u0003ארבעה טפחים. וקרנותיה,\u0004 שהיו מדביקים בצק בכל אחת מזויות, וצורתו כעין קרן — גובהן \u0003היה\u0004 \u0003ארבע אצבעות.\u0004 ואילו הלחמים שהיו ב\u0003לחם הפנים\u0004 — \u0003ארכן\u0004 של כל לחם היה \u0003עשרה טפחים, ורחבן\u0004 — \u0003חמשה טפחים, ו\u0004גובה \u0003קרנותיו\u0004 — \u0003שבע אצבעות.\u0004","\u0003ר' יהודה\u0004 היה \u0003אומר\u0004 סימן כדי \u0003שלא תטעה\u0004 ותשכח את מידות שתי הלחם — \u0003זד\"ד\u0004 (ז' — שבעה טפחים אורך; ד' — ארבעה טפחים רוחב, ויעויין \"גרסות\"; ד' — ארבע אצבעות גובה הקרנות). וכדי שלא תטעה ותשכח את מידות לחם הפנים היה ר' יהודה נותן סימן \u0003יה\"ז\u0004 (י' — עשרה טפחים אורך; ה' — חמישה טפחים רוחב; ז' — שבע אצבעות גובה קרנותיו). \u0003בן זומא אומר:\u0004 נאמר בלחם הפנים \u0003\"ונתת על השלחן לחם פנים לפני תמיד\"\u0004 (שמות כה, ל), ובאה הלשון \u0003\"לחם פנים\"\u0004 להורות: \u0003שיהו לו פנים,\u0004 כלומר, שיהיו ללחם דפנות, שאינו עשוי בעיגול וכיוצא בהן.","ומעתה מתארים את אופן סידור לחם הפנים על השולחן: \u0003השולחן\u0004 עצמו — \u0003ארכו עשרה\u0004 טפחים, שכן נאמר שהשולחן אמתיים ארכו (שמות כה, כג), וסבור ר' יהודה כי אמה של כלי המקדש הריהי בת חמישה טפחים. \u0003ו\u0004\u0003שיעור הטפחים ב\u0004\u0003רחבו\u0004 — \u0003חמשה,\u0004 שכן נאמר שאמה רוחבו (שם). ואילו \u0003לחם הפנים\u0004 — \u0003ארכו עשרה\u0004 טפחים, \u0003ורחבו\u0004 — \u0003חמשה\u0004 טפחים.","ודרך הנחת הלחמים על השולחן היתה באופן ש\u0003נותן\u0004 את \u0003ארכו\u0004 של הלחם \u0003כנגד רחבו של שולחן.\u0004 ונמצא איפוא, שכאשר ניתן הלחם לאורכו (שהוא עשרה טפחים) על רוחבו של השולחן (שהוא חמישה טפחים), היו חמישה טפחים מן הלחם יוצאים אל מחוץ לגבולות השולחן. \u0003ו\u0004מה היה עושה בהם? \u0003כופל\u0004 (מכופף) כלפי מעלה \u0003טפחיים ומחצה מכאן\u0004 מצד אחד של השולחן, \u0003וטפחיים ומחצה מכאן,\u0004 מצידו השני של השולחן. וכך \u0003נמצא\u0004 ש\u0003ארכו\u0004 של הלחם היה \u0003ממלא\u0004 את כל \u0003רחבו של שולחן.\u0004 וכן רוחבו של הלחם (שהיה חמישה טפחים) היה ניתן לאורכו של השולחן (שהיה עשרה טפחים), ותפס איפוא מחצית אורכו של השולחן, ומאחר שניתנו שני סדרים לחמים — נמצאו הלחמים ממלאים אף את מלוא אורכו של השולחן. אלו \u0003דברי ר' יהודה.\u0004","ואילו \u0003ר' מאיר\u0004 חולק עליו ו\u0003אומר: השלחן\u0004 — \u0003ארכו שנים עשר\u0004 טפחים, כשיעור הטפחים בשתי אמות, שלדעתו מידת האמה שבמקדש היתה בת ששה טפחים. \u0003ורחבו\u0004 — \u0003ששה\u0004 טפחים כשיעור הטפחים שבאמה. בעוד ש\u0003לחם הפנים\u0004 — \u0003ארכו עשרה\u0004 טפחים, \u0003ורחבו\u0004 — \u0003חמשה\u0004","\u0003נותן\u0004 את \u0003ארכו\u0004 של הלחם \u0003כנגד רחבו של\u0004 ה\u0003שולחן.\u0004 ונמצא איפוא, שכאשר ניתן הלחם לאורכו (שהוא עשרה טפחים) על רוחבו של השולחן (שהוא ששה טפחים), היו ארבעה טפחים מן הלחם יוצאים אל מחוץ לגבולות השולחן. ומה היה עושה בהם? \u0003כופל\u0004 (מכופף) כלפי מעלה \u0003טפחיים\u0004 (שני טפחים) \u0003מכאן\u0004 מצידו זה של השולחן, \u0003וטפחיים מכאן\u0004 מצידו האחר של השולחן. וכך נמצא מלוא רוחבו של השולחן מתמלא על ידי הלחם. \u0003ו\u0004מאחר ואורכו של השולחן הוא שנים עשר טפחים, לדעת ר' מאיר, כיון שרוחבו של כל לחם הינו רק חמישה טפחים, נמצא שהיו \u0003טפחיים ריוח באמצע\u0004 בין שני הסדרים של לחם הפנים, לאורכו של השולחן. וטעם הדבר: \u0003כדי שתהא הרוח מנשבת בהם\u0004 בין הלחמים לאוורר אותם שלא יתעפשו.","\u0003אבא שאול אומר\u0004 לדעת ר' מאיר: \u0003שם היו נותנין\u0004 את \u0003שני בזיכי\u0004 (כלי) ה\u0003לבונה של לחם הפנים\u0004 (כנאמר בתורה \"ונתת על המערכת לבונה זכה והיתה ללחם לאזכרה אשה לה' \". ויקרא כד, ז). \u0003אמרו לו\u0004 חכמים לאבא שאול: \u0003והרי כבר נאמר \"ונתת על המערכת לבנה זכה\"\u0004 — הרי משמע שהלבונה מונחת על גבי הלחם (\"על המערכת\"), ולא לצד מערכות הלחם! \u0003אמר להם\u0004 אבא שאול בתשובה: ו\u0003הרי\u0004 כיוצא בדבר \u0003כבר נאמר\u0004 בתיאור סדר דגל מחנה אפרים במסעי בני ישראל במדבר \u0003\"ועליו מטה מנשה\"\u0004 (במדבר ב, כ), ושם בוודאי משמעות \"עליו\" — בסמוך לו, אף כאן הביטוי \"על המערכת\" אין משמעו על הלחם ממש, אלא בסמוך לו.","\u0003ו\u0004ממשיכים בתיאור השולחן ואופן סידור לחם הפנים עליו: \u0003ארבעה סניפין\u0004 (לוחות) \u0003של זהב היו שם\u0004 בשולחן, עומדים על הארץ ועולים אל מעל לגובה השולחן, מול מערכות הלחם. והיו הסניפים הללו \u0003מפוצלין מראשיהן,\u0004 מעל לגובה השולחן, על מנת שיינתנו בהם קנים מצד זה לצד זה, \u0003שהיו סומכין בהם\u0004 את הלחמים. \u0003שנים\u0004 סניפים היו עומדים \u0003ל\u0004שני צדדיו של \u0003סדר\u0004 לחמים \u0003זה, ושנים\u0004 סניפים נוספים היו עומדים \u0003ל\u0004שני צדדיו של \u0003סדר זה,\u0004 השני. \u0003ו\u0004היו נתונים בסעיפים הללו \u0003עשרים ושמונה קנים\u0004 שהיו עשויים \u0003כחצי קנה\u0004 (קנה חצוי לאורכו) ו\u0003חלול\u0004 הוא. שהיו \u0003ארבעה עשר\u0004 קנים משמשים \u0003ל\u0004צורכו של \u0003סידור זה,\u0004 \u0003ארבעה עשר\u0004 קנים אחרים \u0003ל\u0004צורכו של \u0003סדר זה.\u0004","ובעניין התקנת הקנים הללו נקבע כי \u0003לא\u0004 מלאכת \u0003סידור\u0004 ה\u0003קנים\u0004 למערכות הלחם החדשות, \u0003ולא\u0004 מלאכת \u0003נטילתם\u0004 ממערכות הלחם הישנות \u0003דוחה את השבת,\u0004 \u0003אלא\u0004 כיצד היה הכהן העוסק בסידור הלחם על השולחן נוהג? היה \u0003נכנס מערב שבת, ושומטו\u0004 את הקנים הללו מבין הלחמים, \u0003ונותנו\u0004 במקום הפנוי (בן שני הטפחים, וכשיטת ר' מאיר) המצוי \u0003לארכו של שלחן.\u0004 ואחר כך בשבת היה מסדר את הלחמים בשתי המערכות, וללא קנים תחתיהם, ובמוצאי שבת היה מניח את הקנים תחתיהם.","ומאחר ונזכרה דרך נתינת הלחמים על השולחן, הוסיפו ואמרו כי \u0003כל הכלים\u0004 (וכגון השולחן) \u0003שהיו במקדש\u0004 היו עומדים באופן זה ש\u0003ארכן\u0004 היה \u0003לארכו של בית\u0004 המקדש, שהוא ממזרח למערב.","שנינו במשנה כי \u0003כל\u0004 מעשיהן של \u0003המנחות\u0004 הנעשות בפנים העזרה (כלישתן ועריכתן ואפייתן של מנחת החביתין) — \u0003יש בהן מעשה\u0004 ב\u0003כלי\u0004 שרת המקדש את הנמצא בתוכו, \u0003מבפנים\u0004 העזרה. \u0003שאלו\u0004 חכמים \u0003את רבי\u0004 יהודה הנשיא: הלכה \u0003זו מנין\u0004 היא, מה מקורה בכתוב? \u0003אמר להם\u0004 בתשובה: \u0003הרי הוא\u0004 הנביא יחזקאל \u0003אומר: \"ויאמר אלי זה המקום אשר יבשלו שם הכהנים את האשם ו\u0004\u0003את החטאת\u0004 \u0003אשר יאפו את המנחה לבלתי הוציא אל החצר\u0004 \u0003החיצונה\u0004 לקדש את העם\" (יחזקאל מו, כ).","ומתוך שהשווה הכתוב את המנחה לקרבנות האשם והחטאת, הרי זה בא להורות: כי דין ה\u0003מנחה\u0004 הריהו \u0003דומיא\u0004 \u0005[בדומה]\u0006 לדין \u0003ה\u0004\u0003אשם ו\u0004ה\u0003חטאת, מה אשם וחטאת\u0004 — \u0003טעונין כלי\u0004 לבישול איבריהם (\"אשר יבשלו\"), ונעשים בפנים העזרה, ואין הם מוצאים אל מחוצה לה (\"לבלתי הוציא אל החצר החיצונה\") לאחר שכבר התקדשו. \u0003אף מנחה נמי\u0004 \u0005[גם כן]\u0006 — \u0003טעונה כלי\u0004 שרת לעשייתה, ומעשיה בפנים העזרה.","שנינו במשנה כי נחלקו ר' יהודה ור' מאיר במדותיו של השולחן, שלדעת ר' יהודה היה \u0003השולחן ארכו\u0004 \u0003עשרה\u0004 טפחים, ולדעת ר' מאיר היה אורכו של השולחן שנים עשר טפחים. ונמצא שלדעת ר' יהודה חמישה טפחים של הלחם היו יוצאים אל מחוץ לרוחב השולחן, ולכך היה כופל שני טפחים ומחצה מכאן ושני טפחים ומחצה מכאן. ואילו לדעת ר' מאיר ארבעה טפחים של הלחם היו יוצאים אל מחוץ לרוחבו של השולחן, ולכן היה כופל שני טפחים מכאן ומכאן.","ובענין זה \u0003אמר ר' יוחנן: לדברי האומר\u0004 ש\u0003טפחיים ומחצה\u0004 היה \u0003כופל\u0004 כלפי מעלה מכל צד (ר' יהודה), והרי שש מערכות לחם היו נתונות על השולחן זו מעל זו — \u0003נמצא\u0004 איפוא שה\u0003שלחן מקדש חמשה עשר טפחים\u0004 (שהם כפולה של שנים ומחצה טפחים לכל סדר וסדר מששת סדרי הלחמים) \u0003למעלה.\u0004 ואילו \u0003לדברי האומר\u0004 כי שני \u0003טפחים\u0004 היה \u0003כופל\u0004 כלפי מעלה מכל צד (ר' מאיר) — \u0003נמצא\u0004 איפוא שה\u0003שלחן מקדש שנים עשר טפחים למעלה.\u0004","ושואלים על כך: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם \u0003קנים\u0004 הנמצאים בין לחם ללחם, עליהם נישאים הלחמים, ונמצא איפוא שסך גובה כל הלחמים היה יותר מחמישה עשר טפחים (לר' יהודה) או שנים עשר טפחים (לר' מאיר)! ומשיבים: אין הקנים מוסיפים לגובה הלחמים, שכן את ה\u0003קנים שקועי משקע להו\u0004 \u0005[משקע אותם]\u0006 בתוך הלחמים. שנחרצו בבצק הלחם חריצים, וכך נאפו, על מנת שינתנו בתוכם הקנים.","ומקשים על כך: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שעושים \u0005את הקנים הללו? הלא הוא\u0006 \u0003משום\u0004 מניעת \u0003איעפושי\u0004 \u0005[עיפוש]\u0006 ה\u0003לחם,\u0004 שיוצרים הקנים ריוח בין לחם ללחם, לצורך מעבר אויר ביניהם. ואם כך שהקנים ניתנים בתוך הלחם עצמו, ואין הוא נישא עליהם, \u0003סוף סוף קא מיעפש\u0004 \u0005[הוא מתעפש]\u0006 ה\u0003לחם!\u0004 ומשיבים: \u0003דמגבה ליה פורתא\u0004 \u0005[שמגביה אותו,\u0006 את הלחם \u0005במקצת]\u0006 מעל הקנים, שאכן לא היו הקנים משוקעים לגמרי בתוך הלחם, אלא נושאים את הלחם על גביהם בגובה מועט, שנועד שלא יגעו הלחמים זה בזה.","ושואלים: \u0003והאיכא ההוא פורתא\u0004 \u0005[והרי יש אותו\u0006 רווח \u0005קטן],\u0006 והרי זה מצטרף לכלל גובה שהוא יותר מחמישה עשר טפחים (לר' יהודה) המתקדש על ידי השולחן, או שנים עשר טפחים (לר' מאיר)! ומשיבים: \u0003כיון דלא הוי\u0004 \u0005[שלא היה]\u0006 השיעור המצטבר של גובה הקנים בשיעור כדי \u0003טפח\u0004 שלם — \u0003לא חשיב ליה\u0004 \u0005[לא חישב\u0006 ר' יוחנן \u0005אותו\u0006 בכלל הגובה המתקדש\u0005].\u0006","ושואלים עוד: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם ה\u0003בזיכין,\u0004 המונחים למעלה מהלחם, ואף הם מוסיפים לגובה המצטבר של הדברים המתקדשים על ידי השולחן (שהרי אף הלבונה שבבזיכים מתקדשת על ידי השולחן)! ומשיבים: \u0003בגוויה\u0004 \u0005[בתוך]\u0006 ה\u0003לחם הוו יתבי\u0004 \u0005[היו ישובים,\u0006 מונחים הבזיכים\u0005],\u0006 \u0003ולבהדי\u0004 \u0005[וביחד]\u0006 עם ה\u0003לחם הוו קיימי\u0004 \u0005[היו עומדים],\u0006 ולא נוסף על ידם כל גובה. ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם \u0003את\u0004 \u0003קרנות\u0004 לחם הפנים (שגובהן היה שבע אצבעות), שהיו בולטות החוצה, ומוסיפות הן לגובה המצטבר מעל השולחן! ומשיבים: את ה\u0003קרנות לגוויה\u0004 \u0005[לתוך]\u0006 ה\u0003לחם כייף להו\u0004 \u0005[היה כופף אותן],\u0006 \u0003ו\u0004ה\u0003לחם עלייהו\u0004 \u0005[עליהן]\u0006 \u0003נח ליה\u0004 \u0005[לו],\u0006 ולכך לא נוסף כל גובה בגלל הקרנות\u0005.\u0006"],["ומקשים עוד על דברי ר' יוחנן: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם את \u0003מסגרתו\u0004 של השולחן, שגובהה טפח (כנאמר במעשה השולחן \"ועשית לו מסגרת טופח סביב\". שמות כה, כה), ומעליה היה מסדר את מערכות הלחם, ואם כן נמצא שהשולחן מקדש את הנמצא מעליו בגובה של טפח נוסף!","ומשיבים: דברי ר' יוחנן אלה הריהם \u0003כ\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003מסגרתו\u0004 של שולחן הפנים לא היתה מעל השולחן, אלא \u0003למטה,\u0004 תחת טבלת השולחן, \u0003היתה\u0004 המסגרת. ולא הוסיפה המסגרת כל גובה לדברים המתקדשים על ידי השולחן. \u0003ו\u0004מוסיפים כי אף \u0003ל\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003מסגרתו\u0004 של השולחן \u0003למעלה היתה\u0004 \u0003—\u0004 לא היתה המסגרת מוסיפה גובה לשולחן שכן לא היתה עומדת ישר, אלא \u0003פרקודי הוה מפרקדא\u0004 \u0005[פרקדן,\u0006 משופעת ונוטה לאחוריה\u0005],\u0006 \u0003ו\u0004אילו ה\u0003לחם בגויה\u0004 \u0005[בתוך]\u0006 ה\u0003שלחן הוה יתיב\u0004 \u0005[היה יושב,\u0006 מונח\u0005].\u0006","ומסבירים מהן אותן שתי דעות באשר למקומה של המסגרת בשולחן, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0003]:\u0004 \u0003ר' יוסי אומר:\u0004 \u0003לא היה שם\u0004 בשולחן \u0003כלל\u0004 \u0003סניפין,\u0004 שלא נזקקו לצורך העמדת הלחם לסניפים, \u0003אלא מסגרתו של\u0004 ה\u0003שלחן\u0004 היא שהיתה \u0003מעמדת את הלחם.\u0004 הרי איפוא דעת ר' יוסי שמסגרת השולחן היתה למעלה, והלחם ניתן עליה. \u0003אמרו לו\u0004 חכמים: אין כן הדבר, אלא סניפים היו בשולחן, ולא שימשה מסגרתו של השולחן להעמדת הלחמים עליה, שכן \u0003מסגרתו למטה\u0004 ממנו \u0003היתה.\u0004","למעלה שנינו מחלוקת ר' יוסי וחכמים בברייתא בשאלה היכן היתה נתונה מסגרתו של השולחן. ובענין זה עוד \u0003אמר ר' יוחנן:\u0004 כלל הוא בדיני קבלת טומאה כי כלי עץ שאין להם בית קיבול (\"פשוטי כלי עץ\") אינם מקבלים טומאה. ואולם למדנו (כמובא להלן) כי שולחן הפנים, אף שהיה עשוי מעץ הריהו מקבל טומאה. ומעתה נאמר, כי \u0003לדברי\u0004 התנא \u0003האומר\u0004 כי \u0003מסגרתו\u0004 של השולחן \u0003למטה היתה\u0004 (חכמים) ואין חלקו העליון של השולחן ראוי לשמש כבית קיבול, אפשר ללמוד מכאן בדין \u0003טבלא\u0004 (משטח עץ רחב וישר) \u0003המתהפכת,\u0004 שניתן להשתמש בה משני צידה, שהיא \u0003טמאה\u0004 (ראויה לקבל טומאה). שאפשרות השימוש בצד האחר, מחשיב אותה כמי שיש לה בית קיבול.","אבל \u0003לדברי ה\u0004תנא ה\u0003אומר\u0004 כי \u0003מסגרתו\u0004 של השולחן \u0003למעלה היתה\u0004 (ר' יוסי) ובית קיבול היה לשולחן, עדיין דין \u0003טבלא המתהפכת\u0004 שאין לה בית קיבול לענין קבלת טומאה \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך.\u0004","ודנים בדברי ר' יוחנן: \u0003מכלל\u0004 דבריו שומעים אנו כי \u0003שלחן\u0004 הפנים \u0003בר קבולי\u0004 \u0005[בן קיבול,\u0006 ראוי לקבל\u0005]\u0006 \u0003טומאה הוא?\u0004 ואולם יש לשאול, שהרי \u0003כלי עץ העשוי לנחת\u0004 (להיות מונח במקום אחד, שאינו מיטלטל ממקום למקום) \u0003הוא,\u0004 \u0003ו\u0004כלל הוא \u0003ש\u0004\u0003כל כלי עץ העשוי לנחת\u0004 \u0003—\u0004 \u0003אין מקבל טומאה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הלכה זו? שכן נאמר בכלים הראויים לקבל טומאה (במגע נבלת שרץ המטמא) \"וכל אשר יפול עליו מהם במותם יטמא מכל כלי עץ או בגד או עור או שק כל כלי אשר ייעשה מלאכה בהם...\" (ויקרא יא, לב), ומכאן למדנו שכדי שכלי יהא ראוי לקבל טומאה \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שק\u0004 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה. \u0003מה שק\u0004 הריהו דבר ה\u0003מטלטל\u0004 ממקום למקום הן כשהוא \u0003מלא\u0004 בדברים הנמצאים בתוכו, \u0003ו\u0004הן כשהוא \u0003ריקן\u0004 \u0003—\u0004 \u0003אף כל\u0004 דבר כדי שיהא ראוי לקבל טומאה צריך שיהיה \u0003מטלטל\u0004 הן כשהוא \u0003מלא ו\u0004הן כשהוא \u0003ריקן.\u0004 ואין בכלל זה כלי עץ העומד במקום אחד, ואינו מיטלטל, וכשולחן הפנים!","ומשיבים: \u0003שלחן\u0004 הפנים \u0003נמי\u0004 \u0005[גם כן]\u0006 הריהו \u0003מטלטל\u0004 כשהוא \u0003מלא ו\u0004כשהוא \u0003ריקן,\u0004 ו\u0003כ\u0004דברי \u0003ריש לקיש.\u0004 שכך \u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מה\u0006 מלמדנו זה \u0005שנאמר]\u0006 בלחם הניתן על השולחן הפנים \"ושמת אותם שתים מערכות שש המערכת \u0003על השלחן\u0004 \u0003הטהור\u0004 לפני ה' \" (שם כד, ו)? שהרי מתוך שהדגיש הכתוב כי הרי זה \"השלחן ה\u0003טהור\"\u0004 — \u0003מכלל דאיכא\u0004 \u0005[מכאן\u0006 נסיק \u0005שיש]\u0006 אפשרות גם שיהיה השולחן \u0003טמא.\u0004 ואולם על כך יש לשאול, כיצד הוא יכול לקבל טומאה והלא אינו מיטלטל!","\u0003אלא, מלמד ש\u0004היו הכהנים \u0003מ\u0004\u0003גביהין אותו\u0004 את השולחן ממקומו, \u0003ל\u0004צורכם של \u0003עולי\u0004 ה\u0003רגלים\u0004 הבאים למקדש, \u0003ומראין בו\u0004 מרחוק את ה\u0003לחם\u0004 הנתון עליו, \u0003ואומרים להם: ראו\u0004 כמה גדולה היא \u0003חיבתכם לפני המקום.\u0004","ומה היה בשולחן שיש בו להראות חיבתם לפני המקום, \u0003כדברי ר' יהושע בן לוי,\u0004 שכך \u0003אמר ר' יהושע בן לוי: נס גדול נעשה בלחם הפנים,\u0004 שהיה הלחם טרי וחם בשעת \u0003סילוקו\u0004 מהשולחן ביום השבת, כדרך שהיה טרי וחם \u0003כ\u0004שעת \u0003סידורו\u0004 בשבת \u0003שעברה.\u0004 \u0003ש\u0004כן \u0003נ\u0004 \u0003אמר\u0004 בלחם הפנים שהוסר מהשולחן, שניתן לדוד בשעה שברח מפני שאול \"...לחם הפנים המוסרים מלפני ה' \u0003לשום לחם חם ביום הלקחו\"\u0004 (שמואל א כא, ז). ומאחר והיה שולחן הפנים מוגבה כדי להראותו לעם הרי שהיה מיטלטל, ולכך הריהו ראוי לקבל טומאה.","ושואלים: ולשם מה נצרכים אנו להוכיח כי השולחן היה מיטלטל, \u0003ותיפוק לי\u0004 \u0005[ושיצא,\u0006 ותילמד \u0005לו]\u0006 שהוא ראוי לקבל טומאה, \u0003משום ציפוי\u0004 הזהב שהיה לשולחן, שבשלו הוא נחשב ככלי מתכת, הראוי לקבל טומאה אף שאינו מיטלטל ממקום למקום. שהרי \u0003מי לא תנן\u0004 \u0005[האם לא שנינו]\u0006 במשנה במסכת כלים כי \u0003השלחן והדולבקי\u0004 (שולחן קטן עליו עורכים את דברי המאכל והשתיה קודם הגשתם לאוכלים על שולחן הסעודה) \u0003שנפחתו\u0004 (נחסר חלק מהם) \u0003או שחיפן\u0004 (ציפה אותם) \u0003ב\u0004משטח של \u0003שייש\u0004 שהוא ציפוי אבן (וכלי אבנים אינם מקבלים טומאה), \u0003ו\u0004אולם \u0003שייר בהן מקום\u0004 שאותו לא ציפה באבן שיש, ויש באותו מקום שיעור כדי \u0003הנחת כוסות\u0004 השתייה — הרי הם עדיין \u0003טמאין\u0004 (ראויים לקבל טומאה). \u0003ר' יהודה אומר:\u0004 אין די בשיור מקום הנחת כוסות כדי שיהיו השולחן והדולבקי ראויים לקבל טומאה, אלא צריך שישייר בהם \u0003מקום\u0004 שיש בו כדי \u0003הנחת חתיכות\u0004 מאכל (לחם ובשר).","ונדייק מכאן: אם \u0003שייר\u0004 בשולחן ודולבקי מקום ללא ציפוי השיש — \u0003אין\u0004 \u0005[כן],\u0006 עדיין ראויים הם לקבל טומאה, ואם \u0003לא שייר\u0004 מקום ללא ציפוי שיש — הריהם \u0003לא\u0004 מקבלים טומאה. ומכאן נלמד כי איננו דנים את השולחן לפי החומר שהוא עשוי בו, אלא לפי הציפוי. ומעתה, אף שולחן הפנים, בהיותו מצופה זהב, הריהו ראוי לקבל טומאה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין להשוות בין ציפוי שולחן הפנים לבין ציפוי השיש על השולחן והדולבקי, שכן \u0003כאן\u0004 בשולחן ודולבקי מדובר \u0003בציפוי עומד\u0004 (קבוע), שקיבעו במסמרים את ציפוי השיש לשולחן ולדולבקי, ולכך ביטל הציפוי את דינם הקודם, ומעתה נחשבים הם לכלי אבנים. ואילו \u0003כאן\u0004 בשולחן הפנים מדובר \u0003בציפוי\u0004 זהב \u0003שאינו עומד\u0004 (מקובע במסמרים), ולכך אין השולחן נחשב בגלל ציפוי זה ככלי מתכת. \u0003ו\u0004אולם על כך יש להקשות, שכן \u0003הא בעא מיניה\u0004 \u0005[הרי שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן\u0004 בבירורה של משנה זו שבמסכת כלים, האם היא מדברת דווקא \u0003בציפוי עומד או\u0004 אף \u0003בציפוי שאינו עומד?\u0004 וכן האם מדובר בה דווקא \u0003ב\u0004מקרה \u0003שחיפה\u0004 בשיש אף \u0003את\u0004"],["ה\u0003לבזבזין\u0004 (הדפנות של טבלת השולחן והדולבקי), שרק אז ציפוי השיש מחשיב אותם ככלי אבנים, ואין הם עוד ראוים לקבל טומאה. \u0003או\u0004 שמא מדובר במשנה זו אף \u0003בשלא חיפה את\u0004 ה\u0003לבזבזין\u0004 של השולחן והדולבקי. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש בפתרון שאלותיו אלה, כי \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה זה \u0003ציפוי עומד, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היה \u0003ציפוי שאינו עומד,\u0004 וכמו כן \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם \u0003חיפה את\u0004 ה\u0003לבזבזין, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם \u0003לא חיפה\u0004 את ה\u0003לבזבזין,\u0004 בכל מקרה הריהם נחשבים מעתה ככלי אבנים. הרי שאין להעמיד את המשנה דווקא בציפוי עומד. ומעתה חוזרת השאלה מדוע נזקקים אנו להסביר ששולחן הפנים מקבל טומאה משום שהוא כלי עץ המיטלטל, \u0003והרי אף אם איננו מיטלטל, הריהו ראוי לקבל טומאה משום ציפוי הזהב שעליו!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בתשובה לשאלה זו, כי ציפוי הזהב אינו מבטל את שם כלי העץ של שולחן הפנים, משום ש\u0003עצי שיטים\u0004 מהם נעשה השולחן הריהם \u0003חשיבי\u0004 \u0005[חשובים],\u0006 \u0003ו\u0004לכך הם \u0003לא בטלי\u0004 \u0005[לא בטלים]\u0006 אצל ציפוי הזהב שעליהם — הסבר זה אכן \u0003הניחא\u0004 \u0005[הריהו נוח]\u0006 \u0003ל\u0004שיטת \u0003ריש לקיש\u0004 בפירוש משנה זו שבמסכת כלים, ש\u0003אמר\u0004 כי \u0003לא שנו\u0004 במשנה זו שציפוי השיש מבטל את שם כלי העץ של השולחן והדולבקי \u0003אלא בכלי אכסלגוס\u0004 העשויים מעץ שאינו יקר כל כך \u0003הבאים ממדינת הים,\u0004 שאף שהם חשובים אינם חשובים דיים, ולכך בטלים הם לגבי ציפויים. \u0003אבל כלי מסמס,\u0004 שהעץ ממנו הם עשויים יקר מאוד, הריהם \u0003חשיבי\u0004 \u0005[חשובים]\u0006 \u0003ו\u0004לכך \u0003לא בטלי\u0004 \u0005[לא בטלים]\u0006 לגבי הציפוי, \u0003שפיר\u0004 \u0005[יפה]\u0006 היא הבחנה זו אף ביחס לשולחן הפנים, שהיה עשוי מעצי שיטים שהם עצים יקרים, ולכן אינו בטל אצל ציפוי הזהב שעליו. \u0003אלא ל\u0004דעת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי \u0003כלי מסמס\u0004 היקרים \u0003נמי בטלי\u0004 \u0005[גם כן בטלים]\u0006 לגבי הציפוי, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא \u0003שולחן\u0004 הפנים, \u0003דרחמנא קרייה\u0004 \u0005[ש\u0006כן \u0005התורה קראה אותו]\u0006 \u0003\"עץ\", שנאמר \"המזבח עץ שלוש אמות גבה ארכו שתים אמות\u0004 \u0003ומקצעותיו לו וארכו וקירתיו עץ וידבר אלי זה השלחן אשר לפני ה' \"\u0004(יחזקאל מא, כב). משמע שהשולחן נקרא בכתוב \"עץ\", אף שאין העץ שבו נראה, ולכך הריהו נדון כשאר כלי עץ לענין קבלת טומאה, ואלמלא היו מטלטלים אותו לצורך עולי רגלים — לא היה ראוי לקבל טומאה.","כיון שהוזכר פסוק זה מבארים דבר תמוה: \u0003פתח\u0004 הכתוב \u0003ב\u0004תיאור ה\u0003מ\u0004\u0003זבח\u0004 (\"המזבח עץ שלש אמות גבוה...\"), \u0003וסיים בשולחן\u0004 (\"וידבר אלי זה השולחן...\"). ובענין זה \u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שכך יש לדרוש את איזכור השולחן בצד המזבח: \u0003בזמן שבית המקדש קיים\u0004 — ה\u0003מזבח\u0004 הוא ש\u0003מכפר על\u0004 חטאיו של \u0003ה\u0004\u0003אדם,\u0004 בקרבנות הקרבים עליו. \u0003ועכשיו, שאין בית המקדש קיים\u0004 — \u0003שולחנו של אדם מכפר עליו,\u0004 אם הוא משתמש בשולחנו כדי להאכיל את העניים והנזקקים.","שנינו במשנתנו כי \u0003ארבע סניפין של זהב היו שם\u0004 בשולחן הפנים, ובפיצוליהם של הסניפים הללו היו נתונים עשרים ושמונה קנים. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין\u0006 לנו כל \u0005הדברים הללו]?\u0006 \u0003אמר רב קטינא:\u0004 שכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בתיאור שולחן הפנים, \u0003\"ועשית קערתיו וכפתיו וקשותיו\u0004 \u0003ומנקיתיו\u0004 אשר יוסך בהן זהב טהור תעשה אותם\" (שמות כה, כט),","\u0003ופירוש הדברים:\u0004 \u0003\"קערתיו\"\u0004 — \u0003אלו\u0004 הן ה\u0003דפוסין\u0004 (תבניות) שבהם לשים ואופים ומניחים את החלות האפויות, וכדרך שהתבאר למעלה (צד,א). \u0003\"כפתיו\"\u0004 — \u0003אלו\u0004 הן ה\u0003בזיכין\u0004 (כפות) שבהם מניחים את הלבונה הניתנת על לחם הפנים. \u0003\"קשותיו\"\u0004 — \u0003אלו\u0004 הן ארבעת ה\u0003סניפין\u0004 של זהב, שנים לצידיו (או על גביו) ושנים על גביו, לצידי שתי מערכות הלחם שמצידי השולחן. \u0003\"ומנקיתיו\"\u0004 — \u0003אלו\u0004 עשרים ושמונה ה\u0003קנים\u0004 הניתנים על פיצוליהם של הסניפים, ונושאים הם את הלחמים זה מעל זה. \u0003\"אשר יסך בהן\"\u0004 — \u0003שמסככין בהן\u0004 באותם קנים \u0003את הלחם\u0004 שמתחתם.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על דרשת כתובים זו, שממנה עולה כי דין תורה הוא שיהיו קנים בשולחן הפנים, ממה ששנינו במשנתנו \u0003כי\u0004 \u0003לא סידור הקנים\u0004 בלחם הפנים החדש הניתן עתה, \u0003ולא נטילתן\u0004 של הקנים מלחם הפנים הישן שסולק מהשולחן הריהן \u0003דוחות את השבת,\u0004 שאין מלאכות אלה נעשות בשבת. \u0003ו\u0004אולם \u0003אי סלקא\u0004 \u0005[אם עולה]\u0006 ב\u0003דעתך\u0004 לומר כי דין הקנים שבשולחן הפנים הריהו \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין\u0004 מלאכות אלה \u0003דוחות את השבת?\u0004","לאחר דבריו אלה, \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: לאו מילתא\u0004 \u0005[לא דבר]\u0006 של ממש \u0003הוא\u0004 זה \u0003דאמרי\u0004 \u0005[\u0006\u0003שאמרתי],\u0004 שאין זו קושיה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 ש\u0003כלל אמר ר' עקיבא\u0004 בדין המלאכה הדוחה את השבת במקדש: \u0003כל מלאכה שאפשר לה לעשותה\u0004 אף \u0003מערב שבת,\u0004 ואין היא נצרכת להיעשות דווקא בשבת — \u0003אינו דוחה את השבת, והני נמי\u0004 \u0005[ואלה\u0006 המלאכות, סידור וסילוק הקנים בשולחן, \u0005גם כן]\u0006 \u0003אפשר דלא דחי\u0004 \u0005[שאינו דוחה]\u0006 \u0003שבת עלייהו\u0004 \u0005[עליהם],\u0006 שהרי יכולות הן להיעשות אף שלא בשבת. שנטילתם מן הלחם הישן יכולה להיעשות בערב שבת, וסידורם לצורך הלחם החדש יכול להיעשות גם לאחר השבת.","שהרי עיקר \u0003טעמא\u0004 \u0005[הטעם]\u0006 לנתינת הקנים תחת הלחמים \u0003מאי\u0004 \u0005[מהו]?\u0006 שיווצר רווח בין לחם ללחם, כדי ש\u0003לא\u0004 \u0003ליעפש\u0004 \u0005[לא יתעפש]\u0006 ה\u0003לחם,\u0004 הנמצא בצפיפות זה מתחת לזה, ואולם \u0003בכי האי שיעורא\u0004 \u0005[בכזה שיעור\u0006 זמן קצר\u0005]\u0006 משעת \u0003עריכת הלחם החדש בשבת ועד לסידורו על הקנים לאחר השבת\u0004 — \u0003לא מיעפש\u0004 \u0005[לא מתעפש]\u0006 הלחם.","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]\u0006 בתיאור \u0005סילוק וסידור הקנים בשולחן הפנים,\u0006 \u0003כיצד\u0004 הכהן נוהג בהם? \u0003נכנס\u0004 הכהן להיכל \u0003מערב שבת ושמטן\u0004 את הקנים מתחת ללחמים המונחים עליהם, \u0003ומניחן\u0004 במקום הפנוי שבשולחן \u0003לארכו של שולחן\u0004 (יעויין לעיל מנחות צו,א). \u0003ו\u0004ב\u0003מוצאי שבת נכנס\u0004 שוב, ו\u0003מגביה\u0004 את \u0003ראשיה\u0004 (קצותיה) \u0003של\u0004 ה\u0003חלה\u0004 האחת שבמערכה זו של הלחמים, \u0003ומכניס קנה תחתיה, וחוזר ומגביה ראשיה של\u0004 ה\u0003חלה\u0004 השניה שבמערכה זו, \u0003ומכניס קנה תחתיה.\u0004 ומוסיפה הברייתא ומתארת עוד את הקנים שבשולחן הפנים.","\u0003ארבעה\u0004 ה\u0003חלות\u0004 האמצעיות מבין השש המונחות בכל מערכת — \u0003צריכות\u0004 כל אחת \u0003שלשה שלשה קנים.\u0004 והרי אלה איפוא בסך הכל שנים עשר קנים. החלה \u0003העליונה\u0004 — \u0003אינה צריכה אלא שנים\u0004 קנים, \u0003לפי שאין עליה משאוי\u0004 (משא) של חלה הניתנת עליה. והרי אלה איפוא בסך הכל ארבעה עשר קנים. והחלה \u0003התחתונה\u0004 ביותר בכל מערכת \u0003אינה צריכה\u0004 קנים \u0003כל עיקר, לפי שמונחת על טהרו\u0004 (גופו) \u0003של שולחן.\u0004 ומעתה נמצאו עשרים ושמונה קנים, לשתי מערכות הלחם.","\u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה במסכת כלים\u0005]\u0006 עוד במידות שנהגו במקדש, \u0003ר' מאיר אומר: כל\u0004 ה\u0003אמות שהיו במקדש,\u0004 כלומר, כל מידות האמה האמורות במקדש וכליו, כולן \u0003בינוניות,\u0004 כלומר, אמות בנות שישה טפחים, \u0003חוץ ממזבח הזהב\u0004 (שהיה אמה על אמה) \u0003ו\u0004כל \u0003הקרן\u0004 מקרנות מזבח הנחושת (שהיתה אמה על אמה בגובה אמה), \u0003והסובב\u0004 (במזבח הנחושת, בגובה חמש אמות, שרוחבו אמה), \u0003והיסוד\u0004 שבמזבח (שגובהו אמה ורחבו אמה) — שכל אלה היו באמה של חמישה טפחים. ואילו \u0003ר' יהודה אומר: אמת בנין\u0004 (האמה שעל פיה נבנו בנייני המקדש), היתה של \u0003ששה טפחים, ו\u0004אולם האמה \u0003של\u0004 ה\u0003כלים\u0004 שבמקדש, כגון השולחן והמנורה ומזבח הזהב, היתה של \u0003חמשה\u0004 טפחים.","ובהסבר מחלוקתם \u0003אמר ר' יוחנן: ושניהם\u0004 מתוך \u0003מקרא אחד דרשו\u0004 את שיטותיהם, שכן נאמר: \u0003\"ואלה מדות המזבח באמות אמה אמה וטפח\u0004"],["\u0003וחיק האמה ואמה רחב וגבולה אל שפתה סביב זרת האחד וזה גב המזבח\"\u0004 (יחזקאל מג, יג). ומסבירים את חלקו הראשון של הנאמר בכתוב זה במזבח החיצון: \u0003\"חיק האמה\"\u0004 — \u0003זה\u0004 הוא \u0003יסוד\u0004 המזבח, הנמצא בתחתיתו של המזבח, \u0003שרוחבו אמה וגובהו אמה;\u0004 \u0003\"אמה רחב\"\u0004 — \u0003זה\u0004 הוא ה\u0003סובב\u0004 את המזבח, הנמצא בגובה חמש אמות של המזבח, שהיה רוחבו אמה; \u0003\"וגבולה אל שפתה סביב זרת האחד\"\u0004 — \u0003אלו\u0004 הן \u0003קרנות\u0004 הנמצאות בגובה המזבח, שהיה גובהן ורוחבן אמה. ואת חלקו השני של הכתוב אין מפרשים במזבח הנחושת, אלא מה שנאמר \u0003\"זה גב המזבח\"\u0004 — הרי \u0003זה מזבח הזהב,\u0004 שהיה אורכו \u0003ורוחבו אמה. שכל האמות הללו היו של חמישה טפחים. ובכך נחלקו ר' מאיר ור' יהודה, ש\u0004","\u0003ר' מאיר סבר\u0004 כי ההדגשה בכתוב \u0003\"זהו\"\u0004 (\"זה גב המזבח\") באה להורות כי דווקא מזבח הזהב הוא הנמדד \u0003באמה בת חמשה\u0004 טפחים, ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003כל אמות\u0004 ה\u0003כלים\u0004 האחרים שבמקדש נמדדות \u0003באמה בת שש\u0004 טפחים. \u0003ו\u0004אילו \u0003ר' יהודה סבר\u0004 כי הכתוב \"זה גב המזבח\" בא להורות כי \u0003כזה\u0004 (באופן זה) \u0003יהו\u0004 נמדדות גם שאר \u0003כל אמות\u0004 ה\u0003כלים\u0004 שבמקדש.","ועתה נפנים לבירורו של האמור בפסוק זה. \u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתנו]\u0006 לומר בפירוש הדברים כי כוונתם לענין מדידת גובהם של חלקי המזבח, ש\u0003מיסוד\u0004 המזבח \u0003ועד\u0004 ה\u0003סובב\u0004 מודדים \u0003באמה בת חמשה\u0004 טפחים \u0003בגובה\u0004 המזבח. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 הכתוב \u0003\"חיק האמה ואמה רחב\"? הכי קא אמר\u0004 \u0005[כך הוא\u0006 \u0003אומר]:\u0004 \u0003מחיק האמה\u0004 (=מיסוד המזבח) \u0003ועד\u0004 אמה \u0003רוחב\u0004 (=הסובב) — נמדדים \u0003באמה בת חמשה\u0004 טפחים.","ואולם על כך יש להקשות: שהרי \u0003גובה המזבח\u0004 כולו \u0003כמה הוי\u0004 \u0005[הוא]?\u0006 \u0003עשר אמות,\u0004 ומעתה, לאופן זה שנאמר עתה, נמצא כי \u0003שית\u0004 \u0005[שש]\u0006 אמות מהן (מרצפת העזרה, מקום המזבח, ועד לכניסת הסובב) הריהן באמות שהן \u0003בני חמשה חמשה\u0004 טפחים, ובכללן יש איפוא שלושים טפחים. \u0003ו\u0004אילו \u0003ארבעי\u0004 \u0005[ארבע]\u0006 האמות שמעליהן בגובה המזבח, מכניסת הסובב ועד שפת הקרנות (שלוש אמות למזבח, וגובה אמה נוסף של הקרנות) הריהן \u0003בני שיתא שיתא\u0004 \u0005[ששה ששה]\u0006 טפחים. והרי זה עשרים וארבעה טפחים.","ולפי זה נמצא שה\u0003מזבח כמה\u0004 טפחים \u0003הוי\u0004 \u0005[הוא]\u0006 גובהו? \u0003חמשין\u0004 \u0005[חמישים]\u0006 \u0003וארבעה\u0004 טפחים. ומעתה, גובה \u0003פלגיה\u0004 \u0005[חציו]\u0006 של ה\u0003מזבח כמה\u0004 טפחים \u0003הוי\u0004 \u0005[הוא]?\u0006 \u0003עשרים ושבעה\u0004 טפחים. ושיעור הגובה \u0003מ\u0004שפת \u0003ק\u0004 \u0003רנות\u0004 המזבח \u0003ועד\u0004 ה\u0003סובב כמה\u0004 טפחים \u0003הוי\u0004 \u0005[הוא]?\u0006 \u0003עשרים וארבעה\u0004 (כשיעור ארבע אמות שכל אחת מהן היא בת ששה טפחים). ומעתה, \u0003כמה\u0004 טפחים \u0003בציר\u0004 \u0005[חסר]\u0006 לעשרים וארבעה הטפחים הללו כדי להגיע \u0003לפלגיה\u0004 \u0005[לחציו]\u0006 של ה\u0003מזבח? תלתא\u0004 \u0005[שלושה]\u0006 טפחים. \u0003ו\u0004אולם על כך יש להקשות, שהרי \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 כי \u0003חוט של סקרא\u0004 (צבע אדום) היה \u0003חוגרו\u0004 (משורטט) \u0003באמצע\u0004 המזבח, \u0003כדי להבדיל בין דמים העליונים\u0004 (דמי הקרבנות שדינם להינתן על חלקו העליון של קיר המזבח) \u0003לדמים התחתונים\u0004 (דמי הקרבנות שדינם להינתן על חלקו התחתון של קיר המזבח).","\u0003אלא\u0004 מעתה שאמרנו כי בין הסובב לבין חוט הסיקרא (הנתון בחצי המזבח) יש מרחק של שלושה טפחים, \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 דרך הקרבתה של \u0003עולת העוף\u0004 (שהיא מן הקרבנות שדמיהם ניתנים בחלקו העליון של קיר המזבח): \u0003היה\u0004 הכהן \u0003עולה בכבש\u0004 המזבח (הנמצא בדרום המזבח) אל המזבח, \u0003ו\u0004כאשר הגיע לסובב הוא \u0003פנה\u0004 ימינה \u0003לסובב, ו\u0004שם היה מהלך לכיוון מזרח, וכך הוא \u0003בא לו\u0004 בתחילה \u0003לקרן דרומית מזרחית,\u0004 שהוא מקום מליקתה של עולת העוף. \u0003ומולק\u0004 (חותך בצפורן שבאגודל ידו הימנית) \u0003את ראשה\u0004 של עולת העוף, \u0003ממול ערפה\u0004 (מאחורי צוארה), \u0003ומבדיל\u0004 את הראש מן הגוף. \u0003ומוצה את דמה על קיר המזבח,\u0004 שמצמיד את בית מליקתה ולוחץ באופן שיימצה מדמה על המזבח. \u0003ואם\u0004 הכהן \u0003עשאה\u0004 את מיצוי דם עולת העוף שלא במקומו הראוי, אלא \u0003למטה מ\u0004מקום עמידת \u0003רגליו\u0004 של הניצבות בסובב, \u0003אפילו אמה אחת\u0004 — עולת העוף \u0003כשירה,\u0004 שכן ניתנו דמיה במקום שהוא עדיין למעלה בחציו העליון של המזבח.","ואולם לשיטתך שבין הסובב לחוט הסיקרא מרחק של שלושה טפחים בלבד, זה הממצה את דמי עולת העוף במרחק של אמה בת חמישה טפחים מתחת לסובב — \u0003הא קא יהיב\u0004 \u0005[הרי הוא נותן]\u0006 את הדמים של \u0003ה\u0004\u0003עליונה\u0004 (קרבנות שדין דמם להינתן בחלקו העליון של המזבח) \u0003למטה משני טפחים\u0004 (מתחת לחוט הסיקרא), והרי זה בחלקו התחתון של המזבח!","\u0003אלא\u0004 מכאן שיש לחזור מהבנת הכתוב כמתייחס לגובה המזבח, ויש לפרשו כמדבר ברוחב הכניסות של חלקי המזבח. וכך יתבאר הכתוב: \u0003\"חיק האמה\"\u0004 — זה רוחב ה\u0003כניסה\u0004 של היסוד פנימה אל תחום המזבח, שהיא רחבה חמישה טפחים. \u0003\"אמה רחב\"\u0004 — זה רוחב ה\u0003כניסה\u0004 של הסובב, שאף הוא חמישה טפחים. \u0003\"גבולה אל שפתה סביב\u0004 זרת האחד\" — זה רוחב ה\u0003כניסה\u0004 של הקרנות, שאף הן של אמה בת חמישה טפחים.","ומעתה יובן הדין האמור בעולת העוף, שגובה ה\u0003מזבח\u0004 הוא עשר אמות (שכל אחת היא בת ששה טפחים) \u0003כמה\u0004 טפחים \u0003הוה ליה\u0004 \u0005[יש לו]?\u0006 \u0003שיתין\u0004 \u0005[שישים].\u0006 ולפי זה, \u0003פלגיה\u0004 \u0005[חציו]\u0006 של גובה ה\u0003מזבח כמה\u0004 טפחים \u0003הוי\u0004 \u0005[הריהו]?\u0006 \u0003תלתין\u0004 \u0005[שלושים].\u0006 הגובה \u0003מ\u0004שפת ה\u0003קרנות ועד\u0004 ה\u0003סובב כמה\u0004 טפחים \u0003הוי\u0004 \u0005[הריהו]?\u0006 \u0003עשרים וארבעה.\u0004 ומעתה, \u0003כמה\u0004 טפחים \u0003בציר\u0004 \u0005[חסר]\u0006 לעשרים וארבעה הטפחים הללו על מנת להגיע \u0003לפלגיה\u0004 \u0005[לחציו]\u0006 של ה\u0003מזבח,\u0004 שהוא שלושים טפחים? \u0003ששה\u0004 טפחים. \u0003ו\u0004אכן כך גם \u0003תנן\u0004 \u0005[שנינו]\u0006 בדין עולת העוף ש\u0003אם עשאה למטה מרגליו אפילו אמה אחת,\u0004 שהיא ששה טפחים — \u0003הריהי\u0004 \u0003כשרה,\u0004 שהרי עדיין ניתנו הדמים במחציתו העליונה של המזבח. ונמצא החשבון עולה יפה.","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 עתה את הכתוב? \u0003ב\u0004רוחב ה\u0003כניסה\u0004 של היסוד והסובב והקרנות אל תוך תחום המזבח, \u0003ו\u0004אולם \u0003מי מצית מוקמת לה\u0004 \u0005[האם אתה יכול להעמיד אותה]\u0006 \u0003בכניסה? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת מידות\u0005]\u0006 כי \u0005ה\u0006\u0003מזבח היה\u0004 עשוי כעין ריבוע על גבי ריבוע: מידותיו של הריבוע התחתון היו \u0003שלשים ושתים\u0004 אמה \u0003על שלשים ושתים\u0004 אמה, \u0003עלה\u0004 ריבוע זה לגובה \u0003אמה וכנס\u0004 (ונכנס) כלפי פנימה מכל צידיו ברוחב \u0003אמה\u0004 עד לתחילת בנין הריבוע שעל גביו — \u0003זהו\u0004 הנקרא \u0003יסוד\u0004 המזבח. \u0003נמצא\u0004 כי מידותיו של הריבוע השני הינן \u0003שלשים\u0004 אמה \u0003על שלשים\u0004 אמה.","ומעתה אם אכן רוחב כניסת היסוד הוא באמה בת חמישה טפחים, ולא ששה, נמצא איפוא שמידותיו של הריבוע השני, מעל היסוד אינן שלושים אמה על שלושים אמה, אלא \u0003שלשים\u0004 אמה \u0003ו\u0004עוד \u0003שני טפחים\u0004 (טפח נוסף מצד זה וטפח נוסף מצד זה) \u0003הוי\u0004 \u0005[הוא],\u0006 שהרי המזבח נמדד באמה בת ששה טפחים, ואם הכניסה של היסוד נמדדה באמה בת חמישה טפחים נמצא שרוחב המזבח פרט ליסוד הוא מאה ושמונים ושתים טפחים, שהם שלושים אמות וטפחיים.","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות על הסבר זה, שהרי שנינו עוד בהמשך אותה משנה כי הריבוע השני שבמזבח \u0003עלה\u0004 לגובה \u0003חמש\u0004 אמות, \u0003ו\u0004שם אף הוא \u0003כנס\u0004 כלפי פנים ברוחב \u0003אמה\u0004 עד לתחילת הריבוע שעל גביו. ו\u0003זהו\u0004 הריבוע השני, הוא המכונה \u0003סובב\u0004 (שבניגוד ליסוד, הקיף את כל צידי המזבח). \u0003נמצא\u0004 כי מידותיו של ריבוע זה הינן \u0003עשרים ושמונה\u0004 אמות \u0003על עשרים ושמונה\u0004 אמות. וכן יש לשאול: אם אמנם רוחב הכניסות של היסוד ושל הסובב הן באמה בת חמישה טפחים, נמצא איפוא שמידותיו של ריבוע זה \u0003עשרים ושמונה\u0004 אמות \u0003ו\u0004עוד \u0003ארבע טפחים הוי\u0004 \u0005[הוא],\u0006 שנים היתרים על אמת היסוד, ושנים היתרים על אמת הסובב!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בתירוץ השאלות הללו, כי אמנם אין אלה שלושים אמה מכוונות (מידותיו של היסוד) ועשרים ושמונה אמות (מידותיו של הסובב), שהרי נוספו עליהם שני טפחים (ביסוד), וארבעה טפחים (ביסוד ובסובב גם יחד). ואולם \u0003כיון\u0004 ש\u0003לא הוי\u0004 \u0005[שאין זה]\u0006 כדי מידת \u0003אמה\u0004 שלימה, לכך \u0003לא חשיב ליה\u0004 \u0005[לא חישב אותו\u0006 התנא במסכת מידות\u0005],\u0006 יש להקשות עוד: שהרי שנינו עוד באותה משנה כי מעל גבי ריבוע זה של הסובב, בארבע פינותיו, נבנו ריבועים בעלי חלל, לתוכם היו נכנסים דמים של הקרבנות הניתנים על קרן המזבח, והם הקרנות. וה\u0003מקום\u0004 של כל אחת \u0003מן ה\u0004\u0003קרנות\u0004 הללו הריהו \u0003אמה מזה\u0004 לאורך המזבח, \u0003ואמה מזה\u0004 לרוחבו. ו\u0003נמצא\u0004 איפוא שמידתו של השטח הפנוי שעל גבי גג המזבח, חוץ משטח הקרנות עצמן והשטח שביניהן הוא \u0003עשרים ושש\u0004 אמות \u0003על עשרים ושש\u0004 אמות. ואולם אם נפרש בכתוב זה כי רוחב הכניסות היה נמדד באמה בת חמישה טפחים (ואף הקרנות, היו אמה בת חמישה טפחים, כמפורש בה), נמצא איפוא כי יש ברוחב המזבח ששה טפחים יתרים על מספר האמות הנזכרות במשנה במסכת מידות, שנים ליסוד, שנים לסובב ושנים לקרנות.","ומעתה השטח הפנוי על גבי גג המזבח הוא לא עשרים ושש אמות על עשרים ושש אמות, אלא \u0003עשרין ושבע\u0004 אמות על עשרים ושבע אמות \u0003הוו\u0004 \u0005[היו],\u0006 שהרי זו אמה שלימה (ולא טפחים בודדים) הנוספת על הנאמר במשנה, ואותן לא \u0005היה התנא משמיט\u0006\u0005!\u0006 ומשיבים: \u0003אכן\u0004 \u0003לא דק\u0004 \u0005[לא דייק]\u0006 התנא, שראוי היה לשנות \"עשרים ושבע אמות על עשרים ושבע אמות\". וממשיכים ושואלים עוד ממה ששנינו באותה משנה, כי לפנים ממקום הקרנות היה מקום מיוחד המיועד להילוך רגלי הכהנים הסובבים את המערכה עצמה בשעת עבודה.","ומידת \u0003מקום הילוך רגלי הכהנים\u0004 שם היתה \u0003אמה מזה\u0004 לאורך, \u0003ואמה מזה\u0004 לרוחב. \u0003נמצא\u0004 איפוא כי השטח הפנוי שנותר על גג המזבח \u0003היה\u0004 \u0003עשרים וארבע\u0004 אמות \u0003על עשרים וארבע\u0004 אמות, והוא \u0003מקום המערכה\u0004 (מקום הקרבת הקרבנות). ויש לשאול, מאחר שללא מקום הילוך רגלי הכהנים היה השטח הפנוי עשרים ושבע אמות על עשרים ושבע אמות, עתה שהתמעט שטח זה באמה מכאן ואמה מכאן, הרי ששטח מקום המערכה \u0003עשרים וחמשה\u0004 אמות על עשרים וחמש אמות \u0003הואי\u0004 \u0005[הוא],\u0006 ולא עשרים וארבע אמות על עשרים וארבע אמות, כשנוי במשנה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בתשובה לשאלה זו כי \u0003הכא נמי\u0004 \u0005[כאן גם\u0006 \u0003כן]\u0004 \u0003לא דק\u0004 \u0005[לא דייק]\u0006 התנא בדבריו — אינך יכול לומר כן, \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 עוד בהמשך אותו כתוב שבספר יחזקאל אודות מקום המערכה (\"האריאל\") עצמה: \u0003\"והאריאיל שתים עשרה ארך בשתים עשרה רחב רבוע\u0004 אל ארבעת רבעיו\" (יחזקאל מג, טז). \u0003יכול\u0004 הוא באמת כך, \u0003ש\u0004מקום המערכה \u0003אינו אלא שתים עשרה\u0004 אמה \u0003על שתים עשרה\u0004 אמה בלבד? \u0003כשהוא,\u0004 הכתוב, שב ו\u0003אומר \"אל ארבעת רבעיו\"\u0004 — הרי זה \u0003מלמד שבאמצע\u0004 המזבח \u0003הוא מודד שתים עשרה אמה לכל רוח ורוח.\u0004 ונמצא ששטח מקום המערכה הריהו עשרים וארבע אמות על עשרים וארבע אמות, ולא עשרים וחמש אמות על עשרים וחמש אמות!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בתשובה לשאלה זו כי לא כל שלושים ושתים האמות על שלושים ושתים האמות (שבבסיס המזבח) היו שוות במידותיהן, אלא שעשרים ושש מהן אכן היו של ששה טפחים, ואולם \u0003שית\u0004 \u0005[שש]\u0006 אמות \u0003מינייהו מעיקרא\u0004 \u0005[מהן, מתחילה,\u0006 בבסיס המזבח\u0005]\u0006 ש\u0003באמה בת חמשה\u0004 טפחים \u0003מייתי להו\u0004 \u0005[מביא,\u0006 מדד \u0005אותן]\u0006 — יש לדחות תשובה זו, שהרי \u0003אם כן\u0004 נאמר, נמצא כי שטח בסיס המזבח הוא מאה ושמונים וששה טפחים שהם לא שלושים ושתים אמה על שלושים ושתים אמה, אלא שלושים ואחת אמה על שלושים ואחת אמה, ומעתה איפוא \u0003רווחא\u0004 \u0005[התרחבה]\u0006 \u0003לה\u0004 ה\u0003עזרה\u0004 (בה עומד המזבח) באמה נוספת.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת מידות\u0005]:\u0006 \u0003כל העזרה\u0004 מתחילת עזרת ישראל ועד לאחורי בית קודש הקדשים \u0003היתה אורך\u0004 מן המזרח למערב \u0003מאה ושמונים ושבע\u0004 אמה \u0003על רוחב\u0004 מן הצפון לדרום \u0003מאה ושלשים וחמש\u0004 אמה. ומפרטים: כיצד אורך העזרה \u0003ממזרח למערב\u0004 הוא \u0003מאה שמונים ושבע\u0004 אמות: עזרת ישראל, שהיא \u0003מקום דריסת רגלי ישראל\u0004 — \u0003אחת עשרה אמה\u0004 מתוך אורך העזרה כולה. \u0003ו\u0004לפנים ממנה עזרת כהנים, שהיא \u0003מקום דריסת רגלי הכהנים\u0004 (שאסור לישראל להיכנס לשם), ועד למקום המזבח — אף הוא \u0003אחת עשרה אמה.\u0004 אורך \u0003המזבח\u0004 עצמו — \u0003שלשים ושתים\u0004 אמה. \u0003בין אולם ולמזבח\u0004 — עוד \u0003עשרים ושתים אמה. ההיכל\u0004 (וקודש הקדשים בכללו) — \u0003מאה אמה.\u0004 ועוד \u0003אחת עשרה אמה\u0004 נוספים מחוץ להיכל \u0003ל\u0004\u0003אחורי בית הכפורת.\u0004 ונמצא אם כן אורך כל העזרה מאה ושמונים ושבע אמות, ואולם לפי דבריך, אורך העזרה הוא מאה שמונים ושמונה אמות!","\u0003אלא\u0004 חוזרים אף מדרך פירוש זו של הכתוב ביחזקאל (מג, יג), ומציעים לפרש כך את הכתוב: \u0003\"חיק האמה\"\u0004 — דיבר הכתוב \u0003ב\u0004שיעור \u0003גובהה\u0004 של האמה שביסוד. \u0003\"אמה רחב\"\u0004 — דיבר הכתוב בשיעור ה\u0003כניסה\u0004 של הסובב. \u0003\"גבולה אל שפתה סביב\"\u0004 —"]]};
